UPDATE public.dictionary_words SET example_hanzi = '隔壁的阿姨常常送我們水果。', example_pinyin = 'gé bì de ā yí cháng cháng sòng wǒ men shuǐ guǒ。', example_vietnamese = 'Cô hàng xóm thường mang trái cây cho chúng tôi.' WHERE level = 'B1' AND hanzi = '阿姨' AND pinyin = 'āyí' AND vietnamese = 'Dì, cô';
UPDATE public.dictionary_words SET example_hanzi = '哎，你怎麼又遲到了？', example_pinyin = 'āi， nǐ zěn me yòu chí dào le？', example_vietnamese = 'Ơ kìa, sao cậu lại đến muộn nữa rồi?' WHERE level = 'B1' AND hanzi = '哎' AND pinyin = 'āi' AND vietnamese = 'Chao ôi, ơ kìa';
UPDATE public.dictionary_words SET example_hanzi = '唉，這次考試我又沒考好。', example_pinyin = 'āi， zhè cì kǎo shì wǒ yòu méi kǎo hǎo。', example_vietnamese = 'Hừ, lần thi này tôi lại không làm tốt.' WHERE level = 'B1' AND hanzi = '唉' AND pinyin = 'āi' AND vietnamese = 'Hừ (thán từ, tỏ ý ái ngại/thở dài)';
UPDATE public.dictionary_words SET example_hanzi = '父母對孩子的愛是無條件的。', example_pinyin = 'fù mǔ duì hái zi de ài shì wú tiáo jiàn de。', example_vietnamese = 'Tình yêu của cha mẹ dành cho con cái là vô điều kiện.' WHERE level = 'B1' AND hanzi = '愛' AND pinyin = 'ài' AND vietnamese = 'Yêu';
UPDATE public.dictionary_words SET example_hanzi = '他們的愛情經過了很多考驗。', example_pinyin = 'tā men de ài qíng jīng guò le hěn duō kǎo yàn。', example_vietnamese = 'Tình yêu của họ đã trải qua nhiều thử thách.' WHERE level = 'B1' AND hanzi = '愛情' AND pinyin = 'àiqíng' AND vietnamese = 'Tình yêu';
UPDATE public.dictionary_words SET example_hanzi = '我們應該愛惜身邊的每一分資源。', example_pinyin = 'wǒ men yīng gāi ài xī shēn biān de měi yī fēn zī yuán。', example_vietnamese = 'Chúng ta nên biết quý trọng từng nguồn tài nguyên xung quanh mình.' WHERE level = 'B1' AND hanzi = '愛惜' AND pinyin = 'àixí' AND vietnamese = 'Yêu quý, quý trọng';
UPDATE public.dictionary_words SET example_hanzi = '他常常捐錢，是個很有愛心的人。', example_pinyin = 'tā cháng cháng juān qián， shì gè hěn yǒu ài xīn de rén。', example_vietnamese = 'Anh ấy thường xuyên quyên góp tiền, là người rất giàu lòng nhân ái.' WHERE level = 'B1' AND hanzi = '愛心' AND pinyin = 'àixīn' AND vietnamese = 'Tình yêu/ biểu tượng trái tim';
UPDATE public.dictionary_words SET example_hanzi = '戰爭結束後，人民的生活漸漸安定下來。', example_pinyin = 'zhàn zhēng jié shù hòu， rén mín de shēng huó jiàn jiàn ān dìng xià lái。', example_vietnamese = 'Sau khi chiến tranh kết thúc, cuộc sống của người dân dần dần ổn định trở lại.' WHERE level = 'B1' AND hanzi = '安定' AND pinyin = 'āndìng' AND vietnamese = 'ổn định, yên ổn';
UPDATE public.dictionary_words SET example_hanzi = '這次旅行的安排非常周到。', example_pinyin = 'zhè cì lǚ xíng de ān pái fēi cháng zhōu dào。', example_vietnamese = 'Việc sắp xếp cho chuyến đi lần này rất chu đáo.' WHERE level = 'B1' AND hanzi = '安排' AND pinyin = 'ānpái' AND vietnamese = 'Sự sắp xếp';
UPDATE public.dictionary_words SET example_hanzi = '老師已經安排好下星期的考試時間。', example_pinyin = 'lǎo shī yǐ jīng ān pái hǎo xià xīng qī de kǎo shì shí jiān。', example_vietnamese = 'Thầy giáo đã sắp xếp xong thời gian thi tuần sau.' WHERE level = 'B1' AND hanzi = '安排' AND pinyin = 'ānpái' AND vietnamese = 'Sắp đặt, sắp xếp';
UPDATE public.dictionary_words SET example_hanzi = '聽到女兒平安到家，媽媽終於安心了。', example_pinyin = 'tīng dào nǚ ér píng ān dào jiā， mā ma zhōng yú ān xīn le。', example_vietnamese = 'Nghe tin con gái về nhà an toàn, mẹ cuối cùng cũng yên tâm.' WHERE level = 'B1' AND hanzi = '安心' AND pinyin = 'ānxīn' AND vietnamese = 'Rắp tâm, mưu tính';
UPDATE public.dictionary_words SET example_hanzi = '請按規定填寫這張表格。', example_pinyin = 'qǐng àn guī dìng tián xiě zhè zhāng biǎo gé。', example_vietnamese = 'Xin vui lòng điền vào biểu mẫu này theo quy định.' WHERE level = 'B1' AND hanzi = '按' AND pinyin = 'àn' AND vietnamese = 'Theo, dựa vào…';
UPDATE public.dictionary_words SET example_hanzi = '我們應該按照計畫進行。', example_pinyin = 'wǒ men yīng gāi àn zhào jì huà jìn xíng。', example_vietnamese = 'Chúng ta nên tiến hành theo đúng kế hoạch.' WHERE level = 'B1' AND hanzi = '按照' AND pinyin = 'ànzhào' AND vietnamese = 'Dựa theo, căn cứ theo…';
UPDATE public.dictionary_words SET example_hanzi = '我每天搭巴士上班。', example_pinyin = 'wǒ měi tiān dā bā shì shàng bān。', example_vietnamese = 'Mỗi ngày tôi đi xe buýt đến chỗ làm.' WHERE level = 'B1' AND hanzi = '巴士' AND pinyin = 'bāshì' AND vietnamese = 'Xe buýt';
UPDATE public.dictionary_words SET example_hanzi = '桌上放著一把傘。', example_pinyin = 'zhuō shàng fàng zhe yī bǎ sǎn。', example_vietnamese = 'Trên bàn có đặt một cây ô.' WHERE level = 'B1' AND hanzi = '把' AND pinyin = 'bǎ' AND vietnamese = 'Cán, quai, tay cầm, cuống';
UPDATE public.dictionary_words SET example_hanzi = '這次比賽他很有把握贏。', example_pinyin = 'zhè cì bǐ sài tā hěn yǒu bǎ wò yíng。', example_vietnamese = 'Trận thi đấu lần này anh ấy rất tự tin sẽ thắng.' WHERE level = 'B1' AND hanzi = '把握' AND pinyin = 'băwò' AND vietnamese = 'Cầm, nắm, nắm bắt';
UPDATE public.dictionary_words SET example_hanzi = '她穿了一件白色的洋裝。', example_pinyin = 'tā chuān le yī jiàn bái sè de yáng zhuāng。', example_vietnamese = 'Cô ấy mặc một chiếc váy màu trắng.' WHERE level = 'B1' AND hanzi = '白' AND pinyin = 'bái' AND vietnamese = 'Trắng';
UPDATE public.dictionary_words SET example_hanzi = '沒帶鑰匙，白跑了一趟。', example_pinyin = 'méi dài yào shi， bái pǎo le yī tàng。', example_vietnamese = 'Không mang chìa khóa, thế là chạy một chuyến vô ích.' WHERE level = 'B1' AND hanzi = '白' AND pinyin = 'bái(bái)' AND vietnamese = 'Vô ích';
UPDATE public.dictionary_words SET example_hanzi = '媽媽買了一顆白菜回來煮湯。', example_pinyin = 'mā ma mǎi le yī kē bái cài huí lái zhǔ tāng。', example_vietnamese = 'Mẹ mua một cây cải trắng về nấu canh.' WHERE level = 'B1' AND hanzi = '白菜' AND pinyin = 'báicài' AND vietnamese = 'Cải trắng';
UPDATE public.dictionary_words SET example_hanzi = '他白天上班，晚上上課。', example_pinyin = 'tā bái tiān shàng bān， wǎn shàng shàng kè。', example_vietnamese = 'Ban ngày anh ấy đi làm, buổi tối thì đi học.' WHERE level = 'B1' AND hanzi = '白天' AND pinyin = 'báitian' AND vietnamese = 'Ban ngày';
UPDATE public.dictionary_words SET example_hanzi = '她把花瓶擺在桌子中間。', example_pinyin = 'tā bǎ huā píng bǎi zài zhuō zi zhōng jiān。', example_vietnamese = 'Cô ấy đặt bình hoa ở giữa bàn.' WHERE level = 'B1' AND hanzi = '擺' AND pinyin = 'băi' AND vietnamese = 'Xếp đặt, bày biện';
UPDATE public.dictionary_words SET example_hanzi = '週末我們去百貨公司買衣服。', example_pinyin = 'zhōu mò wǒ men qù bǎi huò gōng sī mǎi yī fu。', example_vietnamese = 'Cuối tuần chúng tôi đi mua quần áo ở trung tâm bách hóa.' WHERE level = 'B1' AND hanzi = '百貨公司' AND pinyin = 'băihuògōngsī' AND vietnamese = 'Công ty bách hóa';
UPDATE public.dictionary_words SET example_hanzi = '我們的班機延誤了兩個小時。', example_pinyin = 'wǒ men de bān jī yán wù le liǎng gè xiǎo shí。', example_vietnamese = 'Chuyến bay của chúng tôi bị trễ hai tiếng đồng hồ.' WHERE level = 'B1' AND hanzi = '班機' AND pinyin = 'bānjī' AND vietnamese = 'Chuyến bay';
UPDATE public.dictionary_words SET example_hanzi = '下個月我們就要搬家了。', example_pinyin = 'xià gè yuè wǒ men jiù yào bān jiā le。', example_vietnamese = 'Tháng sau chúng tôi sẽ chuyển nhà.' WHERE level = 'B1' AND hanzi = '搬家' AND pinyin = 'bānjiā' AND vietnamese = 'Dọn nhà, chuyển nhà';
UPDATE public.dictionary_words SET example_hanzi = '這件事情交給我來辦。', example_pinyin = 'zhè jiàn shì qíng jiāo gěi wǒ lái bàn。', example_vietnamese = 'Việc này cứ để tôi lo liệu.' WHERE level = 'B1' AND hanzi = '辦' AND pinyin = 'bàn' AND vietnamese = 'Xử lý, lo liệu';
UPDATE public.dictionary_words SET example_hanzi = '請到櫃檯辦理入住手續。', example_pinyin = 'qǐng dào guì tái bàn lǐ rù zhù shǒu xù。', example_vietnamese = 'Xin mời đến quầy để làm thủ tục nhận phòng.' WHERE level = 'B1' AND hanzi = '辦理' AND pinyin = 'bànlĭ' AND vietnamese = 'Giải quyết, thực hiện';
UPDATE public.dictionary_words SET example_hanzi = '我找了半天才找到鑰匙。', example_pinyin = 'wǒ zhǎo le bàn tiān cái zhǎo dào yào shi。', example_vietnamese = 'Tôi tìm mãi cả buổi mới thấy chìa khóa.' WHERE level = 'B1' AND hanzi = '半天' AND pinyin = 'bàntiān' AND vietnamese = 'Nửa ngày';
UPDATE public.dictionary_words SET example_hanzi = '他半夜突然醒來，肚子好餓。', example_pinyin = 'tā bàn yè tū rán xǐng lái， dù zi hǎo è。', example_vietnamese = 'Anh ấy nửa đêm bỗng nhiên tỉnh dậy, bụng đói cồn cào.' WHERE level = 'B1' AND hanzi = '半夜' AND pinyin = 'bànyè' AND vietnamese = 'Nửa đêm';
UPDATE public.dictionary_words SET example_hanzi = '謝謝你在我困難的時候幫助我。', example_pinyin = 'xiè xie nǐ zài wǒ kùn nán de shí hou bāng zhù wǒ。', example_vietnamese = 'Cảm ơn bạn đã giúp đỡ tôi lúc khó khăn.' WHERE level = 'B1' AND hanzi = '幫助' AND pinyin = 'bāngzhù' AND vietnamese = 'Giúp đỡ';
UPDATE public.dictionary_words SET example_hanzi = '他一直是我學習的榜樣。', example_pinyin = 'tā yī zhí shì wǒ xué xí de bǎng yàng。', example_vietnamese = 'Anh ấy luôn là tấm gương để tôi noi theo.' WHERE level = 'B1' AND hanzi = '榜樣' AND pinyin = 'băngyàng' AND vietnamese = 'Tấm gương';
UPDATE public.dictionary_words SET example_hanzi = '你的中文說得真棒！', example_pinyin = 'nǐ de zhōng wén shuō de zhēn bàng！', example_vietnamese = 'Bạn nói tiếng Trung giỏi thật đấy!' WHERE level = 'B1' AND hanzi = '棒' AND pinyin = 'bàng' AND vietnamese = 'Tốt, giỏi';
UPDATE public.dictionary_words SET example_hanzi = '她把禮物包得很漂亮。', example_pinyin = 'tā bǎ lǐ wù bāo de hěn piào liang。', example_vietnamese = 'Cô ấy gói món quà rất đẹp.' WHERE level = 'B1' AND hanzi = '包' AND pinyin = 'bāo' AND vietnamese = 'Bao lại, gói lại';
UPDATE public.dictionary_words SET example_hanzi = '這個價格包含早餐和稅金。', example_pinyin = 'zhè ge jià gé bāo hán zǎo cān hé shuì jīn。', example_vietnamese = 'Mức giá này đã bao gồm bữa sáng và thuế.' WHERE level = 'B1' AND hanzi = '包含' AND pinyin = 'bāohán' AND vietnamese = 'Bao hàm, hàm chứa';
UPDATE public.dictionary_words SET example_hanzi = '這個玩具是他最珍惜的寶貝。', example_pinyin = 'zhè ge wán jù shì tā zuì zhēn xī de bǎo bèi。', example_vietnamese = 'Món đồ chơi này là bảo bối mà cậu ấy quý nhất.' WHERE level = 'B1' AND hanzi = '寶貝' AND pinyin = 'băobèi' AND vietnamese = 'Bảo bối, cục cưng';
UPDATE public.dictionary_words SET example_hanzi = '時間是我們最寶貴的資源。', example_pinyin = 'shí jiān shì wǒ men zuì bǎo guì de zī yuán。', example_vietnamese = 'Thời gian là nguồn tài nguyên quý giá nhất của chúng ta.' WHERE level = 'B1' AND hanzi = '寶貴' AND pinyin = 'băoguì' AND vietnamese = 'Quý giá, quý báu';
UPDATE public.dictionary_words SET example_hanzi = '我們每個人都應該保護環境。', example_pinyin = 'wǒ men měi gè rén dōu yīng gāi bǎo hù huán jìng。', example_vietnamese = 'Mỗi người trong chúng ta đều nên bảo vệ môi trường.' WHERE level = 'B1' AND hanzi = '保護' AND pinyin = 'băohù' AND vietnamese = 'Bảo vệ, giữ gìn';
UPDATE public.dictionary_words SET example_hanzi = '他的想法比較保守，不喜歡冒險。', example_pinyin = 'tā de xiǎng fǎ bǐ jiào bǎo shǒu， bù xǐ huan mào xiǎn。', example_vietnamese = 'Suy nghĩ của anh ấy khá bảo thủ, không thích mạo hiểm.' WHERE level = 'B1' AND hanzi = '保守' AND pinyin = 'băoshǒu' AND vietnamese = 'Tuân theo, tuân thủ';
UPDATE public.dictionary_words SET example_hanzi = '她每天都花時間保養皮膚。', example_pinyin = 'tā měi tiān dōu huā shí jiān bǎo yǎng pí fū。', example_vietnamese = 'Ngày nào cô ấy cũng dành thời gian chăm sóc da.' WHERE level = 'B1' AND hanzi = '保養' AND pinyin = 'băoyăng' AND vietnamese = 'Bảo dưỡng, chăm sóc';
