UPDATE public.dictionary_words SET example_hanzi = '媽媽輕輕地抱著剛出生的寶寶。', example_pinyin = 'mā ma qīng qīng de bào zhe gāng chū shēng de bǎo bao。', example_vietnamese = 'Mẹ nhẹ nhàng bế đứa bé mới sinh.' WHERE level = 'B1' AND hanzi = '抱' AND pinyin = 'bào' AND vietnamese = 'Bế, bồng, ôm';
UPDATE public.dictionary_words SET example_hanzi = '他總是抱怨工作太累。', example_pinyin = 'tā zǒng shì bào yuàn gōng zuò tài lèi。', example_vietnamese = 'Anh ấy lúc nào cũng than phiền công việc quá vất vả.' WHERE level = 'B1' AND hanzi = '抱怨' AND pinyin = 'bàoyuàn' AND vietnamese = 'Oán hận, oán trách';
UPDATE public.dictionary_words SET example_hanzi = '我已經幫你報名這次的比賽了。', example_pinyin = 'wǒ yǐ jīng bāng nǐ bào míng zhè cì de bǐ sài le。', example_vietnamese = 'Tôi đã đăng ký giúp bạn cho cuộc thi lần này rồi.' WHERE level = 'B1' AND hanzi = '報名' AND pinyin = 'bàomíng' AND vietnamese = 'Đăng ký, ghi danh';
UPDATE public.dictionary_words SET example_hanzi = '他背著一個大背包去旅行。', example_pinyin = 'tā bēi zhe yī gè dà bēi bāo qù lǚ xíng。', example_vietnamese = 'Anh ấy đeo một chiếc ba lô lớn đi du lịch.' WHERE level = 'B1' AND hanzi = '背包' AND pinyin = 'bēibāo' AND vietnamese = 'Ba lô, túi đeo vai';
UPDATE public.dictionary_words SET example_hanzi = '北方的冬天特別冷。', example_pinyin = 'běi fāng de dōng tiān tè bié lěng。', example_vietnamese = 'Mùa đông ở phương Bắc đặc biệt lạnh.' WHERE level = 'B1' AND hanzi = '北方' AND pinyin = 'běifāng' AND vietnamese = 'Phương Bắc';
UPDATE public.dictionary_words SET example_hanzi = '他在感情裡總是很被動。', example_pinyin = 'tā zài gǎn qíng lǐ zǒng shì hěn bèi dòng。', example_vietnamese = 'Trong tình cảm anh ấy lúc nào cũng rất bị động.' WHERE level = 'B1' AND hanzi = '被動' AND pinyin = 'bèidòng' AND vietnamese = 'Bị động';
UPDATE public.dictionary_words SET example_hanzi = '別在背後說別人的壞話。', example_pinyin = 'bié zài bèi hòu shuō bié rén de huài huà。', example_vietnamese = 'Đừng nói xấu người khác sau lưng họ.' WHERE level = 'B1' AND hanzi = '背後' AND pinyin = 'bèihòu' AND vietnamese = 'Phía sau';
UPDATE public.dictionary_words SET example_hanzi = '這張照片的背景是一片海。', example_pinyin = 'zhè zhāng zhào piàn de bèi jǐng shì yī piàn hǎi。', example_vietnamese = 'Phông nền của bức ảnh này là một vùng biển.' WHERE level = 'B1' AND hanzi = '背景' AND pinyin = 'bèijĭng' AND vietnamese = 'Phông nền, cảnh';
UPDATE public.dictionary_words SET example_hanzi = '他這輩子最快樂的事就是遇見你。', example_pinyin = 'tā zhè bèi zi zuì kuài lè de shì jiù shì yù jiàn nǐ。', example_vietnamese = 'Điều hạnh phúc nhất đời anh chính là gặp được em.' WHERE level = 'B1' AND hanzi = '輩子' AND pinyin = 'bèizi' AND vietnamese = 'Cuộc đời';
UPDATE public.dictionary_words SET example_hanzi = '我買了三本書。', example_pinyin = 'wǒ mǎi le sān běn shū。', example_vietnamese = 'Tôi đã mua ba cuốn sách.' WHERE level = 'B1' AND hanzi = '本' AND pinyin = 'běn' AND vietnamese = 'Gốc, thân';
UPDATE public.dictionary_words SET example_hanzi = '這件事需要本人親自簽名。', example_pinyin = 'zhè jiàn shì xū yào běn rén qīn zì qiān míng。', example_vietnamese = 'Việc này cần chính bản thân người đó ký tên.' WHERE level = 'B1' AND hanzi = '本人' AND pinyin = 'běnrén' AND vietnamese = 'Bản thân, tự mình';
UPDATE public.dictionary_words SET example_hanzi = '他隨身帶著一個小本子記事情。', example_pinyin = 'tā suí shēn dài zhe yī gè xiǎo běn zi jì shì qing。', example_vietnamese = 'Anh ấy luôn mang theo một cuốn sổ nhỏ để ghi chép.' WHERE level = 'B1' AND hanzi = '本子' AND pinyin = 'běnzi' AND vietnamese = 'Cuốn vở';
UPDATE public.dictionary_words SET example_hanzi = '我不是笨，只是還沒學會而已。', example_pinyin = 'wǒ bú shì bèn， zhǐ shì hái méi xué huì ér yǐ。', example_vietnamese = 'Tôi không ngốc, chỉ là chưa học được thôi.' WHERE level = 'B1' AND hanzi = '笨' AND pinyin = 'bèn' AND vietnamese = 'Ngốc nghếch';
UPDATE public.dictionary_words SET example_hanzi = '別逼他做他不願意的事。', example_pinyin = 'bié bī tā zuò tā bú yuàn yì de shì。', example_vietnamese = 'Đừng ép anh ấy làm việc mà anh ấy không muốn.' WHERE level = 'B1' AND hanzi = '逼' AND pinyin = 'bī' AND vietnamese = 'Dồn ép';
UPDATE public.dictionary_words SET example_hanzi = '這支筆寫起來很順手。', example_pinyin = 'zhè zhī bǐ xiě qǐ lái hěn shùn shǒu。', example_vietnamese = 'Cây bút này viết rất thuận tay.' WHERE level = 'B1' AND hanzi = '筆' AND pinyin = 'bĭ' AND vietnamese = 'Bút';
UPDATE public.dictionary_words SET example_hanzi = '今天比昨天冷多了。', example_pinyin = 'jīn tiān bǐ zuó tiān lěng duō le。', example_vietnamese = 'Hôm nay lạnh hơn hôm qua nhiều.' WHERE level = 'B1' AND hanzi = '比' AND pinyin = 'bǐ' AND vietnamese = 'So sánh, so với';
UPDATE public.dictionary_words SET example_hanzi = '有些水果，比如說芒果，我特別喜歡。', example_pinyin = 'yǒu xiē shuǐ guǒ， bǐ rú shuō máng guǒ， wǒ tè bié xǐ huan。', example_vietnamese = 'Có một số loại trái cây, ví dụ như xoài, tôi đặc biệt thích.' WHERE level = 'B1' AND hanzi = '比如(說)' AND pinyin = 'bǐrú(shuō)' AND vietnamese = 'Ví dụ như';
UPDATE public.dictionary_words SET example_hanzi = '畢竟他還是個孩子，別對他太嚴格。', example_pinyin = 'bì jìng tā hái shì gè hái zi， bié duì tā tài yán gé。', example_vietnamese = 'Suy cho cùng nó vẫn còn là một đứa trẻ, đừng quá nghiêm khắc với nó.' WHERE level = 'B1' AND hanzi = '畢竟' AND pinyin = 'bìjìng' AND vietnamese = 'Rốt cuộc, suy cho cùng';
UPDATE public.dictionary_words SET example_hanzi = '開車時要避免使用手機。', example_pinyin = 'kāi chē shí yào bì miǎn shǐ yòng shǒu jī。', example_vietnamese = 'Khi lái xe cần tránh sử dụng điện thoại.' WHERE level = 'B1' AND hanzi = '避免' AND pinyin = 'bìmiăn' AND vietnamese = 'Tránh, phòng ngừa';
UPDATE public.dictionary_words SET example_hanzi = '沒有必要為了這種小事生氣。', example_pinyin = 'méi yǒu bì yào wèi le zhè zhǒng xiǎo shì shēng qì。', example_vietnamese = 'Không cần thiết phải nổi giận vì chuyện nhỏ nhặt như vậy.' WHERE level = 'B1' AND hanzi = '必要' AND pinyin = 'bìyào' AND vietnamese = 'Cần thiết';
UPDATE public.dictionary_words SET example_hanzi = '過年的時候，大家都喜歡放鞭炮。', example_pinyin = 'guò nián de shí hou， dà jiā dōu xǐ huan fàng biān pào。', example_vietnamese = 'Vào dịp Tết, mọi người đều thích đốt pháo.' WHERE level = 'B1' AND hanzi = '鞭炮' AND pinyin = 'biānpào' AND vietnamese = 'Pháo, bánh pháo';
UPDATE public.dictionary_words SET example_hanzi = '這幾年城市變了很多。', example_pinyin = 'zhè jǐ nián chéng shì biàn le hěn duō。', example_vietnamese = 'Mấy năm nay thành phố đã thay đổi rất nhiều.' WHERE level = 'B1' AND hanzi = '變' AND pinyin = 'biàn' AND vietnamese = 'Thay đổi';
UPDATE public.dictionary_words SET example_hanzi = '毛毛蟲最後會變成蝴蝶。', example_pinyin = 'máo mao chóng zuì hòu huì biàn chéng hú dié。', example_vietnamese = 'Cuối cùng sâu bướm sẽ biến thành bươm bướm.' WHERE level = 'B1' AND hanzi = '變成' AND pinyin = 'biànchéng' AND vietnamese = 'Biến thành, trở thành';
UPDATE public.dictionary_words SET example_hanzi = '班機時間臨時變更了。', example_pinyin = 'bān jī shí jiān lín shí biàn gēng le。', example_vietnamese = 'Giờ bay đã bị thay đổi đột xuất.' WHERE level = 'B1' AND hanzi = '變更' AND pinyin = 'biàngēng' AND vietnamese = 'Thay đổi, biến đổi';
UPDATE public.dictionary_words SET example_hanzi = '這一年他的生活有很大的變化。', example_pinyin = 'zhè yī nián tā de shēng huó yǒu hěn dà de biàn huà。', example_vietnamese = 'Năm nay cuộc sống của anh ấy có sự thay đổi rất lớn.' WHERE level = 'B1' AND hanzi = '變化' AND pinyin = 'biànhuà' AND vietnamese = 'Sự thay đổi';
UPDATE public.dictionary_words SET example_hanzi = '山上的天氣變化很快。', example_pinyin = 'shān shàng de tiān qì biàn huà hěn kuài。', example_vietnamese = 'Thời tiết trên núi thay đổi rất nhanh.' WHERE level = 'B1' AND hanzi = '變化' AND pinyin = 'biànhuà' AND vietnamese = 'Biến hóa';
UPDATE public.dictionary_words SET example_hanzi = '他在桌上留了一張便條給我。', example_pinyin = 'tā zài zhuō shàng liú le yī zhāng biàn tiáo gěi wǒ。', example_vietnamese = 'Anh ấy để lại cho tôi một tờ giấy ghi chú trên bàn.' WHERE level = 'B1' AND hanzi = '便條' AND pinyin = 'biàntiáo' AND vietnamese = 'Giấy ghi chú';
UPDATE public.dictionary_words SET example_hanzi = '每個人對美的標準都不一樣。', example_pinyin = 'měi gè rén duì měi de biāo zhǔn dōu bù yī yàng。', example_vietnamese = 'Mỗi người có tiêu chuẩn về cái đẹp khác nhau.' WHERE level = 'B1' AND hanzi = '標準' AND pinyin = 'biāozhŭn' AND vietnamese = 'Chuẩn mực';
UPDATE public.dictionary_words SET example_hanzi = '他的發音很標準。', example_pinyin = 'tā de fā yīn hěn biāo zhǔn。', example_vietnamese = 'Phát âm của anh ấy rất chuẩn.' WHERE level = 'B1' AND hanzi = '標準' AND pinyin = 'biāozhŭn' AND vietnamese = 'Tiêu chuẩn';
UPDATE public.dictionary_words SET example_hanzi = '請先填好這張表再交給我。', example_pinyin = 'qǐng xiān tián hǎo zhè zhāng biǎo zài jiāo gěi wǒ。', example_vietnamese = 'Xin hãy điền xong biểu mẫu này rồi đưa lại cho tôi.' WHERE level = 'B1' AND hanzi = '表' AND pinyin = 'biǎo' AND vietnamese = 'Bề ngoài, mặt ngoài';
UPDATE public.dictionary_words SET example_hanzi = '她不太會表達自己的感受。', example_pinyin = 'tā bú tài huì biǎo dá zì jǐ de gǎn shòu。', example_vietnamese = 'Cô ấy không giỏi bày tỏ cảm xúc của mình.' WHERE level = 'B1' AND hanzi = '表達' AND pinyin = 'biăodá' AND vietnamese = 'Bày tỏ';
UPDATE public.dictionary_words SET example_hanzi = '這張桌子的表面很光滑。', example_pinyin = 'zhè zhāng zhuō zi de biǎo miàn hěn guāng huá。', example_vietnamese = 'Mặt bàn này rất nhẵn bóng.' WHERE level = 'B1' AND hanzi = '表面' AND pinyin = 'biăomiàn' AND vietnamese = 'Mặt ngoài, phía ngoài';
UPDATE public.dictionary_words SET example_hanzi = '他點點頭，表示同意。', example_pinyin = 'tā diǎn diǎn tóu， biǎo shì tóng yì。', example_vietnamese = 'Anh ấy gật đầu, tỏ ý đồng ý.' WHERE level = 'B1' AND hanzi = '表示' AND pinyin = 'biăoshì' AND vietnamese = 'Biểu thị, tỏ ý';
UPDATE public.dictionary_words SET example_hanzi = '這次考試他的表現讓老師很滿意。', example_pinyin = 'zhè cì kǎo shì tā de biǎo xiàn ràng lǎo shī hěn mǎn yì。', example_vietnamese = 'Kết quả thể hiện của cậu ấy trong kỳ thi này khiến thầy giáo rất hài lòng.' WHERE level = 'B1' AND hanzi = '表現' AND pinyin = 'biǎoxiàn' AND vietnamese = 'Biểu hiện';
UPDATE public.dictionary_words SET example_hanzi = '他在比賽中表現得非常出色。', example_pinyin = 'tā zài bǐ sài zhōng biǎo xiàn de fēi cháng chū sè。', example_vietnamese = 'Anh ấy thể hiện vô cùng xuất sắc trong cuộc thi.' WHERE level = 'B1' AND hanzi = '表現' AND pinyin = 'biǎoxiàn' AND vietnamese = 'Thể hiện, tỏ ra';
UPDATE public.dictionary_words SET example_hanzi = '學生們在晚會上表演了一段舞蹈。', example_pinyin = 'xué sheng men zài wǎn huì shàng biǎo yǎn le yī duàn wǔ dǎo。', example_vietnamese = 'Các em học sinh đã biểu diễn một tiết mục múa trong buổi dạ hội.' WHERE level = 'B1' AND hanzi = '表演' AND pinyin = 'biǎoyǎn' AND vietnamese = 'Biểu diễn';
UPDATE public.dictionary_words SET example_hanzi = '這個顏色我不喜歡，有別的嗎？', example_pinyin = 'zhè ge yán sè wǒ bù xǐ huan， yǒu bié de ma？', example_vietnamese = 'Màu này tôi không thích, có màu khác không?' WHERE level = 'B1' AND hanzi = '別的' AND pinyin = 'biéde' AND vietnamese = 'Cái khác';
UPDATE public.dictionary_words SET example_hanzi = '天氣太熱了，我想喝一杯加冰的飲料。', example_pinyin = 'tiān qì tài rè le， wǒ xiǎng hē yī bēi jiā bīng de yǐn liào。', example_vietnamese = 'Trời nóng quá, tôi muốn uống một ly nước có đá.' WHERE level = 'B1' AND hanzi = '冰' AND pinyin = 'bīng' AND vietnamese = 'Đá, băng';
UPDATE public.dictionary_words SET example_hanzi = '服務生幫我在杯子裡加了幾塊冰塊。', example_pinyin = 'fú wù shēng bāng wǒ zài bēi zi lǐ jiā le jǐ kuài bīng kuài。', example_vietnamese = 'Người phục vụ đã thêm vài viên đá vào ly cho tôi.' WHERE level = 'B1' AND hanzi = '冰塊' AND pinyin = 'bīngkuài/bīngkuàir' AND vietnamese = 'Viên đá, khối đá';
UPDATE public.dictionary_words SET example_hanzi = '奶奶做的月餅特別好吃。', example_pinyin = 'nǎi nai zuò de yuè bǐng tè bié hǎo chī。', example_vietnamese = 'Bánh trung thu bà làm đặc biệt ngon.' WHERE level = 'B1' AND hanzi = '餅' AND pinyin = 'bǐng' AND vietnamese = 'Bánh';
UPDATE public.dictionary_words SET example_hanzi = '他這幾天感冒生病了。', example_pinyin = 'tā zhè jǐ tiān gǎn mào bìng le。', example_vietnamese = 'Mấy hôm nay anh ấy bị cảm và ốm.' WHERE level = 'B1' AND hanzi = '病' AND pinyin = 'bìng' AND vietnamese = 'Bệnh, ốm đau';
UPDATE public.dictionary_words SET example_hanzi = '隔壁的伯伯每天早上都去公園運動。', example_pinyin = 'gé bì de bó bo měi tiān zǎo shang dōu qù gōng yuán yùn dòng。', example_vietnamese = 'Bác trai hàng xóm sáng nào cũng ra công viên tập thể dục.' WHERE level = 'B1' AND hanzi = '伯伯' AND pinyin = 'bóbo' AND vietnamese = 'Bác trai';
UPDATE public.dictionary_words SET example_hanzi = '他去年拿到了博士學位。', example_pinyin = 'tā qù nián ná dào le bó shì xué wèi。', example_vietnamese = 'Năm ngoái anh ấy đã lấy được bằng tiến sĩ.' WHERE level = 'B1' AND hanzi = '博士' AND pinyin = 'bóshì' AND vietnamese = 'Tiến sĩ';
UPDATE public.dictionary_words SET example_hanzi = '這個消息很快就傳播開了。', example_pinyin = 'zhè ge xiāo xi hěn kuài jiù chuán bō kāi le。', example_vietnamese = 'Tin tức này rất nhanh đã được lan truyền đi.' WHERE level = 'B1' AND hanzi = '播' AND pinyin = 'bò' AND vietnamese = 'Truyền bá';
UPDATE public.dictionary_words SET example_hanzi = '你不必為這件小事道歉。', example_pinyin = 'nǐ bú bì wèi zhè jiàn xiǎo shì dào qiàn。', example_vietnamese = 'Bạn không cần phải xin lỗi vì chuyện nhỏ này.' WHERE level = 'B1' AND hanzi = '不必' AND pinyin = 'bùbì' AND vietnamese = 'Không cần, khỏi phải';
UPDATE public.dictionary_words SET example_hanzi = '他不斷地努力，終於成功了。', example_pinyin = 'tā bú duàn de nǔ lì， zhōng yú chéng gōng le。', example_vietnamese = 'Anh ấy không ngừng nỗ lực, cuối cùng đã thành công.' WHERE level = 'B1' AND hanzi = '不斷' AND pinyin = 'bùduàn' AND vietnamese = 'Không ngừng';
UPDATE public.dictionary_words SET example_hanzi = '這幾年科技進步不斷。', example_pinyin = 'zhè jǐ nián kē jì jìn bù bú duàn。', example_vietnamese = 'Mấy năm gần đây khoa học công nghệ tiến bộ liên tục.' WHERE level = 'B1' AND hanzi = '不斷' AND pinyin = 'bùduàn' AND vietnamese = 'Liên tục, liên tiếp';
UPDATE public.dictionary_words SET example_hanzi = '這不過是個小問題，別擔心。', example_pinyin = 'zhè bú guò shì gè xiǎo wèn tí， bié dān xīn。', example_vietnamese = 'Đây chẳng qua chỉ là một vấn đề nhỏ, đừng lo lắng.' WHERE level = 'B1' AND hanzi = '不過' AND pinyin = 'bùguò' AND vietnamese = 'Vừa mới';
UPDATE public.dictionary_words SET example_hanzi = '這件衣服很好看，不過有點貴。', example_pinyin = 'zhè jiàn yī fu hěn hǎo kàn， bú guò yǒu diǎn guì。', example_vietnamese = 'Chiếc áo này đẹp lắm, nhưng hơi đắt.' WHERE level = 'B1' AND hanzi = '不過' AND pinyin = 'bùguò' AND vietnamese = 'Nhưng';
UPDATE public.dictionary_words SET example_hanzi = '我的鑰匙不見了，你有看到嗎？', example_pinyin = 'wǒ de yào shi bú jiàn le， nǐ yǒu kàn dào ma？', example_vietnamese = 'Chìa khóa của tôi không thấy đâu nữa, bạn có nhìn thấy không?' WHERE level = 'B1' AND hanzi = '不見' AND pinyin = 'bùjiàn(le)' AND vietnamese = 'Không gặp, không thấy nữa';
UPDATE public.dictionary_words SET example_hanzi = '不論結果如何，我都會盡力而為。', example_pinyin = 'bú lùn jié guǒ rú hé， wǒ dōu huì jìn lì ér wéi。', example_vietnamese = 'Bất kể kết quả thế nào, tôi cũng sẽ cố gắng hết sức.' WHERE level = 'B1' AND hanzi = '不論' AND pinyin = 'bùlùn' AND vietnamese = 'Cho dù, bất luận';
UPDATE public.dictionary_words SET example_hanzi = '那場車禍讓這個家庭非常不幸。', example_pinyin = 'nà chǎng chē huò ràng zhè ge jiā tíng fēi cháng bú xìng。', example_vietnamese = 'Vụ tai nạn xe cộ đó khiến gia đình này vô cùng bất hạnh.' WHERE level = 'B1' AND hanzi = '不幸' AND pinyin = 'bùxìng' AND vietnamese = 'Bất hạnh';
UPDATE public.dictionary_words SET example_hanzi = '不用說，他一定又遲到了。', example_pinyin = 'bú yòng shuō， tā yī dìng yòu chí dào le。', example_vietnamese = 'Khỏi cần nói, chắc chắn anh ta lại đến muộn rồi.' WHERE level = 'B1' AND hanzi = '不用說' AND pinyin = 'bùyòngshuō' AND vietnamese = 'Không cần nói';
UPDATE public.dictionary_words SET example_hanzi = '因為下大雨，我們不得不取消計畫。', example_pinyin = 'yīn wèi xià dà yǔ， wǒ men bù dé bù qǔ xiāo jì huà。', example_vietnamese = 'Vì trời mưa to, chúng tôi buộc phải hủy kế hoạch.' WHERE level = 'B1' AND hanzi = '不得不' AND pinyin = 'bùdébù' AND vietnamese = 'Không thể không';
UPDATE public.dictionary_words SET example_hanzi = '今天熱得不得了，我快受不了了。', example_pinyin = 'jīn tiān rè de bù dé liǎo， wǒ kuài shòu bù liǎo le。', example_vietnamese = 'Hôm nay nóng khủng khiếp, tôi sắp chịu không nổi rồi.' WHERE level = 'B1' AND hanzi = '不得了' AND pinyin = 'bùdéliăo' AND vietnamese = 'Cực kỳ';
UPDATE public.dictionary_words SET example_hanzi = '不管你去不去，我都要出發了。', example_pinyin = 'bù guǎn nǐ qù bú qù， wǒ dōu yào chū fā le。', example_vietnamese = 'Dù bạn có đi hay không, tôi cũng sẽ xuất phát rồi.' WHERE level = 'B1' AND hanzi = '不管' AND pinyin = 'bùguǎn' AND vietnamese = 'Cho dù, bất kể';
UPDATE public.dictionary_words SET example_hanzi = '員工對新的規定感到不滿。', example_pinyin = 'yuán gōng duì xīn de guī dìng gǎn dào bù mǎn。', example_vietnamese = 'Nhân viên cảm thấy không hài lòng về quy định mới.' WHERE level = 'B1' AND hanzi = '不滿' AND pinyin = 'bùmăn' AND vietnamese = 'Không vừa lòng';
UPDATE public.dictionary_words SET example_hanzi = '與其在家等，不如出去找他。', example_pinyin = 'yǔ qí zài jiā děng， bù rú chū qù zhǎo tā。', example_vietnamese = 'Thay vì ngồi nhà chờ, chi bằng ra ngoài tìm anh ấy.' WHERE level = 'B1' AND hanzi = '不如' AND pinyin = 'bùrú' AND vietnamese = 'Không bằng';
UPDATE public.dictionary_words SET example_hanzi = '這個公司已經賺了不少錢。', example_pinyin = 'zhè ge gōng sī yǐ jīng zhuàn le bù shǎo qián。', example_vietnamese = 'Công ty này đã kiếm được không ít tiền.' WHERE level = 'B1' AND hanzi = '不少' AND pinyin = 'bùshǎo' AND vietnamese = 'Không ít';
UPDATE public.dictionary_words SET example_hanzi = '來參加婚禮的客人真不少。', example_pinyin = 'lái cān jiā hūn lǐ de kè rén zhēn bù shǎo。', example_vietnamese = 'Khách đến dự đám cưới thật là nhiều.' WHERE level = 'B1' AND hanzi = '不少' AND pinyin = 'bùshǎo' AND vietnamese = 'Nhiều';
UPDATE public.dictionary_words SET example_hanzi = '睡眠不足會影響健康。', example_pinyin = 'shuì mián bù zú huì yǐng xiǎng jiàn kāng。', example_vietnamese = 'Thiếu ngủ sẽ ảnh hưởng đến sức khỏe.' WHERE level = 'B1' AND hanzi = '不足' AND pinyin = 'bùzú' AND vietnamese = 'Không đủ';
UPDATE public.dictionary_words SET example_hanzi = '這部電影非常感人。', example_pinyin = 'zhè bù diàn yǐng fēi cháng gǎn rén。', example_vietnamese = 'Bộ phim này vô cùng cảm động.' WHERE level = 'B1' AND hanzi = '部' AND pinyin = 'bù' AND vietnamese = 'Bộ phận, phòng ban';
UPDATE public.dictionary_words SET example_hanzi = '部分學生對這個規定有意見。', example_pinyin = 'bù fen xué sheng duì zhè ge guī dìng yǒu yì jiàn。', example_vietnamese = 'Một bộ phận học sinh có ý kiến về quy định này.' WHERE level = 'B1' AND hanzi = '部分/份' AND pinyin = 'bùfen' AND vietnamese = 'Một phần';
UPDATE public.dictionary_words SET example_hanzi = '這篇文章最精彩的部分在最後一段。', example_pinyin = 'zhè piān wén zhāng zuì jīng cǎi de bù fen zài zuì hòu yī duàn。', example_vietnamese = 'Phần hay nhất của bài viết này nằm ở đoạn cuối cùng.' WHERE level = 'B1' AND hanzi = '部分/份' AND pinyin = 'bùfen' AND vietnamese = 'Bộ phận';
