UPDATE public.dictionary_words SET example_hanzi = '這家公司的產品品質很好。', example_pinyin = 'zhè jiā gōng sī de chǎn pǐn pǐn zhí hěn hǎo。', example_vietnamese = 'Sản phẩm của công ty này có chất lượng rất tốt.' WHERE level = 'B1' AND hanzi = '產品' AND pinyin = 'chănpǐn' AND vietnamese = 'Sản phẩm';
