UPDATE public.dictionary_words SET example_hanzi = '除夕夜全家人一起吃團圓飯。', example_pinyin = 'chú xì yè quán jiā rén yī qǐ chī tuán yuán fàn。', example_vietnamese = 'Đêm giao thừa cả nhà cùng nhau ăn bữa cơm đoàn viên.' WHERE level = 'B1' AND hanzi = '除夕' AND pinyin = 'chúxì' AND vietnamese = 'Giao thừa';
UPDATE public.dictionary_words SET example_hanzi = '他的夢想是成為一名廚師。', example_pinyin = 'tā de mèng xiǎng shì chéng wéi yī míng chú shī。', example_vietnamese = 'Ước mơ của anh ấy là trở thành một đầu bếp.' WHERE level = 'B1' AND hanzi = '廚師' AND pinyin = 'chúshī' AND vietnamese = 'Đầu bếp';
UPDATE public.dictionary_words SET example_hanzi = '這件事需要盡快處理。', example_pinyin = 'zhè jiàn shì xū yào jǐn kuài chǔ lǐ。', example_vietnamese = 'Việc này cần được giải quyết càng sớm càng tốt.' WHERE level = 'B1' AND hanzi = '處理' AND pinyin = 'chŭlĭ' AND vietnamese = 'Giải quyết vđ';
UPDATE public.dictionary_words SET example_hanzi = '中秋節是中國的傳統節日。', example_pinyin = 'zhōng qiū jié shì zhōng guó de chuán tǒng jié rì。', example_vietnamese = 'Tết Trung Thu là ngày lễ truyền thống của Trung Quốc.' WHERE level = 'B1' AND hanzi = '傳統' AND pinyin = 'chuántŏng' AND vietnamese = 'Truyền thống';
UPDATE public.dictionary_words SET example_hanzi = '她手上戴著一串手鍊。', example_pinyin = 'tā shǒu shàng dài zhe yī chuàn shǒu liàn。', example_vietnamese = 'Trên tay cô ấy đeo một chuỗi vòng tay.' WHERE level = 'B1' AND hanzi = '串' AND pinyin = 'chuàn' AND vietnamese = 'Xiên';
