UPDATE public.dictionary_words SET example_hanzi = '晚風輕輕地吹過樹梢。', example_pinyin = 'wǎn fēng qīng qīng de chuī guò shù shāo。', example_vietnamese = 'Gió chiều nhẹ nhàng thổi qua ngọn cây.' WHERE level = 'B1' AND hanzi = '吹' AND pinyin = 'chuī' AND vietnamese = 'Thổi';
