UPDATE public.dictionary_words SET example_hanzi = '由此可見，努力真的很重要。', example_pinyin = 'yóu cǐ kě jiàn， nǔ lì zhēn de hěn zhòng yào。', example_vietnamese = 'Từ đó có thể thấy, nỗ lực thật sự rất quan trọng.' WHERE level = 'B1' AND hanzi = '此' AND pinyin = 'cĭ' AND vietnamese = 'Này, cái này';
UPDATE public.dictionary_words SET example_hanzi = '這件事給了他很大的刺激。', example_pinyin = 'zhè jiàn shì gěi le tā hěn dà de cì jī。', example_vietnamese = 'Chuyện này đã tạo ra một sự kích động rất lớn cho anh ấy.' WHERE level = 'B1' AND hanzi = '刺激' AND pinyin = 'cìjī' AND vietnamese = 'Sự thúc đẩy';
UPDATE public.dictionary_words SET example_hanzi = '坐雲霄飛車真的很刺激。', example_pinyin = 'zuò yún xiāo fēi chē zhēn de hěn cì jī。', example_vietnamese = 'Ngồi tàu lượn siêu tốc thật sự rất kích thích.' WHERE level = 'B1' AND hanzi = '刺激' AND pinyin = 'cìjī' AND vietnamese = 'Kích thích, kích động';
UPDATE public.dictionary_words SET example_hanzi = '他從不遲到。', example_pinyin = 'tā cóng bù chí dào。', example_vietnamese = 'Anh ấy không bao giờ đến muộn.' WHERE level = 'B1' AND hanzi = '從不' AND pinyin = 'cóngbù' AND vietnamese = 'Không bao giờ';
UPDATE public.dictionary_words SET example_hanzi = '我從來沒去過歐洲。', example_pinyin = 'wǒ cóng lái méi qù guò ōu zhōu。', example_vietnamese = 'Tôi từ trước đến nay chưa từng đến châu Âu.' WHERE level = 'B1' AND hanzi = '從來' AND pinyin = 'cónglái' AND vietnamese = 'Từ trước đến nay';
UPDATE public.dictionary_words SET example_hanzi = '他從小就喜歡畫畫。', example_pinyin = 'tā cóng xiǎo jiù xǐ huan huà huà。', example_vietnamese = 'Anh ấy từ nhỏ đã thích vẽ tranh.' WHERE level = 'B1' AND hanzi = '從小' AND pinyin = 'cóngxiăo' AND vietnamese = 'Từ nhỏ';
UPDATE public.dictionary_words SET example_hanzi = '這道菜加了一點醋，味道更好。', example_pinyin = 'zhè dào cài jiā le yī diǎn cù， wèi dào gèng hǎo。', example_vietnamese = 'Món này cho thêm chút giấm, hương vị ngon hơn.' WHERE level = 'B1' AND hanzi = '醋' AND pinyin = 'cù' AND vietnamese = 'Giấm';
UPDATE public.dictionary_words SET example_hanzi = '他每個月都會存一些錢。', example_pinyin = 'tā měi gè yuè dōu huì cún yī xiē qián。', example_vietnamese = 'Mỗi tháng anh ấy đều để dành một ít tiền.' WHERE level = 'B1' AND hanzi = '存' AND pinyin = 'cún' AND vietnamese = 'Tồn tại';
UPDATE public.dictionary_words SET example_hanzi = '這個問題一直存在，沒有解決。', example_pinyin = 'zhè ge wèn tí yī zhí cún zài， méi yǒu jiě jué。', example_vietnamese = 'Vấn đề này vẫn luôn tồn tại, chưa được giải quyết.' WHERE level = 'B1' AND hanzi = '存在' AND pinyin = 'cúnzài' AND vietnamese = 'Tồn tại, có thật';
UPDATE public.dictionary_words SET example_hanzi = '這塊布長三寸，寬兩寸。', example_pinyin = 'zhè kuài bù cháng sān cùn， kuān liǎng cùn。', example_vietnamese = 'Mảnh vải này dài ba tấc, rộng hai tấc.' WHERE level = 'B1' AND hanzi = '寸' AND pinyin = 'cùn' AND vietnamese = 'Tấc';
