UPDATE public.dictionary_words SET example_hanzi = '他答應我明天一定會來。', example_pinyin = 'tā dā yìng wǒ míng tiān yī dìng huì lái。', example_vietnamese = 'Anh ấy hứa với tôi ngày mai chắc chắn sẽ đến.' WHERE level = 'B1' AND hanzi = '答應' AND pinyin = 'dāyìng' AND vietnamese = 'đáp ứng';
UPDATE public.dictionary_words SET example_hanzi = '雙方終於達成協議。', example_pinyin = 'shuāng fāng zhōng yú dá chéng xié yì。', example_vietnamese = 'Hai bên cuối cùng đã đạt được thỏa thuận.' WHERE level = 'B1' AND hanzi = '達成' AND pinyin = 'dáchéng' AND vietnamese = 'Đạt đến';
UPDATE public.dictionary_words SET example_hanzi = '他利用暑假去餐廳打工。', example_pinyin = 'tā lì yòng shǔ jià qù cān tīng dǎ gōng。', example_vietnamese = 'Anh ấy tranh thủ kỳ nghỉ hè đi làm thêm ở nhà hàng.' WHERE level = 'B1' AND hanzi = '打工' AND pinyin = 'dăgōng' AND vietnamese = 'Làm thuê';
UPDATE public.dictionary_words SET example_hanzi = '兩個小孩因為玩具打架了。', example_pinyin = 'liǎng gè xiǎo hái yīn wèi wán jù dǎ jià le。', example_vietnamese = 'Hai đứa trẻ đánh nhau vì tranh giành đồ chơi.' WHERE level = 'B1' AND hanzi = '打架' AND pinyin = 'dăjià' AND vietnamese = 'Đánh nhau';
UPDATE public.dictionary_words SET example_hanzi = '我幫你打聽了一下那家公司的情況。', example_pinyin = 'wǒ bāng nǐ dǎ tīng le yī xià nà jiā gōng sī de qíng kuàng。', example_vietnamese = 'Tôi đã dò hỏi giúp bạn tình hình của công ty đó.' WHERE level = 'B1' AND hanzi = '打聽' AND pinyin = 'dătīng' AND vietnamese = 'Nghe ngóng';
