UPDATE public.dictionary_words SET example_hanzi = '這家店現在全面打折。', example_pinyin = 'zhè jiā diàn xiàn zài quán miàn dǎ zhé。', example_vietnamese = 'Cửa hàng này hiện đang giảm giá toàn bộ.' WHERE level = 'B1' AND hanzi = '打折' AND pinyin = 'dăzhé' AND vietnamese = 'Giảm giá';
UPDATE public.dictionary_words SET example_hanzi = '這個發明大大方便了我們的生活。', example_pinyin = 'zhè ge fā míng dà dà fāng biàn le wǒ men de shēng huó。', example_vietnamese = 'Phát minh này đã làm cho cuộc sống của chúng ta thuận tiện hơn rất nhiều.' WHERE level = 'B1' AND hanzi = '大大' AND pinyin = 'dàdà' AND vietnamese = 'Rất, cực kỳ';
UPDATE public.dictionary_words SET example_hanzi = '大多數學生都同意這個計畫。', example_pinyin = 'dà duō shù xué sheng dōu tóng yì zhè ge jì huà。', example_vietnamese = 'Đa số học sinh đều đồng ý với kế hoạch này.' WHERE level = 'B1' AND hanzi = '大多數' AND pinyin = 'dàduōshù' AND vietnamese = 'Đại đa số';
UPDATE public.dictionary_words SET example_hanzi = '她個性大方，很受大家喜歡。', example_pinyin = 'tā gè xìng dà fāng， hěn shòu dà jiā xǐ huan。', example_vietnamese = 'Tính cách cô ấy rộng rãi, cởi mở nên rất được mọi người yêu quý.' WHERE level = 'B1' AND hanzi = '大方' AND pinyin = 'dàfāng' AND vietnamese = 'Rộng rãi, phóng khoáng';
UPDATE public.dictionary_words SET example_hanzi = '這件事大概需要三天才能完成。', example_pinyin = 'zhè jiàn shì dà gài xū yào sān tiān cái néng wán chéng。', example_vietnamese = 'Việc này đại khái cần ba ngày mới có thể hoàn thành.' WHERE level = 'B1' AND hanzi = '大概' AND pinyin = 'dàgài' AND vietnamese = 'Đại khái, sơ lược';
UPDATE public.dictionary_words SET example_hanzi = '明天公司要舉行年度大會。', example_pinyin = 'míng tiān gōng sī yào jǔ xíng nián dù dà huì。', example_vietnamese = 'Ngày mai công ty sẽ tổ chức đại hội thường niên.' WHERE level = 'B1' AND hanzi = '大會' AND pinyin = 'dàhuì' AND vietnamese = 'Đại hội, hội nghị';
UPDATE public.dictionary_words SET example_hanzi = '他常常去大陸出差。', example_pinyin = 'tā cháng cháng qù dà lù chū chāi。', example_vietnamese = 'Anh ấy thường xuyên đi công tác ở Đại lục.' WHERE level = 'B1' AND hanzi = '大陸' AND pinyin = 'dàlù' AND vietnamese = 'Đại lục';
UPDATE public.dictionary_words SET example_hanzi = '請把大門鎖好再離開。', example_pinyin = 'qǐng bǎ dà mén suǒ hǎo zài lí kāi。', example_vietnamese = 'Xin hãy khóa cổng chính cẩn thận trước khi rời đi.' WHERE level = 'B1' AND hanzi = '大門' AND pinyin = 'dàmén' AND vietnamese = 'Cổng chính';
UPDATE public.dictionary_words SET example_hanzi = '這雙鞋的大小剛剛好。', example_pinyin = 'zhè shuāng xié de dà xiǎo gāng gāng hǎo。', example_vietnamese = 'Kích cỡ đôi giày này vừa vặn.' WHERE level = 'B1' AND hanzi = '大小' AND pinyin = 'dàxiăo' AND vietnamese = 'Lớn nhỏ';
UPDATE public.dictionary_words SET example_hanzi = '從這裡到車站大約要走十分鐘。', example_pinyin = 'cóng zhè lǐ dào chē zhàn dà yuē yào zǒu shí fēn zhōng。', example_vietnamese = 'Từ đây đến trạm xe khoảng chừng phải đi bộ mười phút.' WHERE level = 'B1' AND hanzi = '大約' AND pinyin = 'dàyuē' AND vietnamese = 'Khoảng chừng';
UPDATE public.dictionary_words SET example_hanzi = '我買了一袋蘋果。', example_pinyin = 'wǒ mǎi le yī dài píng guǒ。', example_vietnamese = 'Tôi đã mua một túi táo.' WHERE level = 'B1' AND hanzi = '袋' AND pinyin = 'dài' AND vietnamese = 'Bao, gói';
UPDATE public.dictionary_words SET example_hanzi = '他是公司派來的代表。', example_pinyin = 'tā shì gōng sī pài lái de dài biǎo。', example_vietnamese = 'Anh ấy là đại diện được công ty cử đến.' WHERE level = 'B1' AND hanzi = '代表' AND pinyin = 'dàibiǎo' AND vietnamese = 'Đại biểu';
UPDATE public.dictionary_words SET example_hanzi = '這個顏色代表幸運。', example_pinyin = 'zhè ge yán sè dài biǎo xìng yùn。', example_vietnamese = 'Màu sắc này tượng trưng cho may mắn.' WHERE level = 'B1' AND hanzi = '代表' AND pinyin = 'dàibiǎo' AND vietnamese = 'Đại diện';
UPDATE public.dictionary_words SET example_hanzi = '沒有人可以代替你在我心中的位置。', example_pinyin = 'méi yǒu rén kě yǐ dài tì nǐ zài wǒ xīn zhōng de wèi zhi。', example_vietnamese = 'Không ai có thể thay thế vị trí của bạn trong lòng tôi.' WHERE level = 'B1' AND hanzi = '代替' AND pinyin = 'dàitì' AND vietnamese = 'Thay thế';
UPDATE public.dictionary_words SET example_hanzi = '這次旅行給我帶來了很多美好的回憶。', example_pinyin = 'zhè cì lǚ xíng gěi wǒ dài lái le hěn duō měi hǎo de huí yì。', example_vietnamese = 'Chuyến đi lần này đã mang lại cho tôi rất nhiều kỷ niệm đẹp.' WHERE level = 'B1' AND hanzi = '帶來' AND pinyin = 'dàilái' AND vietnamese = 'Đem đến, mang lại';
UPDATE public.dictionary_words SET example_hanzi = '老師帶領學生參觀博物館。', example_pinyin = 'lǎo shī dài lǐng xué sheng cān guān bó wù guǎn。', example_vietnamese = 'Thầy giáo dẫn dắt học sinh tham quan viện bảo tàng.' WHERE level = 'B1' AND hanzi = '帶領' AND pinyin = 'dàilĭng' AND vietnamese = 'Dẫn dắt';
UPDATE public.dictionary_words SET example_hanzi = '他的想法其實很單純。', example_pinyin = 'tā de xiǎng fǎ qí shí hěn dān chún。', example_vietnamese = 'Suy nghĩ của anh ấy thực ra rất đơn thuần.' WHERE level = 'B1' AND hanzi = '單純' AND pinyin = 'dānchún' AND vietnamese = 'Đơn thuần';
UPDATE public.dictionary_words SET example_hanzi = '他今年三十歲了，還是單身。', example_pinyin = 'tā jīn nián sān shí suì le， hái shì dān shēn。', example_vietnamese = 'Năm nay anh ấy đã ba mươi tuổi mà vẫn còn độc thân.' WHERE level = 'B1' AND hanzi = '單身' AND pinyin = 'dānshēn' AND vietnamese = 'Độc thân';
UPDATE public.dictionary_words SET example_hanzi = '她在這家公司擔任經理一職。', example_pinyin = 'tā zài zhè jiā gōng sī dān rèn jīng lǐ yī zhí。', example_vietnamese = 'Cô ấy đảm nhiệm chức vụ giám đốc tại công ty này.' WHERE level = 'B1' AND hanzi = '擔任' AND pinyin = 'dānrèn' AND vietnamese = 'Đảm nhiệm';
UPDATE public.dictionary_words SET example_hanzi = '天氣很冷，但他還是出門跑步了。', example_pinyin = 'tiān qì hěn lěng， dàn tā hái shì chū mén pǎo bù le。', example_vietnamese = 'Trời rất lạnh, nhưng anh ấy vẫn ra ngoài chạy bộ.' WHERE level = 'B1' AND hanzi = '但' AND pinyin = 'dàn' AND vietnamese = 'Nhưng';
UPDATE public.dictionary_words SET example_hanzi = '這杯茶泡得太淡了。', example_pinyin = 'zhè bēi chá pào de tài dàn le。', example_vietnamese = 'Cốc trà này pha nhạt quá.' WHERE level = 'B1' AND hanzi = '淡' AND pinyin = 'dàn' AND vietnamese = 'Nhạt';
UPDATE public.dictionary_words SET example_hanzi = '他的用詞不當，讓大家誤會了。', example_pinyin = 'tā de yòng cí bú dàng， ràng dà jiā wù huì le。', example_vietnamese = 'Cách dùng từ của anh ấy không thỏa đáng, khiến mọi người hiểu lầm.' WHERE level = 'B1' AND hanzi = '當' AND pinyin = 'dāng' AND vietnamese = 'Xác đáng, thích hợp';
UPDATE public.dictionary_words SET example_hanzi = '他被老師當場抓到作弊。', example_pinyin = 'tā bèi lǎo shī dāng chǎng zhuā dào zuò bì。', example_vietnamese = 'Cậu ấy bị thầy giáo bắt gặp gian lận ngay tại chỗ.' WHERE level = 'B1' AND hanzi = '當場' AND pinyin = 'dāngchăng' AND vietnamese = 'Tại chỗ';
UPDATE public.dictionary_words SET example_hanzi = '我們品嚐了很多當地美食。', example_pinyin = 'wǒ men pǐn cháng le hěn duō dāng dì měi shí。', example_vietnamese = 'Chúng tôi đã thưởng thức rất nhiều món ngon bản địa.' WHERE level = 'B1' AND hanzi = '當地' AND pinyin = 'dāngdì' AND vietnamese = 'Bản địa';
UPDATE public.dictionary_words SET example_hanzi = '有意見應該當面說清楚。', example_pinyin = 'yǒu yì jiàn yīng gāi dāng miàn shuō qīng chu。', example_vietnamese = 'Có ý kiến gì thì nên nói rõ trước mặt nhau.' WHERE level = 'B1' AND hanzi = '當面' AND pinyin = 'dāngmiàn' AND vietnamese = 'Trước mặt';
UPDATE public.dictionary_words SET example_hanzi = '當年他們一起在這裡讀書。', example_pinyin = 'dāng nián tā men yī qǐ zài zhè lǐ dú shū。', example_vietnamese = 'Năm đó họ đã cùng nhau học tập ở đây.' WHERE level = 'B1' AND hanzi = '當年' AND pinyin = 'dāngnián' AND vietnamese = 'Năm đó';
UPDATE public.dictionary_words SET example_hanzi = '訂單當天就能出貨。', example_pinyin = 'dìng dān dàng tiān jiù néng chū huò。', example_vietnamese = 'Đơn hàng ngay trong ngày hôm đó là có thể xuất kho.' WHERE level = 'B1' AND hanzi = '當天' AND pinyin = 'dàngtiān' AND vietnamese = 'Ngày hôm đó';
UPDATE public.dictionary_words SET example_hanzi = '這些學生當中，有一半是外國人。', example_pinyin = 'zhè xiē xué sheng dāng zhōng， yǒu yī bàn shì wài guó rén。', example_vietnamese = 'Trong số những học sinh này, có một nửa là người nước ngoài.' WHERE level = 'B1' AND hanzi = '當中' AND pinyin = 'dāngzhōng' AND vietnamese = 'Trong khi';
UPDATE public.dictionary_words SET example_hanzi = '他把這隻狗當作自己的家人。', example_pinyin = 'tā bǎ zhè zhī gǒu dàng zuò zì jǐ de jiā rén。', example_vietnamese = 'Anh ấy coi con chó này như người thân trong gia đình.' WHERE level = 'B1' AND hanzi = '當作' AND pinyin = 'dàngzuò' AND vietnamese = 'Coi như, xem như';
UPDATE public.dictionary_words SET example_hanzi = '別把我的好意當做理所當然。', example_pinyin = 'bié bǎ wǒ de hǎo yì dàng zuò lǐ suǒ dāng rán。', example_vietnamese = 'Đừng coi thiện ý của tôi là chuyện đương nhiên.' WHERE level = 'B1' AND hanzi = '當做' AND pinyin = 'dàngzuò' AND vietnamese = 'Cho rằng, coi như là';
UPDATE public.dictionary_words SET example_hanzi = '那棵大樹被颱風吹倒了。', example_pinyin = 'nà kē dà shù bèi tái fēng chuī dǎo le。', example_vietnamese = 'Cây cổ thụ đó đã bị bão thổi đổ.' WHERE level = 'B1' AND hanzi = '倒' AND pinyin = 'dǎo' AND vietnamese = 'Đảo ngược';
UPDATE public.dictionary_words SET example_hanzi = '台灣是一座美麗的島。', example_pinyin = 'tái wān shì yī zuò měi lì de dǎo。', example_vietnamese = 'Đài Loan là một hòn đảo xinh đẹp.' WHERE level = 'B1' AND hanzi = '島' AND pinyin = 'dăo' AND vietnamese = 'hòn dảo';
UPDATE public.dictionary_words SET example_hanzi = '這部電影的導演非常有名。', example_pinyin = 'zhè bù diàn yǐng de dǎo yǎn fēi cháng yǒu míng。', example_vietnamese = 'Đạo diễn của bộ phim này rất nổi tiếng.' WHERE level = 'B1' AND hanzi = '導演' AND pinyin = 'dăoyăn' AND vietnamese = 'Đạo diễn';
UPDATE public.dictionary_words SET example_hanzi = '他工作到很晚才回家。', example_pinyin = 'tā gōng zuò dào hěn wǎn cái huí jiā。', example_vietnamese = 'Anh ấy làm việc đến tận khuya mới về nhà.' WHERE level = 'B1' AND hanzi = '到' AND pinyin = 'dào' AND vietnamese = 'Đến';
UPDATE public.dictionary_words SET example_hanzi = '火車已經到站了。', example_pinyin = 'huǒ chē yǐ jīng dào zhàn le。', example_vietnamese = 'Tàu hỏa đã đến ga rồi.' WHERE level = 'B1' AND hanzi = '到' AND pinyin = 'dào' AND vietnamese = 'Chu đáo, đầy đủ';
UPDATE public.dictionary_words SET example_hanzi = '春天到了，到處都開滿了花。', example_pinyin = 'chūn tiān dào le， dào chù dōu kāi mǎn le huā。', example_vietnamese = 'Mùa xuân đến rồi, khắp nơi đều nở đầy hoa.' WHERE level = 'B1' AND hanzi = '到處' AND pinyin = 'dàochù' AND vietnamese = 'Khắp nơi';
UPDATE public.dictionary_words SET example_hanzi = '你到底想說什麼？', example_pinyin = 'nǐ dào dǐ xiǎng shuō shén me？', example_vietnamese = 'Rốt cuộc bạn muốn nói gì?' WHERE level = 'B1' AND hanzi = '到底' AND pinyin = 'dàodĭ' AND vietnamese = 'Đến cuối cùng';
UPDATE public.dictionary_words SET example_hanzi = '這件事一定要查個到底。', example_pinyin = 'zhè jiàn shì yī dìng yào chá gè dào dǐ。', example_vietnamese = 'Việc này nhất định phải điều tra cho ra ngọn ngành.' WHERE level = 'B1' AND hanzi = '到底' AND pinyin = 'dàodĭ' AND vietnamese = 'Rốt cuộc, suy cho cùng';
UPDATE public.dictionary_words SET example_hanzi = '誠實是一種基本的道德。', example_pinyin = 'chéng shí shì yī zhǒng jī běn de dào dé。', example_vietnamese = 'Thành thật là một loại đạo đức cơ bản.' WHERE level = 'B1' AND hanzi = '道德' AND pinyin = 'dàodé' AND vietnamese = 'Đạo đức';
UPDATE public.dictionary_words SET example_hanzi = '這座廟屬於道教信仰。', example_pinyin = 'zhè zuò miào shǔ yú dào jiào xìn yǎng。', example_vietnamese = 'Ngôi đền này thuộc về tín ngưỡng Đạo giáo.' WHERE level = 'B1' AND hanzi = '道教' AND pinyin = 'Dàojiào' AND vietnamese = 'Đạo giáo';
UPDATE public.dictionary_words SET example_hanzi = '他說的話很有道理。', example_pinyin = 'tā shuō de huà hěn yǒu dào lǐ。', example_vietnamese = 'Lời anh ấy nói rất có lý.' WHERE level = 'B1' AND hanzi = '道理' AND pinyin = 'dàolĭ' AND vietnamese = 'Đạo lý, quy luật';
UPDATE public.dictionary_words SET example_hanzi = '他為自己的錯誤向大家道歉。', example_pinyin = 'tā wèi zì jǐ de cuò wù xiàng dà jiā dào qiàn。', example_vietnamese = 'Anh ấy đã xin lỗi mọi người vì sai lầm của mình.' WHERE level = 'B1' AND hanzi = '道歉' AND pinyin = 'dàoqiàn' AND vietnamese = 'Xin thứ lỗi';
UPDATE public.dictionary_words SET example_hanzi = '他不但沒生氣，倒笑了起來。', example_pinyin = 'tā bú dàn méi shēng qì， dào xiào le qǐ lái。', example_vietnamese = 'Anh ấy không những không giận, trái lại còn cười lên.' WHERE level = 'B1' AND hanzi = '倒' AND pinyin = 'dào' AND vietnamese = 'Trái lại';
UPDATE public.dictionary_words SET example_hanzi = '這件事你倒是提醒了我。', example_pinyin = 'zhè jiàn shì nǐ dào shì tí xǐng le wǒ。', example_vietnamese = 'Chuyện này ngược lại là bạn đã nhắc nhở tôi đấy.' WHERE level = 'B1' AND hanzi = '倒是' AND pinyin = 'dàoshì' AND vietnamese = 'Ngược lại';
UPDATE public.dictionary_words SET example_hanzi = '他這次比賽得了冠軍。', example_pinyin = 'tā zhè cì bǐ sài dé le guàn jūn。', example_vietnamese = 'Lần thi đấu này anh ấy đã giành được chức vô địch.' WHERE level = 'B1' AND hanzi = '得' AND pinyin = 'dé' AND vietnamese = 'Được, có được';
UPDATE public.dictionary_words SET example_hanzi = '他終於得到了想要的工作。', example_pinyin = 'tā zhōng yú dé dào le xiǎng yào de gōng zuò。', example_vietnamese = 'Cuối cùng anh ấy cũng có được công việc mình mong muốn.' WHERE level = 'B1' AND hanzi = '得到' AND pinyin = 'dédào' AND vietnamese = 'Đạt được';
UPDATE public.dictionary_words SET example_hanzi = '他考了第一名，非常得意。', example_pinyin = 'tā kǎo le dì yī míng， fēi cháng dé yì。', example_vietnamese = 'Cậu ấy thi được hạng nhất, rất đắc ý.' WHERE level = 'B1' AND hanzi = '得意' AND pinyin = 'déyì' AND vietnamese = 'Đắc ý';
UPDATE public.dictionary_words SET example_hanzi = '這家店的生意好得很。', example_pinyin = 'zhè jiā diàn de shēng yì hǎo de hěn。', example_vietnamese = 'Việc buôn bán của cửa hàng này tốt lắm.' WHERE level = 'B1' AND hanzi = '得很' AND pinyin = 'dehěn' AND vietnamese = 'Rất nhiều';
UPDATE public.dictionary_words SET example_hanzi = '如果明天下雨的話，我們就不去爬山了。', example_pinyin = 'rú guǒ míng tiān xià yǔ de huà， wǒ men jiù bú qù pá shān le。', example_vietnamese = 'Nếu ngày mai trời mưa thì chúng ta sẽ không đi leo núi nữa.' WHERE level = 'B1' AND hanzi = '的話' AND pinyin = 'dehuà' AND vietnamese = 'Nếu';
UPDATE public.dictionary_words SET example_hanzi = '已經很晚了，我得回家了。', example_pinyin = 'yǐ jīng hěn wǎn le， wǒ děi huí jiā le。', example_vietnamese = 'Đã muộn rồi, tôi phải về nhà thôi.' WHERE level = 'B1' AND hanzi = '得' AND pinyin = 'děi' AND vietnamese = 'Phải';
UPDATE public.dictionary_words SET example_hanzi = '舞台上的燈光非常漂亮。', example_pinyin = 'wǔ tái shàng de dēng guāng fēi cháng piào liang。', example_vietnamese = 'Ánh đèn trên sân khấu vô cùng đẹp mắt.' WHERE level = 'B1' AND hanzi = '燈光' AND pinyin = 'dēngguāng' AND vietnamese = 'Ánh đèn';
UPDATE public.dictionary_words SET example_hanzi = '我在門口等你。', example_pinyin = 'wǒ zài mén kǒu děng nǐ。', example_vietnamese = 'Tôi đợi bạn ở cửa.' WHERE level = 'B1' AND hanzi = '等' AND pinyin = 'děng' AND vietnamese = 'Đợi';
UPDATE public.dictionary_words SET example_hanzi = '桌上有蘋果、香蕉、橘子等水果。', example_pinyin = 'zhuō shàng yǒu píng guǒ、 xiāng jiāo、 jú zi děng shuǐ guǒ。', example_vietnamese = 'Trên bàn có táo, chuối, quýt vân vân các loại trái cây.' WHERE level = 'B1' AND hanzi = '等/等等' AND pinyin = 'děng/děngděng' AND vietnamese = 'Vân vân';
UPDATE public.dictionary_words SET example_hanzi = '大家都在耐心地等待結果。', example_pinyin = 'dà jiā dōu zài nài xīn de děng dài jié guǒ。', example_vietnamese = 'Mọi người đều đang kiên nhẫn chờ đợi kết quả.' WHERE level = 'B1' AND hanzi = '等待' AND pinyin = 'děngdài' AND vietnamese = 'Chờ đợi';
UPDATE public.dictionary_words SET example_hanzi = '這裡的房價比市中心低很多。', example_pinyin = 'zhè lǐ de fáng jià bǐ shì zhōng xīn dī hěn duō。', example_vietnamese = 'Giá nhà ở đây thấp hơn nhiều so với trung tâm thành phố.' WHERE level = 'B1' AND hanzi = '低' AND pinyin = 'dī' AND vietnamese = 'Thấp';
UPDATE public.dictionary_words SET example_hanzi = '士兵們勇敢地對抗敵人。', example_pinyin = 'shì bīng men yǒng gǎn de duì kàng dí rén。', example_vietnamese = 'Các binh sĩ dũng cảm chống lại quân địch.' WHERE level = 'B1' AND hanzi = '敵人' AND pinyin = 'dírén' AND vietnamese = 'Quân địch';
UPDATE public.dictionary_words SET example_hanzi = '杯子底部有一些茶葉。', example_pinyin = 'bēi zi dǐ bù yǒu yī xiē chá yè。', example_vietnamese = 'Đáy cốc có một ít lá trà.' WHERE level = 'B1' AND hanzi = '底' AND pinyin = 'dĭ' AND vietnamese = 'đáy';
UPDATE public.dictionary_words SET example_hanzi = '貓躲在桌子底下睡覺。', example_pinyin = 'māo duǒ zài zhuō zi dǐ xia shuì jiào。', example_vietnamese = 'Con mèo trốn dưới gầm bàn ngủ.' WHERE level = 'B1' AND hanzi = '底下' AND pinyin = 'dĭxia' AND vietnamese = 'Phía dưới';
UPDATE public.dictionary_words SET example_hanzi = '我們的飛機準時抵達機場。', example_pinyin = 'wǒ men de fēi jī zhǔn shí dǐ dá jī chǎng。', example_vietnamese = 'Máy bay của chúng tôi đến sân bay đúng giờ.' WHERE level = 'B1' AND hanzi = '抵達' AND pinyin = 'dĭdá' AND vietnamese = 'Đến nơi';
UPDATE public.dictionary_words SET example_hanzi = '他慢慢地走進教室。', example_pinyin = 'tā màn màn de zǒu jìn jiào shì。', example_vietnamese = 'Anh ấy từ từ bước vào lớp học.' WHERE level = 'B1' AND hanzi = '地' AND pinyin = 'dì' AND vietnamese = 'Một cách';
UPDATE public.dictionary_words SET example_hanzi = '每天早上她都會擦地板。', example_pinyin = 'měi tiān zǎo shang tā dōu huì cā dì bǎn。', example_vietnamese = 'Mỗi sáng cô ấy đều lau sàn nhà.' WHERE level = 'B1' AND hanzi = '地板' AND pinyin = 'dìbăn' AND vietnamese = 'Sàn nhà, nền nhà';
UPDATE public.dictionary_words SET example_hanzi = '這裡是森林地帶，要小心野生動物。', example_pinyin = 'zhè lǐ shì sēn lín dì dài， yào xiǎo xīn yě shēng dòng wù。', example_vietnamese = 'Đây là vùng rừng núi, cần cẩn thận với động vật hoang dã.' WHERE level = 'B1' AND hanzi = '地帶' AND pinyin = 'dìdài' AND vietnamese = 'Miền, vùng';
UPDATE public.dictionary_words SET example_hanzi = '我們約好了見面的地點。', example_pinyin = 'wǒ men yuē hǎo le jiàn miàn de dì diǎn。', example_vietnamese = 'Chúng tôi đã hẹn trước địa điểm gặp mặt.' WHERE level = 'B1' AND hanzi = '地點' AND pinyin = 'dìdiăn' AND vietnamese = 'Địa điểm';
UPDATE public.dictionary_words SET example_hanzi = '他對台灣的地理環境很了解。', example_pinyin = 'tā duì tái wān de dì lǐ huán jìng hěn liǎo jiě。', example_vietnamese = 'Anh ấy rất am hiểu về môi trường địa lý của Đài Loan.' WHERE level = 'B1' AND hanzi = '地理' AND pinyin = 'dìlĭ' AND vietnamese = 'Địa lý';
UPDATE public.dictionary_words SET example_hanzi = '這個地區的房價一直上漲。', example_pinyin = 'zhè ge dì qū de fáng jià yī zhí shàng zhǎng。', example_vietnamese = 'Giá nhà ở khu vực này liên tục tăng.' WHERE level = 'B1' AND hanzi = '地區' AND pinyin = 'dìqū' AND vietnamese = 'Khu vực';
UPDATE public.dictionary_words SET example_hanzi = '良好的教育對孩子的未來很重要。', example_pinyin = 'liánghǎo de jiàoyù duì háizi de wèilái hěn zhòngyào。', example_vietnamese = 'Nền giáo dục tốt rất quan trọng đối với tương lai của trẻ em.' WHERE level = 'B1' AND hanzi = '教育' AND pinyin = 'jiàoyù' AND vietnamese = 'Giáo dục, đào tạo';
UPDATE public.dictionary_words SET example_hanzi = '父母應該用耐心教育孩子，而不是打罵。', example_pinyin = 'fùmǔ yīnggāi yòng nàixīn jiàoyù háizi，ér bú shì dǎmà。', example_vietnamese = 'Cha mẹ nên dùng sự kiên nhẫn để giáo dục con cái, chứ không phải đánh mắng.' WHERE level = 'B1' AND hanzi = '教育' AND pinyin = 'jiàoyù' AND vietnamese = 'Chỉ dẫn, dạy';
UPDATE public.dictionary_words SET example_hanzi = '醫生每天都要接觸很多病人。', example_pinyin = 'yīshēng měitiān dōu yào jiēchù hěn duō bìngrén。', example_vietnamese = 'Bác sĩ mỗi ngày đều phải tiếp xúc với rất nhiều bệnh nhân.' WHERE level = 'B1' AND hanzi = '接觸' AND pinyin = 'jiēchù' AND vietnamese = 'Tiếp xúc';
UPDATE public.dictionary_words SET example_hanzi = '他很難接受這個結果。', example_pinyin = 'tā hěn nán jiēshòu zhège jiéguǒ。', example_vietnamese = 'Anh ấy rất khó chấp nhận kết quả này.' WHERE level = 'B1' AND hanzi = '接受' AND pinyin = 'jiēshòu' AND vietnamese = 'Tiếp thu';
UPDATE public.dictionary_words SET example_hanzi = '我們先吃飯，接著再去看電影。', example_pinyin = 'wǒmen xiān chīfàn，jiēzhe zài qù kàn diànyǐng。', example_vietnamese = 'Chúng ta ăn cơm trước, tiếp theo rồi đi xem phim.' WHERE level = 'B1' AND hanzi = '接著' AND pinyin = 'jiēzhe' AND vietnamese = 'Tiếp theo';
UPDATE public.dictionary_words SET example_hanzi = '蜘蛛在窗戶上結了一張網。', example_pinyin = 'zhīzhū zài chuānghù shàng jié le yì zhāng wǎng。', example_vietnamese = 'Con nhện đã kết một cái mạng trên cửa sổ.' WHERE level = 'B1' AND hanzi = '結' AND pinyin = 'jié' AND vietnamese = 'Kết, đan thành';
UPDATE public.dictionary_words SET example_hanzi = '他沒有準備，結果考試不及格。', example_pinyin = 'tā méiyǒu zhǔnbèi，jiéguǒ kǎoshì bù jígé。', example_vietnamese = 'Anh ấy không chuẩn bị, kết quả là thi trượt.' WHERE level = 'B1' AND hanzi = '結果' AND pinyin = 'jiéguǒ' AND vietnamese = 'Kết quả';
UPDATE public.dictionary_words SET example_hanzi = '這部電影的結局讓很多觀眾都哭了。', example_pinyin = 'zhè bù diànyǐng de jiéjú ràng hěn duō guānzhòng dōu kū le。', example_vietnamese = 'Kết cục của bộ phim này khiến rất nhiều khán giả bật khóc.' WHERE level = 'B1' AND hanzi = '結局' AND pinyin = 'jiéjú' AND vietnamese = 'Kết cục';
UPDATE public.dictionary_words SET example_hanzi = '今天早上有一節數學課。', example_pinyin = 'jīntiān zǎoshang yǒu yì jié shùxué kè。', example_vietnamese = 'Sáng nay có một tiết học toán.' WHERE level = 'B1' AND hanzi = '節' AND pinyin = 'jié' AND vietnamese = 'Mấu, khớp';
UPDATE public.dictionary_words SET example_hanzi = '中秋節是台灣人很重視的節日。', example_pinyin = 'zhōngqiūjié shì táiwān rén hěn zhòngshì de jiérì。', example_vietnamese = 'Tết Trung thu là ngày lễ mà người Đài Loan rất coi trọng.' WHERE level = 'B1' AND hanzi = '節日' AND pinyin = 'jiérì' AND vietnamese = 'Ngày lễ, ngày hội';
UPDATE public.dictionary_words SET example_hanzi = '這個問題還沒解決，大家都很煩惱。', example_pinyin = 'zhège wèntí hái méi jiějué，dàjiā dōu hěn fánnǎo。', example_vietnamese = 'Vấn đề này vẫn chưa được giải quyết, mọi người đều rất lo lắng.' WHERE level = 'B1' AND hanzi = '解決' AND pinyin = 'jiějué' AND vietnamese = 'Giải quyết';
UPDATE public.dictionary_words SET example_hanzi = '老師耐心地向我們解釋這個文法。', example_pinyin = 'lǎoshī nàixīn de xiàng wǒmen jiěshì zhège wénfǎ。', example_vietnamese = 'Thầy giáo kiên nhẫn giải thích ngữ pháp này cho chúng tôi.' WHERE level = 'B1' AND hanzi = '解釋' AND pinyin = 'jiěshì' AND vietnamese = 'Giải thích';
UPDATE public.dictionary_words SET example_hanzi = '我們姊妹三個從小感情就很好。', example_pinyin = 'wǒmen jiěmèi sān ge cóngxiǎo gǎnqíng jiù hěn hǎo。', example_vietnamese = 'Ba chị em chúng tôi từ nhỏ tình cảm đã rất tốt.' WHERE level = 'B1' AND hanzi = '姊妹' AND pinyin = 'jiěmèi' AND vietnamese = 'Chị em';
UPDATE public.dictionary_words SET example_hanzi = '媽媽在市場買了兩斤蘋果。', example_pinyin = 'māma zài shìchǎng mǎi le liǎng jīn píngguǒ。', example_vietnamese = 'Mẹ mua hai cân táo ở chợ.' WHERE level = 'B1' AND hanzi = '斤' AND pinyin = 'jīn' AND vietnamese = 'Cân (=1/2kg)';
UPDATE public.dictionary_words SET example_hanzi = '這條項鍊是用純金做的。', example_pinyin = 'zhè tiáo xiàngliàn shì yòng chún jīn zuò de。', example_vietnamese = 'Sợi dây chuyền này được làm bằng vàng ròng.' WHERE level = 'B1' AND hanzi = '金(子)' AND pinyin = 'jīn(zi)' AND vietnamese = 'Vàng';
UPDATE public.dictionary_words SET example_hanzi = '這條褲子太緊了，我穿不下。', example_pinyin = 'zhè tiáo kùzi tài jǐn le，wǒ chuān bú xià。', example_vietnamese = 'Cái quần này quá chật, tôi mặc không vừa.' WHERE level = 'B1' AND hanzi = '緊' AND pinyin = 'jǐn' AND vietnamese = 'Căng, kéo căng';
UPDATE public.dictionary_words SET example_hanzi = '這次比賽僅有十個人報名。', example_pinyin = 'zhècì bǐsài jǐn yǒu shí ge rén bàomíng。', example_vietnamese = 'Cuộc thi lần này chỉ có mười người đăng ký.' WHERE level = 'B1' AND hanzi = '僅' AND pinyin = 'jĭn' AND vietnamese = 'Vẻn vẹn, chỉ';
UPDATE public.dictionary_words SET example_hanzi = '儘管天氣很冷，他還是去跑步。', example_pinyin = 'jǐnguǎn tiānqì hěn lěng，tā háishì qù pǎobù。', example_vietnamese = 'Mặc dù trời rất lạnh, anh ấy vẫn đi chạy bộ.' WHERE level = 'B1' AND hanzi = '儘管' AND pinyin = 'jĭnguăn' AND vietnamese = 'Mặc dù, cho dù';
UPDATE public.dictionary_words SET example_hanzi = '他盡了最大的努力才通過考試。', example_pinyin = 'tā jìn le zuì dà de nǔlì cái tōngguò kǎoshì。', example_vietnamese = 'Anh ấy đã cố gắng hết sức mới vượt qua kỳ thi.' WHERE level = 'B1' AND hanzi = '盡' AND pinyin = 'jìn' AND vietnamese = 'Hết sức, cố';
UPDATE public.dictionary_words SET example_hanzi = '請大家安靜地進教室。', example_pinyin = 'qǐng dàjiā ānjìng de jìn jiàoshì。', example_vietnamese = 'Mời mọi người vào lớp học một cách yên lặng.' WHERE level = 'B1' AND hanzi = '進' AND pinyin = 'jìn' AND vietnamese = 'Tiến vào';
UPDATE public.dictionary_words SET example_hanzi = '會議正在進行，請大家不要打擾。', example_pinyin = 'huìyì zhèngzài jìnxíng，qǐng dàjiā bú yào dǎrǎo。', example_vietnamese = 'Cuộc họp đang được tiến hành, xin mọi người đừng làm phiền.' WHERE level = 'B1' AND hanzi = '進行' AND pinyin = 'jìnxíng' AND vietnamese = 'Tiến hành';
UPDATE public.dictionary_words SET example_hanzi = '我們需要進一步了解這件事的原因。', example_pinyin = 'wǒmen xūyào jìnyíbù liǎojiě zhè jiàn shì de yuányīn。', example_vietnamese = 'Chúng ta cần tìm hiểu sâu hơn nữa nguyên nhân của việc này.' WHERE level = 'B1' AND hanzi = '進一步' AND pinyin = 'jìnyíbù' AND vietnamese = 'Tiến lên 1 bước';
UPDATE public.dictionary_words SET example_hanzi = '經一番努力，他終於考上了理想的大學。', example_pinyin = 'jīng yì fān nǔlì，tā zhōngyú kǎoshàng le lǐxiǎng de dàxué。', example_vietnamese = 'Trải qua một phen nỗ lực, anh ấy cuối cùng đã thi đỗ vào trường đại học mơ ước.' WHERE level = 'B1' AND hanzi = '經' AND pinyin = 'jīng' AND vietnamese = 'Trải qua';
UPDATE public.dictionary_words SET example_hanzi = '學校今年的經費不太夠，很多活動都取消了。', example_pinyin = 'xuéxiào jīnnián de jīngfèi bú tài gòu，hěn duō huódòng dōu qǔxiāo le。', example_vietnamese = 'Kinh phí của trường năm nay không đủ nên nhiều hoạt động bị hủy.' WHERE level = 'B1' AND hanzi = '經費' AND pinyin = 'jīngfèi' AND vietnamese = 'Kinh phí';
UPDATE public.dictionary_words SET example_hanzi = '他向大家說明了事情的經過。', example_pinyin = 'tā xiàng dàjiā shuōmíng le shìqíng de jīngguò。', example_vietnamese = 'Anh ấy đã trình bày cho mọi người quá trình sự việc.' WHERE level = 'B1' AND hanzi = '經過' AND pinyin = 'jīngguò' AND vietnamese = 'Quá trình';
UPDATE public.dictionary_words SET example_hanzi = '我每天上班都會經過那家咖啡店。', example_pinyin = 'wǒ měitiān shàngbān dōu huì jīngguò nà jiā kāfēidiàn。', example_vietnamese = 'Mỗi ngày đi làm tôi đều đi qua quán cà phê đó.' WHERE level = 'B1' AND hanzi = '經過' AND pinyin = 'jīngguò' AND vietnamese = 'Trải qua, đi qua';
UPDATE public.dictionary_words SET example_hanzi = '他在這個行業已經有十年的經驗了。', example_pinyin = 'tā zài zhège hángyè yǐjīng yǒu shí nián de jīngyàn le。', example_vietnamese = 'Anh ấy đã có mười năm kinh nghiệm trong ngành này.' WHERE level = 'B1' AND hanzi = '經驗' AND pinyin = 'jīngyàn' AND vietnamese = 'Kinh nghiệm';
UPDATE public.dictionary_words SET example_hanzi = '睡飽以後，他今天特別有精神。', example_pinyin = 'shuì bǎo yǐhòu，tā jīntiān tèbié yǒu jīngshén。', example_vietnamese = 'Sau khi ngủ đủ giấc, hôm nay anh ấy đặc biệt tràn đầy tinh thần.' WHERE level = 'B1' AND hanzi = '精神' AND pinyin = 'jīngshén' AND vietnamese = 'Tinh thần';
UPDATE public.dictionary_words SET example_hanzi = '聽到這個消息，大家都感到很驚訝。', example_pinyin = 'tīngdào zhège xiāoxi，dàjiā dōu gǎndào hěn jīngyà。', example_vietnamese = 'Nghe được tin này, mọi người đều cảm thấy rất kinh ngạc.' WHERE level = 'B1' AND hanzi = '驚訝' AND pinyin = 'jīngyà' AND vietnamese = 'Kinh ngạc';
UPDATE public.dictionary_words SET example_hanzi = '週末他常常和朋友去酒吧喝一杯。', example_pinyin = 'zhōumò tā chángcháng hé péngyǒu qù jiǔbā hē yì bēi。', example_vietnamese = 'Cuối tuần anh ấy thường cùng bạn bè đến quán bar uống một ly.' WHERE level = 'B1' AND hanzi = '酒吧' AND pinyin = 'jiŭbā' AND vietnamese = 'Quán bar';
UPDATE public.dictionary_words SET example_hanzi = '消防員冒著生命危險把小孩救了出來。', example_pinyin = 'xiāofángyuán màozhe shēngmìng wēixiǎn bǎ xiǎohái jiù le chūlái。', example_vietnamese = 'Lính cứu hỏa liều mạng cứu đứa trẻ ra ngoài.' WHERE level = 'B1' AND hanzi = '救' AND pinyin = 'jiù' AND vietnamese = 'Cứu giúp';
UPDATE public.dictionary_words SET example_hanzi = '我舅舅每年過年都會回台灣看我們。', example_pinyin = 'wǒ jiùjiu měinián guònián dōu huì huí táiwān kàn wǒmen。', example_vietnamese = 'Cậu tôi năm nào ăn Tết cũng về Đài Loan thăm chúng tôi.' WHERE level = 'B1' AND hanzi = '舅舅' AND pinyin = 'jiùjiu' AND vietnamese = 'Cậu (em của mẹ)';
UPDATE public.dictionary_words SET example_hanzi = '舅媽做的紅燒肉非常好吃。', example_pinyin = 'jiùmā zuò de hóngshāoròu fēicháng hǎochī。', example_vietnamese = 'Món thịt kho của mợ tôi rất ngon.' WHERE level = 'B1' AND hanzi = '舅媽' AND pinyin = 'jiùmā' AND vietnamese = 'Mợ (vợ của cậu)';
UPDATE public.dictionary_words SET example_hanzi = '你只要努力，就一定會成功。', example_pinyin = 'nǐ zhǐyào nǔlì，jiù yídìng huì chénggōng。', example_vietnamese = 'Chỉ cần bạn cố gắng thì chắc chắn sẽ thành công.' WHERE level = 'B1' AND hanzi = '就' AND pinyin = 'jiù' AND vietnamese = 'Thì';
UPDATE public.dictionary_words SET example_hanzi = '站在門口的那個人就是我們的新老師。', example_pinyin = 'zhàn zài ménkǒu de nàge rén jiùshì wǒmen de xīn lǎoshī。', example_vietnamese = 'Người đang đứng ở cửa chính là thầy giáo mới của chúng tôi.' WHERE level = 'B1' AND hanzi = '就是' AND pinyin = 'jiùshì' AND vietnamese = 'Nhất định';
UPDATE public.dictionary_words SET example_hanzi = '就算下雨，我們也要去爬山。', example_pinyin = 'jiùsuàn xiàyǔ，wǒmen yě yào qù páshān。', example_vietnamese = 'Cho dù trời mưa, chúng tôi vẫn muốn đi leo núi.' WHERE level = 'B1' AND hanzi = '就算' AND pinyin = 'jiùsuàn' AND vietnamese = 'Cho dù';
UPDATE public.dictionary_words SET example_hanzi = '暑假就要開始了，大家都很興奮。', example_pinyin = 'shǔjià jiùyào kāishǐ le，dàjiā dōu hěn xīngfèn。', example_vietnamese = 'Kỳ nghỉ hè sắp bắt đầu rồi, mọi người đều rất hào hứng.' WHERE level = 'B1' AND hanzi = '就要' AND pinyin = 'jiùyào' AND vietnamese = 'Sẽ, sẽ đến';
UPDATE public.dictionary_words SET example_hanzi = '他們一家人已經在這裡居住了二十年。', example_pinyin = 'tāmen yì jiā rén yǐjīng zài zhèlǐ jūzhù le èrshí nián。', example_vietnamese = 'Gia đình họ đã cư trú ở đây được hai mươi năm.' WHERE level = 'B1' AND hanzi = '居住' AND pinyin = 'jūzhù' AND vietnamese = 'Cư trú, sống, ở';
UPDATE public.dictionary_words SET example_hanzi = '冬天的時候，橘子特別便宜又好吃。', example_pinyin = 'dōngtiān de shíhòu，júzi tèbié piányí yòu hǎochī。', example_vietnamese = 'Vào mùa đông, quýt vừa rẻ vừa ngon.' WHERE level = 'B1' AND hanzi = '橘子' AND pinyin = 'júzi' AND vietnamese = 'Cây quýt, quả quýt';
UPDATE public.dictionary_words SET example_hanzi = '他一個人就把桌子舉了起來。', example_pinyin = 'tā yí ge rén jiù bǎ zhuōzi jǔ le qǐlái。', example_vietnamese = 'Một mình anh ấy đã nhấc cái bàn lên.' WHERE level = 'B1' AND hanzi = '舉' AND pinyin = 'jǔ' AND vietnamese = 'Giương, nâng lên';
UPDATE public.dictionary_words SET example_hanzi = '學校下個月要舉辦一場運動會。', example_pinyin = 'xuéxiào xià ge yuè yào jǔbàn yì chǎng yùndònghuì。', example_vietnamese = 'Tháng sau trường sẽ tổ chức một hội thao.' WHERE level = 'B1' AND hanzi = '舉辦' AND pinyin = 'jŭbàn' AND vietnamese = 'Tổ chức, cử hành';
UPDATE public.dictionary_words SET example_hanzi = '有問題的同學請舉手。', example_pinyin = 'yǒu wèntí de tóngxué qǐng jǔshǒu。', example_vietnamese = 'Bạn nào có thắc mắc xin hãy giơ tay.' WHERE level = 'B1' AND hanzi = '舉手' AND pinyin = 'jŭshŏu' AND vietnamese = 'Giơ tay';
UPDATE public.dictionary_words SET example_hanzi = '婚禮將在下星期六舉行。', example_pinyin = 'hūnlǐ jiāng zài xià xīngqíliù jǔxíng。', example_vietnamese = 'Đám cưới sẽ được tổ chức vào thứ Bảy tuần sau.' WHERE level = 'B1' AND hanzi = '舉行' AND pinyin = 'jǔxíng' AND vietnamese = 'Tiến hành, tổ chức';
UPDATE public.dictionary_words SET example_hanzi = '請你用中文說一句話。', example_pinyin = 'qǐng nǐ yòng zhōngwén shuō yí jù huà。', example_vietnamese = 'Xin bạn hãy nói một câu bằng tiếng Trung.' WHERE level = 'B1' AND hanzi = '句' AND pinyin = 'jù' AND vietnamese = 'Câu';
UPDATE public.dictionary_words SET example_hanzi = '老同學們決定週末聚一聚。', example_pinyin = 'lǎo tóngxué men juédìng zhōumò jù yi jù。', example_vietnamese = 'Các bạn học cũ quyết định cuối tuần tụ họp một chút.' WHERE level = 'B1' AND hanzi = '聚' AND pinyin = 'jù' AND vietnamese = 'Tụ tập';
UPDATE public.dictionary_words SET example_hanzi = '這部電影的劇本寫得非常精彩。', example_pinyin = 'zhè bù diànyǐng de jùběn xiě de fēicháng jīngcǎi。', example_vietnamese = 'Kịch bản của bộ phim này được viết rất xuất sắc.' WHERE level = 'B1' AND hanzi = '劇本' AND pinyin = 'jùběn' AND vietnamese = 'kịch bản';
UPDATE public.dictionary_words SET example_hanzi = '這部連續劇的劇情越來越吸引人。', example_pinyin = 'zhè bù liánxùjù de jùqíng yuèláiyuè xīyǐn rén。', example_vietnamese = 'Tình tiết của bộ phim truyền hình này ngày càng hấp dẫn.' WHERE level = 'B1' AND hanzi = '劇情' AND pinyin = 'jùqíng' AND vietnamese = 'Tình tiết vở kịch';
UPDATE public.dictionary_words SET example_hanzi = '他禮貌地拒絕了對方的邀請。', example_pinyin = 'tā lǐmào de jùjué le duìfāng de yāoqǐng。', example_vietnamese = 'Anh ấy lịch sự từ chối lời mời của đối phương.' WHERE level = 'B1' AND hanzi = '拒絕' AND pinyin = 'jùjué' AND vietnamese = 'Từ chối, cự tuyệt';
UPDATE public.dictionary_words SET example_hanzi = '學校距離我家只有五分鐘的路程。', example_pinyin = 'xuéxiào jùlí wǒ jiā zhǐyǒu wǔ fēnzhōng de lùchéng。', example_vietnamese = 'Trường học cách nhà tôi chỉ năm phút đi bộ.' WHERE level = 'B1' AND hanzi = '距離' AND pinyin = 'jùlí' AND vietnamese = 'Khoảng cách, cự ly';
UPDATE public.dictionary_words SET example_hanzi = '這項計畫具有很大的發展潛力。', example_pinyin = 'zhè xiàng jìhuà jùyǒu hěn dà de fāzhǎn qiánlì。', example_vietnamese = 'Kế hoạch này có tiềm năng phát triển rất lớn.' WHERE level = 'B1' AND hanzi = '具有' AND pinyin = 'jùyŏu' AND vietnamese = 'Có, vốn có';
UPDATE public.dictionary_words SET example_hanzi = '我絕對不會答應這種事。', example_pinyin = 'wǒ juéduì bú huì dāying zhè zhǒng shì。', example_vietnamese = 'Tôi tuyệt đối sẽ không đồng ý chuyện như vậy.' WHERE level = 'B1' AND hanzi = '絕對' AND pinyin = 'juéduì' AND vietnamese = 'Tuyệt đối';
UPDATE public.dictionary_words SET example_hanzi = '他的哥哥在軍隊裡服役兩年。', example_pinyin = 'tā de gēge zài jūnduì lǐ fúyì liǎng nián。', example_vietnamese = 'Anh trai của anh ấy phục vụ trong quân đội hai năm.' WHERE level = 'B1' AND hanzi = '軍隊' AND pinyin = 'jūnduì' AND vietnamese = 'Quân đội';
UPDATE public.dictionary_words SET example_hanzi = '他從小的夢想就是成為一名軍人。', example_pinyin = 'tā cóngxiǎo de mèngxiǎng jiùshì chéngwéi yì míng jūnrén。', example_vietnamese = 'Ước mơ từ nhỏ của anh ấy là trở thành một quân nhân.' WHERE level = 'B1' AND hanzi = '軍人' AND pinyin = 'jūnrén' AND vietnamese = 'Quân nhân';
UPDATE public.dictionary_words SET example_hanzi = '一輛卡車擋住了整條路。', example_pinyin = 'yí liàng kǎchē dǎngzhù le zhěng tiáo lù。', example_vietnamese = 'Một chiếc xe tải chắn ngang cả con đường.' WHERE level = 'B1' AND hanzi = '卡車' AND pinyin = 'kǎchē' AND vietnamese = 'Xe tải';
UPDATE public.dictionary_words SET example_hanzi = '這座公園全天開放，不收門票。', example_pinyin = 'zhè zuò gōngyuán quántiān kāifàng，bù shōu ménpiào。', example_vietnamese = 'Công viên này mở cửa cả ngày, không thu vé vào cổng.' WHERE level = 'B1' AND hanzi = '開放' AND pinyin = 'kāifàng' AND vietnamese = 'Mở bỏ phong tỏa';
UPDATE public.dictionary_words SET example_hanzi = '春天一到，櫻花就開花了。', example_pinyin = 'chūntiān yí dào，yīnghuā jiù kāihuā le。', example_vietnamese = 'Mùa xuân vừa đến, hoa anh đào liền nở rộ.' WHERE level = 'B1' AND hanzi = '開花' AND pinyin = 'kāihuā' AND vietnamese = 'Nở hoa';
UPDATE public.dictionary_words SET example_hanzi = '她的個性開朗，很容易交到朋友。', example_pinyin = 'tā de gèxìng kāilǎng，hěn róngyì jiāo dào péngyǒu。', example_vietnamese = 'Tính cách của cô ấy cởi mở nên rất dễ kết bạn.' WHERE level = 'B1' AND hanzi = '開朗' AND pinyin = 'kāilăng' AND vietnamese = 'Thoáng mát';
UPDATE public.dictionary_words SET example_hanzi = '電影再五分鐘就要開始了。', example_pinyin = 'diànyǐng zài wǔ fēnzhōng jiù yào kāishǐ le。', example_vietnamese = 'Năm phút nữa bộ phim sẽ bắt đầu.' WHERE level = 'B1' AND hanzi = '開始' AND pinyin = 'kāishǐ' AND vietnamese = 'Bắt đầu';
UPDATE public.dictionary_words SET example_hanzi = '別生氣，我只是跟你開玩笑而已。', example_pinyin = 'bié shēngqì，wǒ zhǐshì gēn nǐ kāiwánxiào éryǐ。', example_vietnamese = 'Đừng giận, tôi chỉ đùa với bạn thôi.' WHERE level = 'B1' AND hanzi = '開玩笑' AND pinyin = 'kāiwánxiào' AND vietnamese = 'Đùa, giỡn';
UPDATE public.dictionary_words SET example_hanzi = '你不應該因為他家窮就看不起他。', example_pinyin = 'nǐ bù yīnggāi yīnwèi tā jiā qióng jiù kànbuqǐ tā。', example_vietnamese = 'Bạn không nên vì gia đình anh ấy nghèo mà khinh thường anh ấy.' WHERE level = 'B1' AND hanzi = '看不起' AND pinyin = 'kànbuqĭ' AND vietnamese = 'Khinh thường, xem thường';
UPDATE public.dictionary_words SET example_hanzi = '每個人對這件事的看法都不一樣。', example_pinyin = 'měi ge rén duì zhè jiàn shì de kànfǎ dōu bù yíyàng。', example_vietnamese = 'Mỗi người có quan điểm khác nhau về việc này.' WHERE level = 'B1' AND hanzi = '看法' AND pinyin = 'kànfǎ' AND vietnamese = 'Cách nhìn, quan điểm';
UPDATE public.dictionary_words SET example_hanzi = '天空烏雲密布，看起來快要下雨了。', example_pinyin = 'tiānkōng wūyún mìbù，kànqǐlái kuàiyào xiàyǔ le。', example_vietnamese = 'Bầu trời đầy mây đen, trông có vẻ sắp mưa rồi.' WHERE level = 'B1' AND hanzi = '看起來' AND pinyin = 'kànqĭlái' AND vietnamese = 'Xem ra, coi như';
UPDATE public.dictionary_words SET example_hanzi = '明天要考數學，我今晚得好好複習。', example_pinyin = 'míngtiān yào kǎo shùxué，wǒ jīnwǎn děi hǎohǎo fùxí。', example_vietnamese = 'Ngày mai phải thi toán, tối nay tôi phải ôn tập thật kỹ.' WHERE level = 'B1' AND hanzi = '考' AND pinyin = 'kǎo' AND vietnamese = 'Thi, hỏi, đố';
UPDATE public.dictionary_words SET example_hanzi = '院子裡種了三棵大樹。', example_pinyin = 'yuànzi lǐ zhòng le sān kē dà shù。', example_vietnamese = 'Trong sân trồng ba cây cổ thụ.' WHERE level = 'B1' AND hanzi = '棵' AND pinyin = 'kē' AND vietnamese = 'Cây, ngọn';
UPDATE public.dictionary_words SET example_hanzi = '現在是三點一刻。', example_pinyin = 'xiànzài shì sān diǎn yí kè。', example_vietnamese = 'Bây giờ là ba giờ mười lăm.' WHERE level = 'B1' AND hanzi = '刻' AND pinyin = 'kè' AND vietnamese = 'Khắc, mười lăm phút';
UPDATE public.dictionary_words SET example_hanzi = '他是眼科的醫生。', example_pinyin = 'tā shì yǎnkē de yīshēng。', example_vietnamese = 'Anh ấy là bác sĩ khoa mắt.' WHERE level = 'B1' AND hanzi = '科' AND pinyin = 'kē' AND vietnamese = 'Môn học, môn, khoa';
UPDATE public.dictionary_words SET example_hanzi = '現代科技的發展改變了我們的生活方式。', example_pinyin = 'xiàndài kējì de fāzhǎn gǎibiàn le wǒmen de shēnghuó fāngshì。', example_vietnamese = 'Sự phát triển của khoa học kỹ thuật hiện đại đã thay đổi lối sống của chúng ta.' WHERE level = 'B1' AND hanzi = '科技' AND pinyin = 'kējì' AND vietnamese = 'Khoa học kĩ thuật';
UPDATE public.dictionary_words SET example_hanzi = '這個說法一點都不科學。', example_pinyin = 'zhège shuōfǎ yìdiǎn dōu bù kēxué。', example_vietnamese = 'Cách nói này hoàn toàn không khoa học chút nào.' WHERE level = 'B1' AND hanzi = '科學' AND pinyin = 'kēxué' AND vietnamese = 'Khoa học, ngành học';
UPDATE public.dictionary_words SET example_hanzi = '這個方法是否可行，還需要再討論。', example_pinyin = 'zhège fāngfǎ shìfǒu kěxíng，hái xūyào zài tǎolùn。', example_vietnamese = 'Phương pháp này có khả thi hay không, vẫn cần bàn bạc thêm.' WHERE level = 'B1' AND hanzi = '可' AND pinyin = 'kě' AND vietnamese = 'có thể, khả dĩ';
UPDATE public.dictionary_words SET example_hanzi = '他很想去，可他沒有時間。', example_pinyin = 'tā hěn xiǎng qù，kě tā méiyǒu shíjiān。', example_vietnamese = 'Anh ấy rất muốn đi, nhưng anh ấy không có thời gian.' WHERE level = 'B1' AND hanzi = '可' AND pinyin = 'kě' AND vietnamese = 'nhưng, mà';
UPDATE public.dictionary_words SET example_hanzi = '這個消息來源非常可靠。', example_pinyin = 'zhège xiāoxi láiyuán fēicháng kěkào。', example_vietnamese = 'Nguồn tin này rất đáng tin cậy.' WHERE level = 'B1' AND hanzi = '可靠' AND pinyin = 'kěkào' AND vietnamese = 'Đáng tin';
UPDATE public.dictionary_words SET example_hanzi = '他點了一份漢堡和一杯可樂。', example_pinyin = 'tā diǎn le yí fèn hànbǎo hé yì bēi kělè。', example_vietnamese = 'Anh ấy gọi một phần hamburger và một ly cô-ca.' WHERE level = 'B1' AND hanzi = '可樂' AND pinyin = 'kělè' AND vietnamese = 'Cô-ca';
UPDATE public.dictionary_words SET example_hanzi = '那個小偷真是太可惡了。', example_pinyin = 'nàge xiǎotōu zhēnshi tài kěwù le。', example_vietnamese = 'Tên trộm đó thật đáng ghét quá.' WHERE level = 'B1' AND hanzi = '可惡' AND pinyin = 'kěwù' AND vietnamese = 'Đáng ghét, đáng giận';
UPDATE public.dictionary_words SET example_hanzi = '這麼好的機會錯過了，真可惜。', example_pinyin = 'zhème hǎo de jīhuì cuòguò le，zhēn kěxí。', example_vietnamese = 'Cơ hội tốt như vậy mà bị bỏ lỡ, thật đáng tiếc.' WHERE level = 'B1' AND hanzi = '可惜' AND pinyin = 'kěxí' AND vietnamese = 'Đáng tiếc';
UPDATE public.dictionary_words SET example_hanzi = '你可以借我一枝筆嗎？', example_pinyin = 'nǐ kěyǐ jiè wǒ yì zhī bǐ ma？', example_vietnamese = 'Bạn có thể cho tôi mượn một cây bút được không?' WHERE level = 'B1' AND hanzi = '可以' AND pinyin = 'kěyǐ' AND vietnamese = 'Có thể';
UPDATE public.dictionary_words SET example_hanzi = '每個孩子都渴望得到父母的關愛。', example_pinyin = 'měi ge háizi dōu kěwàng dédào fùmǔ de guānài。', example_vietnamese = 'Đứa trẻ nào cũng khát khao nhận được tình yêu thương của cha mẹ.' WHERE level = 'B1' AND hanzi = '渴望' AND pinyin = 'kěwàng' AND vietnamese = 'Khát vọng, khát khao';
UPDATE public.dictionary_words SET example_hanzi = '這個食譜需要兩百克的麵粉。', example_pinyin = 'zhège shípǔ xūyào liǎngbǎi kè de miànfěn。', example_vietnamese = 'Công thức này cần hai trăm gram bột mì.' WHERE level = 'B1' AND hanzi = '克' AND pinyin = 'kè' AND vietnamese = 'Khắc, khắc chế';
UPDATE public.dictionary_words SET example_hanzi = '只要努力，就能克服眼前的困難。', example_pinyin = 'zhǐyào nǔlì，jiù néng kèfú yǎnqián de kùnnán。', example_vietnamese = 'Chỉ cần cố gắng thì có thể khắc phục khó khăn trước mắt.' WHERE level = 'B1' AND hanzi = '克服' AND pinyin = 'kèfú' AND vietnamese = 'Khắc phục';
UPDATE public.dictionary_words SET example_hanzi = '這學期的課程比上學期難多了。', example_pinyin = 'zhè xuéqí de kèchéng bǐ shàng xuéqí nán duō le。', example_vietnamese = 'Chương trình học kỳ này khó hơn nhiều so với học kỳ trước.' WHERE level = 'B1' AND hanzi = '課程' AND pinyin = 'kèchéng' AND vietnamese = 'Chương trình học';
UPDATE public.dictionary_words SET example_hanzi = '課堂上請大家專心聽講。', example_pinyin = 'kètáng shàng qǐng dàjiā zhuānxīn tīngjiǎng。', example_vietnamese = 'Trong lớp học, xin mọi người chú ý nghe giảng.' WHERE level = 'B1' AND hanzi = '課堂' AND pinyin = 'kètáng' AND vietnamese = 'Tại lớp, trong lớp';
UPDATE public.dictionary_words SET example_hanzi = '老師要我們把這一課的課文背下來。', example_pinyin = 'lǎoshī yào wǒmen bǎ zhè yí kè de kèwén bèi xiàlái。', example_vietnamese = 'Thầy giáo yêu cầu chúng tôi học thuộc lòng bài khóa này.' WHERE level = 'B1' AND hanzi = '課文' AND pinyin = 'kèwén' AND vietnamese = 'Bài khóa, bài văn';
UPDATE public.dictionary_words SET example_hanzi = '這家餐廳每到假日就客滿。', example_pinyin = 'zhè jiā cāntīng měi dào jiàrì jiù kèmǎn。', example_vietnamese = 'Nhà hàng này cứ đến ngày lễ là hết chỗ.' WHERE level = 'B1' AND hanzi = '客滿' AND pinyin = 'kèmăn' AND vietnamese = 'Không còn chỗ trống';
UPDATE public.dictionary_words SET example_hanzi = '他在木頭上刻了一隻小鳥。', example_pinyin = 'tā zài mùtóu shàng kè le yì zhī xiǎoniǎo。', example_vietnamese = 'Anh ấy khắc một con chim nhỏ lên khúc gỗ.' WHERE level = 'B1' AND hanzi = '刻' AND pinyin = 'kè' AND vietnamese = 'Khắc';
UPDATE public.dictionary_words SET example_hanzi = '不管我怎麼勸，他都不肯道歉。', example_pinyin = 'bùguǎn wǒ zěnme quàn，tā dōu bù kěn dàoqiàn。', example_vietnamese = 'Dù tôi khuyên thế nào, anh ấy cũng không chịu xin lỗi.' WHERE level = 'B1' AND hanzi = '肯' AND pinyin = 'kěn' AND vietnamese = 'Đồng ý, tán thành';
UPDATE public.dictionary_words SET example_hanzi = '老師肯定了我們這次的努力。', example_pinyin = 'lǎoshī kěndìng le wǒmen zhècì de nǔlì。', example_vietnamese = 'Thầy giáo đã ghi nhận nỗ lực của chúng tôi lần này.' WHERE level = 'B1' AND hanzi = '肯定' AND pinyin = 'kěndìng' AND vietnamese = 'Khẳng định';
UPDATE public.dictionary_words SET example_hanzi = '冰箱裡什麼都沒有，空空的。', example_pinyin = 'bīngxiāng lǐ shénme dōu méiyǒu，kōngkōng de。', example_vietnamese = 'Trong tủ lạnh chẳng có gì cả, trống trơn.' WHERE level = 'B1' AND hanzi = '空' AND pinyin = 'kōng' AND vietnamese = 'Trống không';
UPDATE public.dictionary_words SET example_hanzi = '這間房子的空間不大，但很舒服。', example_pinyin = 'zhè jiān fángzi de kōngjiān bú dà，dàn hěn shūfú。', example_vietnamese = 'Không gian của căn nhà này không lớn nhưng rất thoải mái.' WHERE level = 'B1' AND hanzi = '空間' AND pinyin = 'kōngjiān' AND vietnamese = 'Không gian';
UPDATE public.dictionary_words SET example_hanzi = '他大學畢業後選擇加入空軍。', example_pinyin = 'tā dàxué bìyè hòu xuǎnzé jiārù kōngjūn。', example_vietnamese = 'Sau khi tốt nghiệp đại học, anh ấy chọn gia nhập không quân.' WHERE level = 'B1' AND hanzi = '空軍' AND pinyin = 'kōngjūn' AND vietnamese = 'Không quân';
UPDATE public.dictionary_words SET example_hanzi = '恐怕明天會下雨，你最好帶把傘。', example_pinyin = 'kǒngpà míngtiān huì xiàyǔ，nǐ zuìhǎo dài bǎ sǎn。', example_vietnamese = 'E rằng ngày mai sẽ mưa, bạn nên mang theo ô.' WHERE level = 'B1' AND hanzi = '恐怕' AND pinyin = 'kǒngpà' AND vietnamese = 'E rằng, sợ rằng';
UPDATE public.dictionary_words SET example_hanzi = '你今天下午有空嗎？', example_pinyin = 'nǐ jīntiān xiàwǔ yǒu kòng ma？', example_vietnamese = 'Chiều nay bạn có rảnh không?' WHERE level = 'B1' AND hanzi = '空' AND pinyin = 'kòng' AND vietnamese = 'Trống rỗng';
UPDATE public.dictionary_words SET example_hanzi = '他張開口，卻一句話也說不出來。', example_pinyin = 'tā zhāngkāi kǒu，què yí jù huà yě shuō bù chūlái。', example_vietnamese = 'Anh ấy mở miệng ra nhưng không nói được lời nào.' WHERE level = 'B1' AND hanzi = '口' AND pinyin = 'kǒu' AND vietnamese = 'Miệng';
UPDATE public.dictionary_words SET example_hanzi = '他把鑰匙放進褲子的口袋裡。', example_pinyin = 'tā bǎ yàoshi fàng jìn kùzi de kǒudài lǐ。', example_vietnamese = 'Anh ấy bỏ chìa khóa vào túi quần.' WHERE level = 'B1' AND hanzi = '口袋' AND pinyin = 'kǒudài' AND vietnamese = 'Túi áo, túi, bao';
UPDATE public.dictionary_words SET example_hanzi = '這家店的菜很符合台灣人的口味。', example_pinyin = 'zhè jiā diàn de cài hěn fúhé táiwān rén de kǒuwèi。', example_vietnamese = 'Món ăn của quán này rất hợp khẩu vị người Đài Loan.' WHERE level = 'B1' AND hanzi = '口味' AND pinyin = 'kŏuwèi' AND vietnamese = 'Khẩu vị, hương vị';
UPDATE public.dictionary_words SET example_hanzi = '他說的話太誇張了，我不太相信。', example_pinyin = 'tā shuō de huà tài kuāzhāng le，wǒ bú tài xiāngxìn。', example_vietnamese = 'Những lời anh ấy nói quá phóng đại, tôi không tin lắm.' WHERE level = 'B1' AND hanzi = '誇張' AND pinyin = 'kuāzhāng' AND vietnamese = 'Khoa trương';
UPDATE public.dictionary_words SET example_hanzi = '快一點，公車快要來了！', example_pinyin = 'kuài yìdiǎn，gōngchē kuàiyào lái le！', example_vietnamese = 'Nhanh lên, xe buýt sắp đến rồi!' WHERE level = 'B1' AND hanzi = '快' AND pinyin = 'kuài' AND vietnamese = 'Nhanh';
UPDATE public.dictionary_words SET example_hanzi = '火車快要進站了，請大家準備上車。', example_pinyin = 'huǒchē kuàiyào jìn zhàn le，qǐng dàjiā zhǔnbèi shàngchē。', example_vietnamese = 'Tàu hỏa sắp vào ga rồi, mời mọi người chuẩn bị lên tàu.' WHERE level = 'B1' AND hanzi = '快要' AND pinyin = 'kuàiyào' AND vietnamese = 'Sắp, suýt';
UPDATE public.dictionary_words SET example_hanzi = '這條馬路又寬又長。', example_pinyin = 'zhè tiáo mǎlù yòu kuān yòu cháng。', example_vietnamese = 'Con đường này vừa rộng vừa dài.' WHERE level = 'B1' AND hanzi = '寬' AND pinyin = 'kuān' AND vietnamese = 'Rộng, bao quát';
UPDATE public.dictionary_words SET example_hanzi = '這件衣服太貴了，況且顏色也不適合我。', example_pinyin = 'zhè jiàn yīfú tài guì le，kuàngqiě yánsè yě bú shìhé wǒ。', example_vietnamese = 'Chiếc áo này quá đắt, vả lại màu sắc cũng không hợp với tôi.' WHERE level = 'B1' AND hanzi = '況且' AND pinyin = 'kuàngqiě' AND vietnamese = 'Vả lại';
UPDATE public.dictionary_words SET example_hanzi = '學習一門新語言會遇到不少困難。', example_pinyin = 'xuéxí yì mén xīn yǔyán huì yùdào bù shǎo kùnnán。', example_vietnamese = 'Học một ngôn ngữ mới sẽ gặp không ít khó khăn.' WHERE level = 'B1' AND hanzi = '困難' AND pinyin = 'kùnnán' AND vietnamese = 'Khó khăn, trở ngại';
UPDATE public.dictionary_words SET example_hanzi = '家裡經濟比較困難，他很早就開始打工。', example_pinyin = 'jiālǐ jīngjì bǐjiào kùnnán，tā hěn zǎo jiù kāishǐ dǎgōng。', example_vietnamese = 'Kinh tế gia đình khá khó khăn nên anh ấy đi làm thêm từ rất sớm.' WHERE level = 'B1' AND hanzi = '困難' AND pinyin = 'kùnnán' AND vietnamese = 'Gặp trắc trở, khó khăn';
UPDATE public.dictionary_words SET example_hanzi = '公司決定擴大生產規模。', example_pinyin = 'gōngsī juédìng kuòdà shēngchǎn guīmó。', example_vietnamese = 'Công ty quyết định mở rộng quy mô sản xuất.' WHERE level = 'B1' AND hanzi = '擴大' AND pinyin = 'kuòdà' AND vietnamese = 'Mở rộng, tăng thêm';
UPDATE public.dictionary_words SET example_hanzi = '他昨晚吃壞肚子，一直拉肚子。', example_pinyin = 'tā zuówǎn chī huài dùzi，yìzhí lādùzi。', example_vietnamese = 'Tối qua anh ấy ăn phải đồ xấu bụng nên cứ bị tiêu chảy.' WHERE level = 'B1' AND hanzi = '拉肚子' AND pinyin = 'lādùzi' AND vietnamese = 'Bị đau bụng, tiêu chảy';
UPDATE public.dictionary_words SET example_hanzi = '好啦好啦，我知道了啦！', example_pinyin = 'hǎo la hǎo la，wǒ zhīdào le la！', example_vietnamese = 'Được rồi được rồi, tôi biết rồi mà!' WHERE level = 'B1' AND hanzi = '啦' AND pinyin = 'la' AND vietnamese = 'Đấy, nhé';
UPDATE public.dictionary_words SET example_hanzi = '明天請你來我家吃飯。', example_pinyin = 'míngtiān qǐng nǐ lái wǒ jiā chīfàn。', example_vietnamese = 'Ngày mai mời bạn đến nhà tôi ăn cơm.' WHERE level = 'B1' AND hanzi = '來' AND pinyin = 'lái' AND vietnamese = 'Đến';
UPDATE public.dictionary_words SET example_hanzi = '他臨時請假，這麼一來，計畫全都亂了。', example_pinyin = 'tā línshí qǐngjià，zhème yì lái，jìhuà quán dōu luàn le。', example_vietnamese = 'Anh ấy đột xuất xin nghỉ, thế là kế hoạch hoàn toàn bị đảo lộn.' WHERE level = 'B1' AND hanzi = '來' AND pinyin = 'lái' AND vietnamese = 'Xảy đến, xảy ra';
UPDATE public.dictionary_words SET example_hanzi = '再不出門就來不及搭飛機了。', example_pinyin = 'zài bù chūmén jiù láibùjí dā fēijī le。', example_vietnamese = 'Không ra khỏi nhà ngay thì sẽ không kịp lên máy bay.' WHERE level = 'B1' AND hanzi = '來不及' AND pinyin = 'láibùjí' AND vietnamese = 'Không kịp';
UPDATE public.dictionary_words SET example_hanzi = '現在出發還來得及趕上火車。', example_pinyin = 'xiànzài chūfā hái láidejí gǎnshàng huǒchē。', example_vietnamese = 'Bây giờ xuất phát vẫn còn kịp bắt kịp chuyến tàu.' WHERE level = 'B1' AND hanzi = '來得及' AND pinyin = 'láidejí' AND vietnamese = 'Kịp, còn kịp';
UPDATE public.dictionary_words SET example_hanzi = '今天的天空非常藍。', example_pinyin = 'jīntiān de tiānkōng fēicháng lán。', example_vietnamese = 'Bầu trời hôm nay xanh lam vô cùng.' WHERE level = 'B1' AND hanzi = '藍' AND pinyin = 'lán' AND vietnamese = 'Lam, xanh lam';
UPDATE public.dictionary_words SET example_hanzi = '他在海邊為女朋友辦了一場浪漫的求婚。', example_pinyin = 'tā zài hǎibiān wèi nǚpéngyǒu bàn le yì chǎng làngmàn de qiúhūn。', example_vietnamese = 'Anh ấy đã tổ chức một buổi cầu hôn lãng mạn cho bạn gái bên bờ biển.' WHERE level = 'B1' AND hanzi = '浪漫' AND pinyin = 'làngmàn' AND vietnamese = 'Lãng mạn';
UPDATE public.dictionary_words SET example_hanzi = '我老公每天早上都會送我去上班。', example_pinyin = 'wǒ lǎogōng měitiān zǎoshang dōu huì sòng wǒ qù shàngbān。', example_vietnamese = 'Chồng tôi sáng nào cũng đưa tôi đi làm.' WHERE level = 'B1' AND hanzi = '老公' AND pinyin = 'lăogōng' AND vietnamese = 'Chồng';
UPDATE public.dictionary_words SET example_hanzi = '動物園裡的老虎正在睡覺。', example_pinyin = 'dòngwùyuán lǐ de lǎohǔ zhèngzài shuìjiào。', example_vietnamese = 'Con hổ trong sở thú đang ngủ.' WHERE level = 'B1' AND hanzi = '老虎' AND pinyin = 'lăohŭ' AND vietnamese = 'Con hổ';
UPDATE public.dictionary_words SET example_hanzi = '他的老婆是一位小學老師。', example_pinyin = 'tā de lǎopo shì yí wèi xiǎoxué lǎoshī。', example_vietnamese = 'Vợ của anh ấy là một giáo viên tiểu học.' WHERE level = 'B1' AND hanzi = '老婆' AND pinyin = 'lăopo' AND vietnamese = 'Vợ';
UPDATE public.dictionary_words SET example_hanzi = '他是個很老實的人，從不說謊。', example_pinyin = 'tā shì ge hěn lǎoshi de rén，cóng bù shuōhuǎng。', example_vietnamese = 'Anh ấy là người rất trung thực, chưa bao giờ nói dối.' WHERE level = 'B1' AND hanzi = '老實' AND pinyin = 'lăoshi' AND vietnamese = 'Trung thành, trung thực';
UPDATE public.dictionary_words SET example_hanzi = '他老是遲到，讓大家等他。', example_pinyin = 'tā lǎoshì chídào，ràng dàjiā děng tā。', example_vietnamese = 'Anh ấy cứ đi trễ hoài, khiến mọi người phải chờ.' WHERE level = 'B1' AND hanzi = '老是' AND pinyin = 'lăoshì' AND vietnamese = 'Luôn luôn';
UPDATE public.dictionary_words SET example_hanzi = '他樂於幫助身邊的每一個人。', example_pinyin = 'tā lèyú bāngzhù shēnbiān de měi yí ge rén。', example_vietnamese = 'Anh ấy luôn vui vẻ giúp đỡ mọi người xung quanh mình.' WHERE level = 'B1' AND hanzi = '樂' AND pinyin = 'lè' AND vietnamese = 'Âm nhạc';
UPDATE public.dictionary_words SET example_hanzi = '即使遇到困難，她還是很樂觀。', example_pinyin = 'jíshǐ yùdào kùnnán，tā háishì hěn lèguān。', example_vietnamese = 'Dù gặp khó khăn, cô ấy vẫn rất lạc quan.' WHERE level = 'B1' AND hanzi = '樂觀' AND pinyin = 'lèguān' AND vietnamese = 'Lạc quan, vui vẻ';
UPDATE public.dictionary_words SET example_hanzi = '學習語言的樂趣在於能認識新的文化。', example_pinyin = 'xuéxí yǔyán de lèqù zàiyú néng rènshi xīn de wénhuà。', example_vietnamese = 'Niềm vui của việc học ngôn ngữ nằm ở chỗ có thể tìm hiểu nền văn hóa mới.' WHERE level = 'B1' AND hanzi = '樂趣' AND pinyin = 'lèqù' AND vietnamese = 'Niềm vui, hứng thú';
UPDATE public.dictionary_words SET example_hanzi = '請把垃圾丟到垃圾桶裡。', example_pinyin = 'qǐng bǎ lèsè diū dào lèsètǒng lǐ。', example_vietnamese = 'Xin hãy vứt rác vào thùng rác.' WHERE level = 'B1' AND hanzi = '垃圾' AND pinyin = 'lèsè' AND vietnamese = 'Rác, rác thải';
UPDATE public.dictionary_words SET example_hanzi = '聽完這個故事，她的眼淚忍不住流了下來。', example_pinyin = 'tīng wán zhège gùshì，tā de yǎnlèi rěnbúzhù liú le xiàlái。', example_vietnamese = 'Nghe xong câu chuyện này, nước mắt cô ấy không kìm được mà chảy xuống.' WHERE level = 'B1' AND hanzi = '淚' AND pinyin = 'lèi' AND vietnamese = 'Nước mắt, lệ';
UPDATE public.dictionary_words SET example_hanzi = '這類問題很常見，不用太擔心。', example_pinyin = 'zhè lèi wèntí hěn chángjiàn，búyòng tài dānxīn。', example_vietnamese = 'Loại vấn đề này rất thường gặp, không cần quá lo lắng.' WHERE level = 'B1' AND hanzi = '類' AND pinyin = 'lèi' AND vietnamese = 'Chủng loại';
UPDATE public.dictionary_words SET example_hanzi = '最近他對我的態度變得很冷淡。', example_pinyin = 'zuìjìn tā duì wǒ de tàidù biàn de hěn lěngdàn。', example_vietnamese = 'Gần đây thái độ của anh ấy đối với tôi trở nên rất lạnh nhạt.' WHERE level = 'B1' AND hanzi = '冷淡' AND pinyin = 'lěngdàn' AND vietnamese = 'Vắng lặng, lạnh nhạt';
UPDATE public.dictionary_words SET example_hanzi = '這裡離火車站不遠。', example_pinyin = 'zhèlǐ lí huǒchēzhàn bù yuǎn。', example_vietnamese = 'Chỗ này cách nhà ga không xa.' WHERE level = 'B1' AND hanzi = '離' AND pinyin = 'lí' AND vietnamese = 'Xa rời, xa cách';
UPDATE public.dictionary_words SET example_hanzi = '他們結婚三年後就離婚了。', example_pinyin = 'tāmen jiéhūn sān nián hòu jiù líhūn le。', example_vietnamese = 'Họ kết hôn được ba năm thì ly hôn.' WHERE level = 'B1' AND hanzi = '離婚' AND pinyin = 'líhūn' AND vietnamese = 'Li dị, li hôn';
UPDATE public.dictionary_words SET example_hanzi = '這座山離山頂還有五里路。', example_pinyin = 'zhè zuò shān lí shāndǐng hái yǒu wǔ lǐ lù。', example_vietnamese = 'Ngọn núi này còn cách đỉnh núi năm dặm đường nữa.' WHERE level = 'B1' AND hanzi = '里' AND pinyin = 'lǐ' AND vietnamese = 'dặm (đơn vị đo chiều dài)';
UPDATE public.dictionary_words SET example_hanzi = '箱子裡邊裝滿了舊衣服。', example_pinyin = 'xiāngzi lǐbiān zhuāng mǎn le jiù yīfú。', example_vietnamese = 'Bên trong thùng chứa đầy quần áo cũ.' WHERE level = 'B1' AND hanzi = '裡邊' AND pinyin = 'lĭbiān' AND vietnamese = 'Bên trong';
UPDATE public.dictionary_words SET example_hanzi = '我完全能理解你現在的心情。', example_pinyin = 'wǒ wánquán néng lǐjiě nǐ xiànzài de xīnqíng。', example_vietnamese = 'Tôi hoàn toàn có thể hiểu được tâm trạng của bạn lúc này.' WHERE level = 'B1' AND hanzi = '理解' AND pinyin = 'lĭjiě' AND vietnamese = 'Hiểu, tìm hiểu';
UPDATE public.dictionary_words SET example_hanzi = '這個理論聽起來很有道理，但很難證明。', example_pinyin = 'zhège lǐlùn tīngqǐlái hěn yǒu dàolǐ，dàn hěn nán zhèngmíng。', example_vietnamese = 'Lý thuyết này nghe có vẻ hợp lý nhưng rất khó chứng minh.' WHERE level = 'B1' AND hanzi = '理論' AND pinyin = 'lĭlùn' AND vietnamese = 'Lý luận, lý thuyết';
UPDATE public.dictionary_words SET example_hanzi = '成為一名醫生是他從小的理想。', example_pinyin = 'chéngwéi yì míng yīshēng shì tā cóngxiǎo de lǐxiǎng。', example_vietnamese = 'Trở thành một bác sĩ là lý tưởng từ nhỏ của anh ấy.' WHERE level = 'B1' AND hanzi = '理想' AND pinyin = 'lĭxiăng' AND vietnamese = 'Lý tưởng';
UPDATE public.dictionary_words SET example_hanzi = '這次考試的結果不太理想。', example_pinyin = 'zhècì kǎoshì de jiéguǒ bú tài lǐxiǎng。', example_vietnamese = 'Kết quả kỳ thi lần này không được lý tưởng cho lắm.' WHERE level = 'B1' AND hanzi = '理想' AND pinyin = 'lĭxiăng' AND vietnamese = 'Ước vọng, hy vọng';
UPDATE public.dictionary_words SET example_hanzi = '房間裏面很乾淨，也很整齊。', example_pinyin = 'fángjiān lǐmiàn hěn gānjìng，yě hěn zhěngqí。', example_vietnamese = 'Bên trong phòng rất sạch sẽ và gọn gàng.' WHERE level = 'B1' AND hanzi = '裏面' AND pinyin = 'lǐmiàn' AND vietnamese = 'Bên trong';
UPDATE public.dictionary_words SET example_hanzi = '畢業典禮在學校的禮堂舉行。', example_pinyin = 'bìyè diǎnlǐ zài xuéxiào de lǐtáng jǔxíng。', example_vietnamese = 'Lễ tốt nghiệp được tổ chức tại hội trường của trường.' WHERE level = 'B1' AND hanzi = '禮堂' AND pinyin = 'lĭtáng' AND vietnamese = 'Lễ đường';
UPDATE public.dictionary_words SET example_hanzi = '他用力推開了門。', example_pinyin = 'tā yònglì tuī kāi le mén。', example_vietnamese = 'Anh ấy dùng sức đẩy mở cánh cửa.' WHERE level = 'B1' AND hanzi = '力' AND pinyin = 'lì' AND vietnamese = 'Lực, sức lực';
UPDATE public.dictionary_words SET example_hanzi = '團結就是力量。', example_pinyin = 'tuánjié jiùshì lìliàng。', example_vietnamese = 'Đoàn kết chính là sức mạnh.' WHERE level = 'B1' AND hanzi = '力量' AND pinyin = 'lìlìang' AND vietnamese = 'Lực lượng, sức mạnh';
UPDATE public.dictionary_words SET example_hanzi = '他打籃球打得真厲害。', example_pinyin = 'tā dǎ lánqiú dǎ de zhēn lìhai。', example_vietnamese = 'Anh ấy chơi bóng rổ giỏi thật đấy.' WHERE level = 'B1' AND hanzi = '厲害' AND pinyin = 'lìhai' AND vietnamese = 'Lợi hại, gay gắt, dữ dội';
UPDATE public.dictionary_words SET example_hanzi = '聽到消息後，他立刻趕到醫院。', example_pinyin = 'tīngdào xiāoxi hòu，tā lìkè gǎndào yīyuàn。', example_vietnamese = 'Nghe được tin, anh ấy lập tức chạy đến bệnh viện.' WHERE level = 'B1' AND hanzi = '立刻' AND pinyin = 'lìkè' AND vietnamese = 'Ngay lập tức';
UPDATE public.dictionary_words SET example_hanzi = '這裡有很多水果，例如芒果、香蕉和西瓜。', example_pinyin = 'zhèlǐ yǒu hěn duō shuǐguǒ，lìrú mángguǒ、xiāngjiāo hé xīguā。', example_vietnamese = 'Ở đây có nhiều loại trái cây, ví dụ như xoài, chuối và dưa hấu.' WHERE level = 'B1' AND hanzi = '例如' AND pinyin = 'lìrú' AND vietnamese = 'Ví dụ';
UPDATE public.dictionary_words SET example_hanzi = '老師舉了一個例子幫我們理解這個文法。', example_pinyin = 'lǎoshī jǔ le yí ge lìzi bāng wǒmen lǐjiě zhège wénfǎ。', example_vietnamese = 'Thầy giáo đưa ra một ví dụ để giúp chúng tôi hiểu ngữ pháp này.' WHERE level = 'B1' AND hanzi = '例子' AND pinyin = 'lìzi' AND vietnamese = 'Thí dụ';
UPDATE public.dictionary_words SET example_hanzi = '這項政策符合大多數人的利益。', example_pinyin = 'zhè xiàng zhèngcè fúhé dàduōshù rén de lìyì。', example_vietnamese = 'Chính sách này phù hợp với lợi ích của đa số người dân.' WHERE level = 'B1' AND hanzi = '利益' AND pinyin = 'lìyì' AND vietnamese = 'Lợi ích, quyền lợi';
UPDATE public.dictionary_words SET example_hanzi = '我們應該好好利用時間讀書。', example_pinyin = 'wǒmen yīnggāi hǎohǎo lìyòng shíjiān dúshū。', example_vietnamese = 'Chúng ta nên tận dụng thời gian thật tốt để học tập.' WHERE level = 'B1' AND hanzi = '利用' AND pinyin = 'lìyòng' AND vietnamese = 'Sử dụng, dùng, lợi dụng';
UPDATE public.dictionary_words SET example_hanzi = '連小孩都知道這個道理。', example_pinyin = 'lián xiǎohái dōu zhīdào zhège dàolǐ。', example_vietnamese = 'Ngay cả trẻ con cũng biết đạo lý này.' WHERE level = 'B1' AND hanzi = '連' AND pinyin = 'lián' AND vietnamese = 'Ngay cả…';
UPDATE public.dictionary_words SET example_hanzi = '這座橋把兩座城市連了起來。', example_pinyin = 'zhè zuò qiáo bǎ liǎng zuò chéngshì lián le qǐlái。', example_vietnamese = 'Cây cầu này nối liền hai thành phố với nhau.' WHERE level = 'B1' AND hanzi = '連' AND pinyin = 'lián' AND vietnamese = 'Gắn bó, nối liền';
UPDATE public.dictionary_words SET example_hanzi = '出國以後，我們還是常常聯絡。', example_pinyin = 'chūguó yǐhòu，wǒmen háishì chángcháng liánluò。', example_vietnamese = 'Sau khi ra nước ngoài, chúng tôi vẫn thường xuyên liên lạc.' WHERE level = 'B1' AND hanzi = '連/聯絡' AND pinyin = 'liánluò' AND vietnamese = 'Liên lạc, liên hệ';
UPDATE public.dictionary_words SET example_hanzi = '媽媽每天晚上都準時收看那部連續劇。', example_pinyin = 'māma měitiān wǎnshàng dōu zhǔnshí shōukàn nà bù liánxùjù。', example_vietnamese = 'Tối nào mẹ cũng đúng giờ xem bộ phim truyền hình đó.' WHERE level = 'B1' AND hanzi = '連續劇' AND pinyin = 'liánxùjù' AND vietnamese = 'Phim bộ, phim nhiều tập';
UPDATE public.dictionary_words SET example_hanzi = '他每天都練書法，寫得越來越好。', example_pinyin = 'tā měitiān dōu liàn shūfǎ，xiě de yuèláiyuè hǎo。', example_vietnamese = 'Anh ấy luyện thư pháp mỗi ngày, viết ngày càng đẹp.' WHERE level = 'B1' AND hanzi = '練' AND pinyin = 'liàn' AND vietnamese = 'Luyện tập';
UPDATE public.dictionary_words SET example_hanzi = '他們兩個從大學就開始戀愛了。', example_pinyin = 'tāmen liǎng ge cóng dàxué jiù kāishǐ liànài le。', example_vietnamese = 'Hai người họ bắt đầu yêu nhau từ hồi đại học.' WHERE level = 'B1' AND hanzi = '戀愛' AND pinyin = 'liànài' AND vietnamese = 'Yêu đương';
UPDATE public.dictionary_words SET example_hanzi = '湯有點燙，等涼一點再喝。', example_pinyin = 'tāng yǒudiǎn tàng，děng liáng yìdiǎn zài hē。', example_vietnamese = 'Canh hơi nóng, đợi nguội một chút rồi hãy uống.' WHERE level = 'B1' AND hanzi = '涼' AND pinyin = 'liáng' AND vietnamese = 'Để nguội';
UPDATE public.dictionary_words SET example_hanzi = '保持良好的作息習慣對身體很重要。', example_pinyin = 'bǎochí liánghǎo de zuòxí xíguàn duì shēntǐ hěn zhòngyào。', example_vietnamese = 'Duy trì thói quen sinh hoạt tốt rất quan trọng đối với sức khỏe.' WHERE level = 'B1' AND hanzi = '良好' AND pinyin = 'liánghăo' AND vietnamese = 'Tốt đẹp';
UPDATE public.dictionary_words SET example_hanzi = '教室裡的燈很亮。', example_pinyin = 'jiàoshì lǐ de dēng hěn liàng。', example_vietnamese = 'Đèn trong lớp học rất sáng.' WHERE level = 'B1' AND hanzi = '亮' AND pinyin = 'liàng' AND vietnamese = 'Phát sáng';
UPDATE public.dictionary_words SET example_hanzi = '我們坐在咖啡店裡聊了一個下午。', example_pinyin = 'wǒmen zuò zài kāfēidiàn lǐ liáo le yí ge xiàwǔ。', example_vietnamese = 'Chúng tôi ngồi trong quán cà phê tán gẫu cả một buổi chiều.' WHERE level = 'B1' AND hanzi = '聊' AND pinyin = 'liáo' AND vietnamese = 'Nói chuyện phiếm';
UPDATE public.dictionary_words SET example_hanzi = '一個人能完成這麼大的計畫，真了不起。', example_pinyin = 'yí ge rén néng wánchéng zhème dà de jìhuà，zhēn liǎobuqǐ。', example_vietnamese = 'Một mình mà hoàn thành được kế hoạch lớn như vậy, thật tài giỏi.' WHERE level = 'B1' AND hanzi = '了不起' AND pinyin = 'liăobuqĭ' AND vietnamese = 'Giỏi lắm, khá lắm';
UPDATE public.dictionary_words SET example_hanzi = '音樂是這部電影的靈魂。', example_pinyin = 'yīnyuè shì zhè bù diànyǐng de línghún。', example_vietnamese = 'Âm nhạc chính là linh hồn của bộ phim này.' WHERE level = 'B1' AND hanzi = '靈魂' AND pinyin = 'línghún' AND vietnamese = 'Linh hồn';
UPDATE public.dictionary_words SET example_hanzi = '我身上沒有零錢，沒辦法坐公車。', example_pinyin = 'wǒ shēnshàng méiyǒu língqián，méi bànfǎ zuò gōngchē。', example_vietnamese = 'Tôi không có tiền lẻ nên không thể đi xe buýt.' WHERE level = 'B1' AND hanzi = '零錢' AND pinyin = 'língqián' AND vietnamese = 'Tiền lẻ';
UPDATE public.dictionary_words SET example_hanzi = '媽媽每個星期給我兩百塊零用錢。', example_pinyin = 'māma měi ge xīngqí gěi wǒ liǎngbǎi kuài língyòngqián。', example_vietnamese = 'Mỗi tuần mẹ cho tôi hai trăm đồng tiền tiêu vặt.' WHERE level = 'B1' AND hanzi = '零用錢' AND pinyin = 'língyòngqián' AND vietnamese = 'Tiền tiêu vặt';
UPDATE public.dictionary_words SET example_hanzi = '導遊領著我們參觀故宮。', example_pinyin = 'dǎoyóu lǐng zhe wǒmen cānguān gùgōng。', example_vietnamese = 'Hướng dẫn viên dẫn chúng tôi tham quan Cố Cung.' WHERE level = 'B1' AND hanzi = '領' AND pinyin = 'lǐng' AND vietnamese = 'Dẫn dắt';
UPDATE public.dictionary_words SET example_hanzi = '他很有能力領導這個團隊。', example_pinyin = 'tā hěn yǒu nénglì lǐngdǎo zhège tuánduì。', example_vietnamese = 'Anh ấy rất có năng lực lãnh đạo đội nhóm này.' WHERE level = 'B1' AND hanzi = '領導' AND pinyin = 'lĭngdăo' AND vietnamese = 'Lãnh đạo';
UPDATE public.dictionary_words SET example_hanzi = '他在人工智慧的領域做了很多研究。', example_pinyin = 'tā zài réngōng zhìhuì de lǐngyù zuò le hěn duō yánjiū。', example_vietnamese = 'Anh ấy đã thực hiện nhiều nghiên cứu trong lĩnh vực trí tuệ nhân tạo.' WHERE level = 'B1' AND hanzi = '領域' AND pinyin = 'lĭngyù' AND vietnamese = 'Lĩnh vực';
UPDATE public.dictionary_words SET example_hanzi = '這個消息令大家都很高興。', example_pinyin = 'zhège xiāoxi lìng dàjiā dōu hěn gāoxìng。', example_vietnamese = 'Tin tức này khiến mọi người đều rất vui mừng.' WHERE level = 'B1' AND hanzi = '令' AND pinyin = 'lìng' AND vietnamese = 'Ra lệnh';
UPDATE public.dictionary_words SET example_hanzi = '這條河從山上一直流到海邊。', example_pinyin = 'zhè tiáo hé cóng shānshàng yìzhí liú dào hǎibiān。', example_vietnamese = 'Con sông này chảy từ trên núi mãi ra đến biển.' WHERE level = 'B1' AND hanzi = '流' AND pinyin = 'liú' AND vietnamese = 'Chảy, đổ, di chuyển';
UPDATE public.dictionary_words SET example_hanzi = '運動半小時後，他已經滿身流汗。', example_pinyin = 'yùndòng bàn xiǎoshí hòu，tā yǐjīng mǎnshēn liúhàn。', example_vietnamese = 'Sau nửa tiếng vận động, anh ấy đã đổ mồ hôi đầy người.' WHERE level = 'B1' AND hanzi = '流汗' AND pinyin = 'liúhàn' AND vietnamese = 'Đổ mồ hôi';
UPDATE public.dictionary_words SET example_hanzi = '他不小心割到手，流了不少血。', example_pinyin = 'tā bù xiǎoxīn gē dào shǒu，liú le bù shǎo xiě。', example_vietnamese = 'Anh ấy vô ý bị đứt tay, chảy khá nhiều máu.' WHERE level = 'B1' AND hanzi = '流血' AND pinyin = 'liúxiě' AND vietnamese = 'Đổ máu';
UPDATE public.dictionary_words SET example_hanzi = '他打算明年去美國留學。', example_pinyin = 'tā dǎsuàn míngnián qù měiguó liúxué。', example_vietnamese = 'Anh ấy dự định sang năm sẽ đi du học ở Mỹ.' WHERE level = 'B1' AND hanzi = '留學' AND pinyin = 'liúxué' AND vietnamese = 'Du học';
UPDATE public.dictionary_words SET example_hanzi = '這所大學有很多來自越南的留學生。', example_pinyin = 'zhè suǒ dàxué yǒu hěn duō láizì yuènán de liúxuéshēng。', example_vietnamese = 'Trường đại học này có rất nhiều du học sinh đến từ Việt Nam.' WHERE level = 'B1' AND hanzi = '留學生' AND pinyin = 'liúxuéshēng' AND vietnamese = 'Du học sinh';
UPDATE public.dictionary_words SET example_hanzi = '在中國文化裡，龍是力量和吉祥的象徵。', example_pinyin = 'zài zhōngguó wénhuà lǐ，lóng shì lìliàng hé jíxiáng de xiàngzhēng。', example_vietnamese = 'Trong văn hóa Trung Hoa, rồng là biểu tượng của sức mạnh và may mắn.' WHERE level = 'B1' AND hanzi = '龍' AND pinyin = 'lóng' AND vietnamese = 'Con rồng';
UPDATE public.dictionary_words SET example_hanzi = '他把老師上課的內容都錄了下來。', example_pinyin = 'tā bǎ lǎoshī shàngkè de nèiróng dōu lù le xiàlái。', example_vietnamese = 'Anh ấy đã ghi lại toàn bộ nội dung bài giảng của thầy.' WHERE level = 'B1' AND hanzi = '錄' AND pinyin = 'lù' AND vietnamese = 'Ghi chép, thu (băng)';
UPDATE public.dictionary_words SET example_hanzi = '他終於被那間公司錄取了。', example_pinyin = 'tā zhōngyú bèi nà jiān gōngsī lùqǔ le。', example_vietnamese = 'Cuối cùng anh ấy đã được công ty đó tuyển dụng.' WHERE level = 'B1' AND hanzi = '錄取' AND pinyin = 'lùqŭ' AND vietnamese = 'Tuyển chọn, nhận vào';
UPDATE public.dictionary_words SET example_hanzi = '老師要我們把課文錄音下來練習發音。', example_pinyin = 'lǎoshī yào wǒmen bǎ kèwén lùyīn xiàlái liànxí fāyīn。', example_vietnamese = 'Thầy giáo yêu cầu chúng tôi ghi âm bài khóa lại để luyện phát âm.' WHERE level = 'B1' AND hanzi = '錄音' AND pinyin = 'lùyīn' AND vietnamese = 'Thu âm, ghi âm';
UPDATE public.dictionary_words SET example_hanzi = '我們這個週末打算去山上露營。', example_pinyin = 'wǒmen zhège zhōumò dǎsuàn qù shānshàng lùyíng。', example_vietnamese = 'Cuối tuần này chúng tôi định lên núi cắm trại.' WHERE level = 'B1' AND hanzi = '露營' AND pinyin = 'lùyíng' AND vietnamese = 'Đóng quân dã ngoại';
UPDATE public.dictionary_words SET example_hanzi = '他的房間總是亂七八糟的。', example_pinyin = 'tā de fángjiān zǒngshì luànqībāzāo de。', example_vietnamese = 'Phòng của anh ấy lúc nào cũng bừa bộn lộn xộn.' WHERE level = 'B1' AND hanzi = '亂' AND pinyin = 'luàn' AND vietnamese = 'Loạn, rối, lộn xộn';
UPDATE public.dictionary_words SET example_hanzi = '車子的輪胎沒氣了，我們得換一個。', example_pinyin = 'chēzi de lúntāi méi qì le，wǒmen děi huàn yí ge。', example_vietnamese = 'Lốp xe bị xẹp rồi, chúng ta phải thay một cái mới.' WHERE level = 'B1' AND hanzi = '輪胎' AND pinyin = 'lúntāi' AND vietnamese = 'Lốp xe';
UPDATE public.dictionary_words SET example_hanzi = '機場裡擠滿了等待登機的旅客。', example_pinyin = 'jīchǎng lǐ jǐ mǎn le děngdài dēngjī de lǚkè。', example_vietnamese = 'Sân bay đông nghịt hành khách đang chờ lên máy bay.' WHERE level = 'B1' AND hanzi = '旅客' AND pinyin = 'lǚkè' AND vietnamese = 'Lữ khách, hành khách';
UPDATE public.dictionary_words SET example_hanzi = '春天一到，山上的樹都變綠了。', example_pinyin = 'chūntiān yí dào，shānshàng de shù dōu biàn lǜ le。', example_vietnamese = 'Mùa xuân vừa đến, cây cối trên núi đều chuyển sang màu xanh.' WHERE level = 'B1' AND hanzi = '綠' AND pinyin = 'lǜ' AND vietnamese = 'Trở nên xanh';
UPDATE public.dictionary_words SET example_hanzi = '他請了一位律師幫忙處理這件事。', example_pinyin = 'tā qǐng le yí wèi lǜshī bāngmáng chǔlǐ zhè jiàn shì。', example_vietnamese = 'Anh ấy đã thuê một luật sư giúp xử lý việc này.' WHERE level = 'B1' AND hanzi = '律師' AND pinyin = 'lǜshī' AND vietnamese = 'Luật sư';
UPDATE public.dictionary_words SET example_hanzi = '不好意思，麻煩你幫我開一下門。', example_pinyin = 'bùhǎoyìsi，máfan nǐ bāng wǒ kāi yíxià mén。', example_vietnamese = 'Xin lỗi, phiền bạn giúp tôi mở cửa một chút.' WHERE level = 'B1' AND hanzi = '麻煩' AND pinyin = 'máfan' AND vietnamese = 'Phiền phức, phiền toái';
UPDATE public.dictionary_words SET example_hanzi = '馬桶塞住了，得請人來修理。', example_pinyin = 'mǎtǒng sāizhù le，děi qǐng rén lái xiūlǐ。', example_vietnamese = 'Bồn cầu bị tắc rồi, phải gọi người đến sửa.' WHERE level = 'B1' AND hanzi = '馬桶' AND pinyin = 'mătŏng' AND vietnamese = 'Cái bô (có nắp)';
UPDATE public.dictionary_words SET example_hanzi = '漁船每天早上都會回到碼頭卸貨。', example_pinyin = 'yúchuán měitiān zǎoshang dōu huì huí dào mǎtou xièhuò。', example_vietnamese = 'Sáng nào tàu cá cũng quay về bến cảng để dỡ hàng.' WHERE level = 'B1' AND hanzi = '碼頭' AND pinyin = 'mătou' AND vietnamese = 'Bến đò, bến sông';
UPDATE public.dictionary_words SET example_hanzi = '一群螞蟻正在搬一塊麵包屑。', example_pinyin = 'yì qún mǎyǐ zhèngzài bān yí kuài miànbāo xiè。', example_vietnamese = 'Một đàn kiến đang tha một mẩu bánh mì.' WHERE level = 'B1' AND hanzi = '螞蟻' AND pinyin = 'măyĭ' AND vietnamese = 'Con kiến';
UPDATE public.dictionary_words SET example_hanzi = '弟弟因為打破花瓶被媽媽罵了一頓。', example_pinyin = 'dìdi yīnwèi dǎpò huāpíng bèi māma mà le yí dùn。', example_vietnamese = 'Em trai bị mẹ mắng một trận vì làm vỡ bình hoa.' WHERE level = 'B1' AND hanzi = '罵' AND pinyin = 'mà' AND vietnamese = 'Chửi, mắng';
UPDATE public.dictionary_words SET example_hanzi = '你就試試看嘛，反正也沒有損失。', example_pinyin = 'nǐ jiù shìshìkàn ma，fǎnzhèng yě méiyǒu sǔnshī。', example_vietnamese = 'Bạn cứ thử xem mà, dù sao cũng chẳng mất gì.' WHERE level = 'B1' AND hanzi = '嘛' AND pinyin = 'ma' AND vietnamese = 'Đi, mà';
UPDATE public.dictionary_words SET example_hanzi = '桌上擺滿了各式各樣的菜。', example_pinyin = 'zhuō shàng bǎi mǎn le gèshìgèyàng de cài。', example_vietnamese = 'Trên bàn bày đầy đủ loại món ăn.' WHERE level = 'B1' AND hanzi = '滿' AND pinyin = 'măn' AND vietnamese = 'Đầy, chật';
UPDATE public.dictionary_words SET example_hanzi = '杯子裡的水已經滿了，別再倒了。', example_pinyin = 'bēizi lǐ de shuǐ yǐjīng mǎn le，bié zài dào le。', example_vietnamese = 'Nước trong ly đã đầy rồi, đừng rót thêm nữa.' WHERE level = 'B1' AND hanzi = '滿' AND pinyin = 'măn' AND vietnamese = 'Thỏa mãn';
UPDATE public.dictionary_words SET example_hanzi = '小小的成就就能讓他感到滿足。', example_pinyin = 'xiǎoxiǎo de chéngjiù jiù néng ràng tā gǎndào mǎnzú。', example_vietnamese = 'Chỉ một thành tựu nhỏ cũng có thể khiến anh ấy cảm thấy hài lòng.' WHERE level = 'B1' AND hanzi = '滿足' AND pinyin = 'mănzú' AND vietnamese = 'Làm thỏa mãn, hài lòng';
UPDATE public.dictionary_words SET example_hanzi = '慢慢來，不用著急。', example_pinyin = 'mànmàn lái，búyòng zháojí。', example_vietnamese = 'Từ từ thôi, không cần vội.' WHERE level = 'B1' AND hanzi = '慢慢' AND pinyin = 'mànmàn' AND vietnamese = 'Chậm rãi';
UPDATE public.dictionary_words SET example_hanzi = '爸爸每天早上都會去公園慢跑。', example_pinyin = 'bàba měitiān zǎoshang dōu huì qù gōngyuán mànpǎo。', example_vietnamese = 'Sáng nào bố cũng ra công viên chạy bộ.' WHERE level = 'B1' AND hanzi = '慢跑' AND pinyin = 'mànpăo' AND vietnamese = 'Chạy bộ';
UPDATE public.dictionary_words SET example_hanzi = '服務生把菜端上桌後說：「慢用。」', example_pinyin = 'fúwùshēng bǎ cài duān shàng zhuō hòu shuō：「mànyòng。」', example_vietnamese = 'Nhân viên phục vụ bưng món ăn lên bàn rồi nói: "Mời dùng bữa."' WHERE level = 'B1' AND hanzi = '慢用' AND pinyin = 'mànyòng' AND vietnamese = 'Ăn từ từ, thưởng thức món ăn';
UPDATE public.dictionary_words SET example_hanzi = '這隻貓的毛又軟又厚。', example_pinyin = 'zhè zhī māo de máo yòu ruǎn yòu hòu。', example_vietnamese = 'Lông của con mèo này vừa mềm vừa dày.' WHERE level = 'B1' AND hanzi = '毛' AND pinyin = 'máo' AND vietnamese = 'Lông';
UPDATE public.dictionary_words SET example_hanzi = '這台電腦最近老是出毛病。', example_pinyin = 'zhè tái diànnǎo zuìjìn lǎoshì chū máobìng。', example_vietnamese = 'Cái máy tính này gần đây cứ hay trục trặc.' WHERE level = 'B1' AND hanzi = '毛病' AND pinyin = 'máobìng' AND vietnamese = 'tật xấu';
UPDATE public.dictionary_words SET example_hanzi = '這兩個國家的貿易關係越來越密切。', example_pinyin = 'zhè liǎng ge guójiā de màoyì guānxi yuèláiyuè mìqiè。', example_vietnamese = 'Quan hệ thương mại giữa hai nước này ngày càng khăng khít.' WHERE level = 'B1' AND hanzi = '貿易' AND pinyin = 'màoyì' AND vietnamese = 'Thương mại, buôn bán';
UPDATE public.dictionary_words SET example_hanzi = '你吃飯了沒？', example_pinyin = 'nǐ chīfàn le méi？', example_vietnamese = 'Bạn ăn cơm chưa?' WHERE level = 'B1' AND hanzi = '沒' AND pinyin = 'méi' AND vietnamese = 'Chưa';
UPDATE public.dictionary_words SET example_hanzi = '海水漲得很快，小船漸漸沒入水中。', example_pinyin = 'hǎi shuǐ zhǎng de hěn kuài， xiǎo chuán jiàn jiàn méi rù shuǐ zhōng。', example_vietnamese = 'Nước biển dâng rất nhanh, con thuyền nhỏ dần dần chìm xuống nước.' WHERE level = 'B1' AND hanzi = '沒' AND pinyin = 'méi' AND vietnamese = 'Chìm, lặn';
UPDATE public.dictionary_words SET example_hanzi = '別擔心，這只是一點小傷，沒什麼。', example_pinyin = 'bié dān xīn， zhè zhǐ shì yì diǎn xiǎo shāng， méi shén me。', example_vietnamese = 'Đừng lo, đây chỉ là vết thương nhỏ thôi, không sao đâu.' WHERE level = 'B1' AND hanzi = '沒什麼' AND pinyin = 'méishénme' AND vietnamese = 'Không sao, không việc gì';
UPDATE public.dictionary_words SET example_hanzi = '我沒想到他會在這麼短的時間內學會中文。', example_pinyin = 'wǒ méi xiǎng dào tā huì zài zhè me duǎn de shí jiān nèi xué huì zhōng wén。', example_vietnamese = 'Tôi không ngờ rằng anh ấy có thể học được tiếng Trung trong thời gian ngắn như vậy.' WHERE level = 'B1' AND hanzi = '沒想到' AND pinyin = 'méixiăngdào' AND vietnamese = 'Không ngờ rằng';
UPDATE public.dictionary_words SET example_hanzi = '他送給女朋友一束紅色的玫瑰。', example_pinyin = 'tā sòng gěi nǚ péng yǒu yí shù hóng sè de méi gui。', example_vietnamese = 'Anh ấy tặng bạn gái một bó hoa hồng đỏ.' WHERE level = 'B1' AND hanzi = '玫瑰' AND pinyin = 'méigui' AND vietnamese = 'Hoa hồng';
UPDATE public.dictionary_words SET example_hanzi = '我每天早上都會喝一杯咖啡。', example_pinyin = 'wǒ měi tiān zǎo shang dōu huì hē yì bēi kā fēi。', example_vietnamese = 'Mỗi sáng tôi đều uống một tách cà phê.' WHERE level = 'B1' AND hanzi = '每' AND pinyin = 'měi' AND vietnamese = 'Mỗi';
UPDATE public.dictionary_words SET example_hanzi = '大家都希望擁有一個美好的未來。', example_pinyin = 'dà jiā dōu xī wàng yōng yǒu yí gè měi hǎo de wèi lái。', example_vietnamese = 'Mọi người đều mong muốn có một tương lai tốt đẹp.' WHERE level = 'B1' AND hanzi = '美好' AND pinyin = 'měihăo' AND vietnamese = 'Tốt đẹp';
UPDATE public.dictionary_words SET example_hanzi = '這學期我選了三門課。', example_pinyin = 'zhè xué qī wǒ xuǎn le sān mén kè。', example_vietnamese = 'Học kỳ này tôi đã đăng ký ba môn học.' WHERE level = 'B1' AND hanzi = '門' AND pinyin = 'mén' AND vietnamese = 'Cửa, cánh cửa';
UPDATE public.dictionary_words SET example_hanzi = '昨晚我做了一個很奇怪的夢。', example_pinyin = 'zuó wǎn wǒ zuò le yí gè hěn qí guài de mèng。', example_vietnamese = 'Tối qua tôi đã có một giấc mơ rất kỳ lạ.' WHERE level = 'B1' AND hanzi = '夢' AND pinyin = 'mèng' AND vietnamese = 'Mơ, giấc mơ';
UPDATE public.dictionary_words SET example_hanzi = '我們在山裡迷路了，找不到回去的路。', example_pinyin = 'wǒ men zài shān lǐ mí lù le， zhǎo bú dào huí qù de lù。', example_vietnamese = 'Chúng tôi bị lạc đường trong núi, không tìm được đường về.' WHERE level = 'B1' AND hanzi = '迷路' AND pinyin = 'mílù' AND vietnamese = 'Lạc đường';
UPDATE public.dictionary_words SET example_hanzi = '這座城市的夜景真是迷人。', example_pinyin = 'zhè zuò chéng shì de yè jǐng zhēn shì mí rén。', example_vietnamese = 'Cảnh đêm của thành phố này thật mê hoặc lòng người.' WHERE level = 'B1' AND hanzi = '迷人' AND pinyin = 'mírén' AND vietnamese = 'Mê hoặc lòng người';
UPDATE public.dictionary_words SET example_hanzi = '我今天中午吃了一碗米飯和一些青菜。', example_pinyin = 'wǒ jīn tiān zhōng wǔ chī le yì wǎn mǐ fàn hàn yì xiē qīng cài。', example_vietnamese = 'Trưa nay tôi đã ăn một bát cơm và một ít rau xanh.' WHERE level = 'B1' AND hanzi = '米飯' AND pinyin = 'mǐfàn' AND vietnamese = 'Cơm';
UPDATE public.dictionary_words SET example_hanzi = '這家店的炒米粉又香又好吃。', example_pinyin = 'zhè jiā diàn de chǎo mǐ fěn yòu xiāng yòu hǎo chī。', example_vietnamese = 'Món bún xào của quán này vừa thơm vừa ngon.' WHERE level = 'B1' AND hanzi = '米粉' AND pinyin = 'mĭfěn' AND vietnamese = 'Bột gạo, bún';
UPDATE public.dictionary_words SET example_hanzi = '這是我們兩個人的秘密，不能告訴別人。', example_pinyin = 'zhè shì wǒ men liǎng gè rén de mì mì， bù néng gào su bié rén。', example_vietnamese = 'Đây là bí mật của hai chúng ta, không được nói cho người khác biết.' WHERE level = 'B1' AND hanzi = '秘/祕密' AND pinyin = 'mìmì' AND vietnamese = 'Bí mật';
UPDATE public.dictionary_words SET example_hanzi = '這兩個國家的關係一直很密切。', example_pinyin = 'zhè liǎng gè guó jiā de guān xì yì zhí hěn mì qiè。', example_vietnamese = 'Quan hệ giữa hai nước này luôn rất mật thiết.' WHERE level = 'B1' AND hanzi = '密切' AND pinyin = 'mìqiè' AND vietnamese = 'Mật thiết';
UPDATE public.dictionary_words SET example_hanzi = '這家咖啡廳提供免費的無線網路。', example_pinyin = 'zhè jiā kā fēi tīng tí gōng miǎn fèi de wú xiàn wǎng lù。', example_vietnamese = 'Quán cà phê này cung cấp wifi miễn phí.' WHERE level = 'B1' AND hanzi = '免費' AND pinyin = 'miănfèi' AND vietnamese = 'Miễn phí';
UPDATE public.dictionary_words SET example_hanzi = '牆上掛著一面很大的鏡子。', example_pinyin = 'qiáng shàng guà zhe yí miàn hěn dà de jìng zi。', example_vietnamese = 'Trên tường treo một tấm gương rất lớn.' WHERE level = 'B1' AND hanzi = '面' AND pinyin = 'miàn' AND vietnamese = 'Mặt';
UPDATE public.dictionary_words SET example_hanzi = '他家就在學校的東面。', example_pinyin = 'tā jiā jiù zài xué xiào de dōng miàn。', example_vietnamese = 'Nhà anh ấy ở phía đông trường học.' WHERE level = 'B1' AND hanzi = '面' AND pinyin = 'miàn' AND vietnamese = 'Trước mặt, đối diện';
UPDATE public.dictionary_words SET example_hanzi = '這間房子的面積大約是一百平方公尺。', example_pinyin = 'zhè jiān fáng zi de miàn jī dà yuē shì yì bǎi píng fāng gōng chǐ。', example_vietnamese = 'Diện tích căn nhà này khoảng một trăm mét vuông.' WHERE level = 'B1' AND hanzi = '面積' AND pinyin = 'miànjī' AND vietnamese = 'Diện tích';
UPDATE public.dictionary_words SET example_hanzi = '在老師面前，他不敢說謊。', example_pinyin = 'zài lǎo shī miàn qián， tā bù gǎn shuō huǎng。', example_vietnamese = 'Trước mặt thầy giáo, cậu ấy không dám nói dối.' WHERE level = 'B1' AND hanzi = '面前' AND pinyin = 'miànqián' AND vietnamese = 'Phía trước, trước mặt';
UPDATE public.dictionary_words SET example_hanzi = '媽媽煮了一碗熱騰騰的麵條給我當早餐。', example_pinyin = 'mā ma zhǔ le yì wǎn rè téng téng de miàn tiáo gěi wǒ dāng zǎo cān。', example_vietnamese = 'Mẹ nấu cho tôi một bát mì nóng hổi để ăn sáng.' WHERE level = 'B1' AND hanzi = '麵條' AND pinyin = 'miàntiáo' AND vietnamese = 'Mì sợi';
UPDATE public.dictionary_words SET example_hanzi = '這篇小說生動地描寫了鄉下的生活。', example_pinyin = 'zhè piān xiǎo shuō shēng dòng de miáo xiě le xiāng xià de shēng huó。', example_vietnamese = 'Truyện ngắn này miêu tả sinh động cuộc sống ở nông thôn.' WHERE level = 'B1' AND hanzi = '描寫' AND pinyin = 'miáoxiě' AND vietnamese = 'Miêu tả';
UPDATE public.dictionary_words SET example_hanzi = '這場比賽只剩下十秒就結束了。', example_pinyin = 'zhè chǎng bǐ sài zhǐ shèng xià shí miǎo jiù jié shù le。', example_vietnamese = 'Trận đấu này chỉ còn mười giây nữa là kết thúc.' WHERE level = 'B1' AND hanzi = '秒' AND pinyin = 'miǎo' AND vietnamese = 'Giây';
UPDATE public.dictionary_words SET example_hanzi = '過年的時候，很多人會去廟裡拜拜。', example_pinyin = 'guò nián de shí hou， hěn duō rén huì qù miào lǐ bài bai。', example_vietnamese = 'Vào dịp Tết, nhiều người thường đến miếu để cúng bái.' WHERE level = 'B1' AND hanzi = '廟' AND pinyin = 'miào' AND vietnamese = 'Miếu, đền thờ';
UPDATE public.dictionary_words SET example_hanzi = '今年是民國一百一十三年。', example_pinyin = 'jīn nián shì mín guó yì bǎi yì shí sān nián。', example_vietnamese = 'Năm nay là năm Dân Quốc thứ một trăm mười ba.' WHERE level = 'B1' AND hanzi = '民國' AND pinyin = 'mínguó' AND vietnamese = 'Dân quốc';
UPDATE public.dictionary_words SET example_hanzi = '台灣是一個由多個民族組成的社會。', example_pinyin = 'tái wān shì yí gè yóu duō gè mín zú zǔ chéng de shè huì。', example_vietnamese = 'Đài Loan là một xã hội được hình thành từ nhiều dân tộc.' WHERE level = 'B1' AND hanzi = '民族' AND pinyin = 'mínzú' AND vietnamese = 'Dân tộc';
UPDATE public.dictionary_words SET example_hanzi = '這次比賽總共有五十名選手參加。', example_pinyin = 'zhè cì bǐ sài zǒng gòng yǒu wǔ shí míng xuǎn shǒu cān jiā。', example_vietnamese = 'Cuộc thi lần này có tổng cộng năm mươi thí sinh tham gia.' WHERE level = 'B1' AND hanzi = '名' AND pinyin = 'míng' AND vietnamese = 'Tên gọi';
UPDATE public.dictionary_words SET example_hanzi = '老師要我們找出句子裡的名詞。', example_pinyin = 'lǎo shī yào wǒ men zhǎo chū jù zi lǐ de míng cí。', example_vietnamese = 'Thầy giáo yêu cầu chúng tôi tìm ra các danh từ trong câu.' WHERE level = 'B1' AND hanzi = '名詞' AND pinyin = 'míngcí' AND vietnamese = 'Danh từ';
UPDATE public.dictionary_words SET example_hanzi = '你解釋了半天，我終於明白了。', example_pinyin = 'nǐ jiě shì le bàn tiān， wǒ zhōng yú míng bái le。', example_vietnamese = 'Bạn giải thích cả một hồi lâu, cuối cùng tôi cũng hiểu rồi.' WHERE level = 'B1' AND hanzi = '明白' AND pinyin = 'míngbái' AND vietnamese = 'Hiểu';
UPDATE public.dictionary_words SET example_hanzi = '這幾年他的中文進步得非常明顯。', example_pinyin = 'zhè jǐ nián tā de zhōng wén jìn bù de fēi cháng míng xiǎn。', example_vietnamese = 'Mấy năm nay tiếng Trung của anh ấy tiến bộ rất rõ rệt.' WHERE level = 'B1' AND hanzi = '明顯' AND pinyin = 'míngxiăn' AND vietnamese = 'Rõ ràng, nổi bật';
UPDATE public.dictionary_words SET example_hanzi = '那位電影明星走在路上，馬上被大家認出來了。', example_pinyin = 'nà wèi diàn yǐng míng xīng zǒu zài lù shàng， mǎ shàng bèi dà jiā rèn chū lái le。', example_vietnamese = 'Ngôi sao điện ảnh đó vừa đi trên đường liền bị mọi người nhận ra ngay.' WHERE level = 'B1' AND hanzi = '明星' AND pinyin = 'míngxīng' AND vietnamese = 'Ngôi sao';
UPDATE public.dictionary_words SET example_hanzi = '醫生盡全力救回了他的命。', example_pinyin = 'yī shēng jìn quán lì jiù huí le tā de mìng。', example_vietnamese = 'Bác sĩ đã dốc hết sức để cứu sống anh ấy.' WHERE level = 'B1' AND hanzi = '命' AND pinyin = 'mìng' AND vietnamese = 'Sinh mệnh, mạng';
UPDATE public.dictionary_words SET example_hanzi = '小孩子好奇地伸手摸了摸那隻小狗。', example_pinyin = 'xiǎo hái zi hào qí de shēn shǒu mō le mō nà zhī xiǎo gǒu。', example_vietnamese = 'Đứa trẻ tò mò đưa tay sờ sờ con chó nhỏ đó.' WHERE level = 'B1' AND hanzi = '摸' AND pinyin = 'mō' AND vietnamese = 'sờ , xoa , chạm';
UPDATE public.dictionary_words SET example_hanzi = '他每天騎摩托車去上班。', example_pinyin = 'tā měi tiān qí mó tuō chē qù shàng bān。', example_vietnamese = 'Hằng ngày anh ấy đi làm bằng xe gắn máy.' WHERE level = 'B1' AND hanzi = '摩托車/機車' AND pinyin = 'mótuōchē/jīchē' AND vietnamese = 'Xe gắn máy, xe mô-tô';
UPDATE public.dictionary_words SET example_hanzi = '剛搬到這個城市時，我對這裡感到很陌生。', example_pinyin = 'gāng bān dào zhè ge chéng shì shí， wǒ duì zhè lǐ gǎn dào hěn mò shēng。', example_vietnamese = 'Khi mới chuyển đến thành phố này, tôi cảm thấy rất xa lạ với nơi đây.' WHERE level = 'B1' AND hanzi = '陌生' AND pinyin = 'mòshēng' AND vietnamese = 'Xa lạ, không quen';
UPDATE public.dictionary_words SET example_hanzi = '他在某個地方看過這部電影的海報。', example_pinyin = 'tā zài mǒu gè dì fāng kàn guò zhè bù diàn yǐng de hǎi bào。', example_vietnamese = 'Anh ấy đã xem áp phích của bộ phim này ở một nơi nào đó.' WHERE level = 'B1' AND hanzi = '某' AND pinyin = 'mŏu' AND vietnamese = 'Nào đó';
UPDATE public.dictionary_words SET example_hanzi = '五行之中，木代表生長與希望。', example_pinyin = 'wǔ xíng zhī zhōng， mù dài biǎo shēng zhǎng yǔ xī wàng。', example_vietnamese = 'Trong ngũ hành, Mộc tượng trưng cho sự sinh trưởng và hy vọng.' WHERE level = 'B1' AND hanzi = '木' AND pinyin = 'mù' AND vietnamese = 'Mộc, cây gỗ';
UPDATE public.dictionary_words SET example_hanzi = '爺爺用一塊木頭刻了一隻小鳥。', example_pinyin = 'yé ye yòng yí kuài mù tou kè le yì zhī xiǎo niǎo。', example_vietnamese = 'Ông nội dùng một khúc gỗ khắc thành một con chim nhỏ.' WHERE level = 'B1' AND hanzi = '木頭' AND pinyin = 'mùtou' AND vietnamese = 'Gỗ, mảnh gỗ';
UPDATE public.dictionary_words SET example_hanzi = '他學中文的目的是想去中國工作。', example_pinyin = 'tā xué zhōng wén de mù dì shì xiǎng qù zhōng guó gōng zuò。', example_vietnamese = 'Mục đích anh ấy học tiếng Trung là muốn sang Trung Quốc làm việc.' WHERE level = 'B1' AND hanzi = '目的' AND pinyin = 'mùdì' AND vietnamese = 'Mục đích';
UPDATE public.dictionary_words SET example_hanzi = '目前公司還沒有決定要不要擴大規模。', example_pinyin = 'mù qián gōng sī hái méi yǒu jué dìng yào bú yào kuò dà guī mó。', example_vietnamese = 'Hiện nay công ty vẫn chưa quyết định có mở rộng quy mô hay không.' WHERE level = 'B1' AND hanzi = '目前' AND pinyin = 'mùqián' AND vietnamese = 'Hiện nay, trước mắt';
UPDATE public.dictionary_words SET example_hanzi = '做紅燒肉是媽媽最拿手的菜。', example_pinyin = 'zuò hóng shāo ròu shì mā ma zuì ná shǒu de cài。', example_vietnamese = 'Làm thịt kho là món sở trường nhất của mẹ.' WHERE level = 'B1' AND hanzi = '拿手' AND pinyin = 'náshŏu' AND vietnamese = 'Sở trường';
UPDATE public.dictionary_words SET example_hanzi = '你昨天在超市買了哪些東西？', example_pinyin = 'nǐ zuó tiān zài chāo shì mǎi le nǎ xiē dōng xi？', example_vietnamese = 'Hôm qua bạn đã mua những gì ở siêu thị vậy?' WHERE level = 'B1' AND hanzi = '哪些' AND pinyin = 'nǎxiē' AND vietnamese = 'Cái nào, người nào';
UPDATE public.dictionary_words SET example_hanzi = '你要是不喜歡吃辣，那我們就換一家餐廳吧。', example_pinyin = 'nǐ yào shi bù xǐ huan chī là， nà wǒ men jiù huàn yì jiā cān tīng ba。', example_vietnamese = 'Nếu bạn không thích ăn cay, vậy thì chúng ta đổi sang quán khác nhé.' WHERE level = 'B1' AND hanzi = '那' AND pinyin = 'nà' AND vietnamese = 'Kia, đó';
UPDATE public.dictionary_words SET example_hanzi = '如果明天下雨，那麼運動會就要延期了。', example_pinyin = 'rú guǒ míng tiān xià yǔ， nà me yùn dòng huì jiù yào yán qī le。', example_vietnamese = 'Nếu ngày mai trời mưa, thì hội thao sẽ phải hoãn lại.' WHERE level = 'B1' AND hanzi = '那麼' AND pinyin = 'nàme' AND vietnamese = 'Như vậy, như thế';
UPDATE public.dictionary_words SET example_hanzi = '你不要那樣看著我，我會不好意思。', example_pinyin = 'nǐ bú yào nà yàng kàn zhe wǒ， wǒ huì bù hǎo yì si。', example_vietnamese = 'Bạn đừng nhìn tôi như thế, tôi sẽ ngại đấy.' WHERE level = 'B1' AND hanzi = '那樣' AND pinyin = 'nàyàng' AND vietnamese = 'Như thế';
UPDATE public.dictionary_words SET example_hanzi = '事情不是你想的那樣。', example_pinyin = 'shì qing bú shì nǐ xiǎng de nà yàng。', example_vietnamese = 'Sự việc không phải như những gì bạn nghĩ.' WHERE level = 'B1' AND hanzi = '那樣' AND pinyin = 'nàyàng' AND vietnamese = 'như vậy';
UPDATE public.dictionary_words SET example_hanzi = '你可要小心哪！', example_pinyin = 'nǐ kě yào xiǎo xīn na！', example_vietnamese = 'Bạn phải cẩn thận đấy nhé!' WHERE level = 'B1' AND hanzi = '哪' AND pinyin = 'na' AND vietnamese = 'à, nhé (trợ từ ngữ khí)';
UPDATE public.dictionary_words SET example_hanzi = '小寶寶餓了，就會哭著要喝奶。', example_pinyin = 'xiǎo bǎo bao è le， jiù huì kū zhe yào hē nǎi。', example_vietnamese = 'Em bé đói bụng thì sẽ khóc đòi uống sữa.' WHERE level = 'B1' AND hanzi = '奶' AND pinyin = 'nǎi' AND vietnamese = 'Sữa';
UPDATE public.dictionary_words SET example_hanzi = '下課後，同學們常常一起去買珍珠奶茶。', example_pinyin = 'xià kè hòu， tóng xué men cháng cháng yì qǐ qù mǎi zhēn zhū nǎi chá。', example_vietnamese = 'Sau giờ học, các bạn học thường cùng nhau đi mua trà sữa trân châu.' WHERE level = 'B1' AND hanzi = '奶茶' AND pinyin = 'nǎichá' AND vietnamese = 'Trà sữa';
UPDATE public.dictionary_words SET example_hanzi = '教小孩子讀書需要很大的耐心。', example_pinyin = 'jiāo xiǎo hái zi dú shū xū yào hěn dà de nài xīn。', example_vietnamese = 'Dạy trẻ nhỏ học chữ cần rất nhiều sự kiên nhẫn.' WHERE level = 'B1' AND hanzi = '耐心' AND pinyin = 'nàixīn' AND vietnamese = 'Sự kiên nhẫn';
UPDATE public.dictionary_words SET example_hanzi = '冬天的時候，很多候鳥會飛到南方過冬。', example_pinyin = 'dōng tiān de shí hou， hěn duō hòu niǎo huì fēi dào nán fāng guò dōng。', example_vietnamese = 'Vào mùa đông, nhiều loài chim di cư sẽ bay về phương Nam để trú đông.' WHERE level = 'B1' AND hanzi = '南方' AND pinyin = 'nánfāng' AND vietnamese = 'Phương Nam';
UPDATE public.dictionary_words SET example_hanzi = '難怪你今天這麼開心，原來是考試考得很好。', example_pinyin = 'nán guài nǐ jīn tiān zhè me kāi xīn， yuán lái shì kǎo shì kǎo de hěn hǎo。', example_vietnamese = 'Thảo nào hôm nay bạn vui như vậy, hoá ra là thi được điểm cao.' WHERE level = 'B1' AND hanzi = '難怪' AND pinyin = 'nánguài' AND vietnamese = 'Thảo nào, hèn chi';
UPDATE public.dictionary_words SET example_hanzi = '這件衣服的顏色配得很難看。', example_pinyin = 'zhè jiàn yī fu de yán sè pèi de hěn nán kàn。', example_vietnamese = 'Màu sắc của bộ quần áo này phối rất khó coi.' WHERE level = 'B1' AND hanzi = '難看' AND pinyin = 'nánkàn' AND vietnamese = 'Xấu xí, khó coi';
UPDATE public.dictionary_words SET example_hanzi = '醫生說他的腦部受到了一點小傷。', example_pinyin = 'yī shēng shuō tā de nǎo bù shòu dào le yì diǎn xiǎo shāng。', example_vietnamese = 'Bác sĩ nói não của anh ấy bị tổn thương nhẹ.' WHERE level = 'B1' AND hanzi = '腦' AND pinyin = 'năo' AND vietnamese = 'Não';
UPDATE public.dictionary_words SET example_hanzi = '這個問題有點複雜，讓我動動腦子想一想。', example_pinyin = 'zhè ge wèn tí yǒu diǎn fù zá， ràng wǒ dòng dòng nǎo zi xiǎng yi xiǎng。', example_vietnamese = 'Vấn đề này hơi phức tạp, để tôi động não suy nghĩ một chút.' WHERE level = 'B1' AND hanzi = '腦子' AND pinyin = 'năozi' AND vietnamese = 'Não bộ';
UPDATE public.dictionary_words SET example_hanzi = '我每天早上七點都會被鬧鐘吵醒。', example_pinyin = 'wǒ měi tiān zǎo shang qī diǎn dōu huì bèi nào zhōng chǎo xǐng。', example_vietnamese = 'Mỗi sáng bảy giờ tôi đều bị đồng hồ báo thức đánh thức.' WHERE level = 'B1' AND hanzi = '鬧鐘' AND pinyin = 'nàozhōng' AND vietnamese = 'Đồng hồ báo thức';
UPDATE public.dictionary_words SET example_hanzi = '這件事必須在三天內完成。', example_pinyin = 'zhè jiàn shì bì xū zài sān tiān nèi wán chéng。', example_vietnamese = 'Việc này phải hoàn thành trong vòng ba ngày.' WHERE level = 'B1' AND hanzi = '內' AND pinyin = 'nèi' AND vietnamese = 'Trong, phía trong';
UPDATE public.dictionary_words SET example_hanzi = '這本書的內容非常豐富，值得一讀。', example_pinyin = 'zhè běn shū de nèi róng fēi cháng fēng fù， zhí de yì dú。', example_vietnamese = 'Nội dung cuốn sách này rất phong phú, đáng để đọc.' WHERE level = 'B1' AND hanzi = '內容' AND pinyin = 'nèiróng' AND vietnamese = 'Nội dung';
UPDATE public.dictionary_words SET example_hanzi = '你明天能不能來參加我的生日派對？', example_pinyin = 'nǐ míng tiān néng bù néng lái cān jiā wǒ de shēng rì pài duì？', example_vietnamese = 'Ngày mai bạn có thể đến dự tiệc sinh nhật của tôi không?' WHERE level = 'B1' AND hanzi = '能' AND pinyin = 'néng' AND vietnamese = 'Năng lực, có thể';
UPDATE public.dictionary_words SET example_hanzi = '只要努力練習，你一定能夠說一口流利的中文。', example_pinyin = 'zhǐ yào nǔ lì liàn xí， nǐ yí dìng néng gòu shuō yì kǒu liú lì de zhōng wén。', example_vietnamese = 'Chỉ cần chăm chỉ luyện tập, bạn chắc chắn sẽ có thể nói tiếng Trung lưu loát.' WHERE level = 'B1' AND hanzi = '能夠' AND pinyin = 'nénggòu' AND vietnamese = 'Có khả năng';
UPDATE public.dictionary_words SET example_hanzi = '這份工作需要很強的溝通能力。', example_pinyin = 'zhè fèn gōng zuò xū yào hěn qiáng de gōu tōng néng lì。', example_vietnamese = 'Công việc này đòi hỏi khả năng giao tiếp rất tốt.' WHERE level = 'B1' AND hanzi = '能力' AND pinyin = 'nénglì' AND vietnamese = 'Năng lực, khả năng';
UPDATE public.dictionary_words SET example_hanzi = '我在台灣已經住了三年了。', example_pinyin = 'wǒ zài tái wān yǐ jīng zhù le sān nián le。', example_vietnamese = 'Tôi đã sống ở Đài Loan được ba năm rồi.' WHERE level = 'B1' AND hanzi = '年' AND pinyin = 'nián' AND vietnamese = 'Năm';
UPDATE public.dictionary_words SET example_hanzi = '這首歌是八十年代非常流行的老歌。', example_pinyin = 'zhè shǒu gē shì bā shí nián dài fēi cháng liú xíng de lǎo gē。', example_vietnamese = 'Bài hát này là ca khúc rất thịnh hành vào thập niên tám mươi.' WHERE level = 'B1' AND hanzi = '年代' AND pinyin = 'niándài' AND vietnamese = 'Thời đại, thời kỳ';
UPDATE public.dictionary_words SET example_hanzi = '報名這項比賽沒有年齡的限制。', example_pinyin = 'bào míng zhè xiàng bǐ sài méi yǒu nián líng de xiàn zhì。', example_vietnamese = 'Đăng ký tham gia cuộc thi này không giới hạn độ tuổi.' WHERE level = 'B1' AND hanzi = '年齡' AND pinyin = 'niánlíng' AND vietnamese = 'Tuổi tác';
UPDATE public.dictionary_words SET example_hanzi = '這個地區年年都會舉辦熱鬧的燈會。', example_pinyin = 'zhè ge dì qū nián nián dōu huì jǔ bàn rè nao de dēng huì。', example_vietnamese = 'Khu vực này năm nào cũng tổ chức lễ hội đèn lồng náo nhiệt.' WHERE level = 'B1' AND hanzi = '年年' AND pinyin = 'niánnián' AND vietnamese = 'Hằng năm, mỗi năm';
UPDATE public.dictionary_words SET example_hanzi = '弟弟正在房間裡專心念書，準備明天的考試。', example_pinyin = 'dì di zhèng zài fáng jiān lǐ zhuān xīn niàn shū， zhǔn bèi míng tiān de kǎo shì。', example_vietnamese = 'Em trai đang chăm chú học bài trong phòng để chuẩn bị cho kỳ thi ngày mai.' WHERE level = 'B1' AND hanzi = '念書' AND pinyin = 'niànshū' AND vietnamese = 'Học bài, đọc sách';
UPDATE public.dictionary_words SET example_hanzi = '這個地方以農業為主要的經濟來源。', example_pinyin = 'zhè ge dì fang yǐ nóng yè wéi zhǔ yào de jīng jì lái yuán。', example_vietnamese = 'Nơi này chủ yếu dựa vào nông nghiệp làm nguồn kinh tế chính.' WHERE level = 'B1' AND hanzi = '農業' AND pinyin = 'nóngyè' AND vietnamese = 'Nông nghiệp';
UPDATE public.dictionary_words SET example_hanzi = '各位先生女士，歡迎來到今天的音樂會。', example_pinyin = 'gè wèi xiān sheng nǚ shì， huān yíng lái dào jīn tiān de yīn yuè huì。', example_vietnamese = 'Kính chào quý ông quý bà, chào mừng đến với buổi hòa nhạc hôm nay.' WHERE level = 'B1' AND hanzi = '女士' AND pinyin = 'nǚshì' AND vietnamese = 'Bà, phu nhân, quý cô';
UPDATE public.dictionary_words SET example_hanzi = '喔，原來你也是台北人啊！', example_pinyin = 'ō， yuán lái nǐ yě shì tái běi rén a！', example_vietnamese = 'Ồ, hoá ra bạn cũng là người Đài Bắc à!' WHERE level = 'B1' AND hanzi = '喔' AND pinyin = 'ō' AND vietnamese = 'ờ';
UPDATE public.dictionary_words SET example_hanzi = '哦，我懂了，原來是這麼一回事。', example_pinyin = 'ó， wǒ dǒng le， yuán lái shì zhè me yì huí shì。', example_vietnamese = 'À, tôi hiểu rồi, hoá ra là chuyện như vậy.' WHERE level = 'B1' AND hanzi = '哦' AND pinyin = 'ó' AND vietnamese = 'Ngâm thơ';
UPDATE public.dictionary_words SET example_hanzi = '噢，我知道問題出在哪裡了。', example_pinyin = 'ō， wǒ zhī dào wèn tí chū zài nǎ lǐ le。', example_vietnamese = 'Ồ, tôi biết vấn đề nằm ở đâu rồi.' WHERE level = 'B1' AND hanzi = '噢' AND pinyin = 'yǔ' AND vietnamese = 'ờ';
UPDATE public.dictionary_words SET example_hanzi = '老師拍了拍我的肩膀，鼓勵我繼續努力。', example_pinyin = 'lǎo shī pāi le pāi wǒ de jiān bǎng， gǔ lì wǒ jì xù nǔ lì。', example_vietnamese = 'Thầy giáo vỗ vỗ vai tôi, động viên tôi tiếp tục cố gắng.' WHERE level = 'B1' AND hanzi = '拍' AND pinyin = 'pāi' AND vietnamese = 'Đập, vỗ, phủi';
UPDATE public.dictionary_words SET example_hanzi = '大家請排好隊，一個一個上車。', example_pinyin = 'dà jiā qǐng pái hǎo duì， yí gè yí gè shàng chē。', example_vietnamese = 'Mọi người vui lòng xếp hàng ngay ngắn, lần lượt lên xe.' WHERE level = 'B1' AND hanzi = '排' AND pinyin = 'pái' AND vietnamese = 'Xếp, sắp xếp';
UPDATE public.dictionary_words SET example_hanzi = '門口掛著一塊寫著「休息中」的牌子。', example_pinyin = 'mén kǒu guà zhe yí kuài xiě zhe「xiū xi zhōng」de pái zi。', example_vietnamese = 'Trước cửa treo một tấm biển ghi "đang nghỉ".' WHERE level = 'B1' AND hanzi = '牌子' AND pinyin = 'páizi' AND vietnamese = 'Thẻ, bảng, biển hiệu';
UPDATE public.dictionary_words SET example_hanzi = '全家人都盼望著他能平安回來。', example_pinyin = 'quán jiā rén dōu pàn wàng zhe tā néng píng ān huí lái。', example_vietnamese = 'Cả nhà đều mong mỏi anh ấy trở về bình an.' WHERE level = 'B1' AND hanzi = '盼望' AND pinyin = 'pànwàng' AND vietnamese = 'Trông mong, mong mỏi';
UPDATE public.dictionary_words SET example_hanzi = '圖書館旁有一個很安靜的小公園。', example_pinyin = 'tú shū guǎn páng yǒu yí gè hěn ān jìng de xiǎo gōng yuán。', example_vietnamese = 'Bên cạnh thư viện có một công viên nhỏ rất yên tĩnh.' WHERE level = 'B1' AND hanzi = '旁' AND pinyin = 'páng' AND vietnamese = 'Bên cạnh';
UPDATE public.dictionary_words SET example_hanzi = '週末我會陪媽媽去菜市場買菜。', example_pinyin = 'zhōu mò wǒ huì péi mā ma qù cài shì chǎng mǎi cài。', example_vietnamese = 'Cuối tuần tôi sẽ đi cùng mẹ ra chợ mua rau.' WHERE level = 'B1' AND hanzi = '陪' AND pinyin = 'péi' AND vietnamese = 'ở cùng với';
UPDATE public.dictionary_words SET example_hanzi = '父母應該從小培養孩子閱讀的習慣。', example_pinyin = 'fù mǔ yīng gāi cóng xiǎo péi yǎng hái zi yuè dú de xí guàn。', example_vietnamese = 'Cha mẹ nên bồi dưỡng thói quen đọc sách cho con từ nhỏ.' WHERE level = 'B1' AND hanzi = '培養' AND pinyin = 'péiyăng' AND vietnamese = 'Nuôi dưỡng, bồi dưỡng';
UPDATE public.dictionary_words SET example_hanzi = '這件白色上衣配黑色褲子很好看。', example_pinyin = 'zhè jiàn bái sè shàng yī pèi hēi sè kù zi hěn hǎo kàn。', example_vietnamese = 'Chiếc áo trắng này phối với quần đen rất đẹp.' WHERE level = 'B1' AND hanzi = '配' AND pinyin = 'pèi' AND vietnamese = 'Kết đôi';
UPDATE public.dictionary_words SET example_hanzi = '這次活動需要大家互相配合才能順利完成。', example_pinyin = 'zhè cì huó dòng xū yào dà jiā hù xiāng pèi hé cái néng shùn lì wán chéng。', example_vietnamese = 'Hoạt động lần này cần mọi người phối hợp với nhau mới có thể hoàn thành suôn sẻ.' WHERE level = 'B1' AND hanzi = '配合' AND pinyin = 'pèihé' AND vietnamese = 'Kết hợp, phối hợp';
UPDATE public.dictionary_words SET example_hanzi = '小心一點，別碰到桌上的花瓶。', example_pinyin = 'xiǎo xīn yì diǎn， bié pèng dào zhuō shàng de huā píng。', example_vietnamese = 'Cẩn thận một chút, đừng chạm vào bình hoa trên bàn.' WHERE level = 'B1' AND hanzi = '碰' AND pinyin = 'pèng' AND vietnamese = 'Đụng, chạm, vấp phải';
UPDATE public.dictionary_words SET example_hanzi = '我在路上碰到了一個好久不見的老朋友。', example_pinyin = 'wǒ zài lù shàng pèng dào le yí gè hǎo jiǔ bú jiàn de lǎo péng you。', example_vietnamese = 'Trên đường tôi tình cờ gặp một người bạn cũ đã lâu không gặp.' WHERE level = 'B1' AND hanzi = '碰到' AND pinyin = 'pèngdào' AND vietnamese = 'Đi qua, đụng phải';
UPDATE public.dictionary_words SET example_hanzi = '我們出門的時候剛好碰上下大雨。', example_pinyin = 'wǒ men chū mén de shí hou gāng hǎo pèng shàng xià dà yǔ。', example_vietnamese = 'Lúc chúng tôi ra ngoài thì vừa đúng lúc gặp phải trời mưa to.' WHERE level = 'B1' AND hanzi = '碰上' AND pinyin = 'pèngshàng' AND vietnamese = 'Gặp gỡ, đụng trúng';
UPDATE public.dictionary_words SET example_hanzi = '老闆在會議上批評了這次企劃案的內容。', example_pinyin = 'lǎo bǎn zài huì yì shàng pī píng le zhè cì qǐ huà àn de nèi róng。', example_vietnamese = 'Ông chủ đã phê bình nội dung của kế hoạch lần này trong cuộc họp.' WHERE level = 'B1' AND hanzi = '批評' AND pinyin = 'pīpíng' AND vietnamese = 'Phê bình';
UPDATE public.dictionary_words SET example_hanzi = '這種蘋果的皮很薄，可以直接吃。', example_pinyin = 'zhè zhǒng píng guǒ de pí hěn báo， kě yǐ zhí jiē chī。', example_vietnamese = 'Vỏ của loại táo này rất mỏng, có thể ăn trực tiếp.' WHERE level = 'B1' AND hanzi = '皮' AND pinyin = 'pí' AND vietnamese = 'Vỏ, da';
UPDATE public.dictionary_words SET example_hanzi = '他繫了一條黑色的皮帶配這套西裝。', example_pinyin = 'tā jì le yì tiáo hēi sè de pí dài pèi zhè tào xī zhuāng。', example_vietnamese = 'Anh ấy thắt một chiếc dây lưng màu đen để phối với bộ vest này.' WHERE level = 'B1' AND hanzi = '皮帶' AND pinyin = 'pídài' AND vietnamese = 'Dây thắt lưng';
UPDATE public.dictionary_words SET example_hanzi = '夏天要多擦防曬乳，保護皮膚。', example_pinyin = 'xià tiān yào duō cā fáng shài rǔ， bǎo hù pí fū。', example_vietnamese = 'Vào mùa hè nên thoa kem chống nắng thường xuyên để bảo vệ da.' WHERE level = 'B1' AND hanzi = '皮膚' AND pinyin = 'pífū' AND vietnamese = 'Da dẻ';
UPDATE public.dictionary_words SET example_hanzi = '他每天上班都穿著一雙黑色的皮鞋。', example_pinyin = 'tā měi tiān shàng bān dōu chuān zhe yì shuāng hēi sè de pí xié。', example_vietnamese = 'Ngày nào đi làm anh ấy cũng mang một đôi giày da màu đen.' WHERE level = 'B1' AND hanzi = '皮鞋' AND pinyin = 'píxié' AND vietnamese = 'Giày da';
UPDATE public.dictionary_words SET example_hanzi = '老師這週要我們寫一篇作文。', example_pinyin = 'lǎo shī zhè zhōu yào wǒ men xiě yì piān zuò wén。', example_vietnamese = 'Tuần này thầy giáo yêu cầu chúng tôi viết một bài văn.' WHERE level = 'B1' AND hanzi = '篇' AND pinyin = 'piān' AND vietnamese = 'Bài, trang vở';
UPDATE public.dictionary_words SET example_hanzi = '他被一個假裝銀行職員的騙子騙走了不少錢。', example_pinyin = 'tā bèi yí gè jiǎ zhuāng yín háng zhí yuán de piàn zi piàn zǒu le bù shǎo qián。', example_vietnamese = 'Anh ấy đã bị một tên lừa đảo giả danh nhân viên ngân hàng lừa mất không ít tiền.' WHERE level = 'B1' AND hanzi = '騙子' AND pinyin = 'piànzi' AND vietnamese = 'Tên lừa đảo';
UPDATE public.dictionary_words SET example_hanzi = '這家工廠生產的產品品質一向很穩定。', example_pinyin = 'zhè jiā gōng chǎng shēng chǎn de chǎn pǐn pǐn zhí yí xiàng hěn wěn dìng。', example_vietnamese = 'Chất lượng sản phẩm do nhà máy này sản xuất luôn ổn định.' WHERE level = 'B1' AND hanzi = '品質' AND pinyin = 'pĭnzhí' AND vietnamese = 'Phẩm chất';
UPDATE public.dictionary_words SET example_hanzi = '這間套房大約有八坪大。', example_pinyin = 'zhè jiān tào fáng dà yuē yǒu bā píng dà。', example_vietnamese = 'Căn phòng trọ này rộng khoảng tám bình (đơn vị diện tích Đài Loan).' WHERE level = 'B1' AND hanzi = '坪' AND pinyin = 'píng' AND vietnamese = 'bãi đất ,';
UPDATE public.dictionary_words SET example_hanzi = '這條路修得又平又直，開車很舒服。', example_pinyin = 'zhè tiáo lù xiū de yòu píng yòu zhí， kāi chē hěn shū fu。', example_vietnamese = 'Con đường này được sửa vừa bằng phẳng vừa thẳng, lái xe rất thoải mái.' WHERE level = 'B1' AND hanzi = '平' AND pinyin = 'píng' AND vietnamese = 'Bằng phẳng, san bằng';
UPDATE public.dictionary_words SET example_hanzi = '祝你旅途平安，早日回來。', example_pinyin = 'zhù nǐ lǚ tú píng ān， zǎo rì huí lái。', example_vietnamese = 'Chúc bạn đi đường bình an, sớm ngày trở về.' WHERE level = 'B1' AND hanzi = '平安' AND pinyin = 'píngān' AND vietnamese = 'Bình an';
UPDATE public.dictionary_words SET example_hanzi = '法律面前，人人平等。', example_pinyin = 'fǎ lǜ miàn qián， rén rén píng děng。', example_vietnamese = 'Trước pháp luật, mọi người đều bình đẳng.' WHERE level = 'B1' AND hanzi = '平等' AND pinyin = 'píngděng' AND vietnamese = 'Bình đẳng';
UPDATE public.dictionary_words SET example_hanzi = '平時他很少喝酒，只有過節才會喝一點。', example_pinyin = 'píng shí tā hěn shǎo hē jiǔ， zhǐ yǒu guò jié cái huì hē yì diǎn。', example_vietnamese = 'Bình thường anh ấy rất ít khi uống rượu, chỉ có dịp lễ mới uống một chút.' WHERE level = 'B1' AND hanzi = '平時' AND pinyin = 'píngshí' AND vietnamese = 'Bình thường';
UPDATE public.dictionary_words SET example_hanzi = '這片平原土地肥沃，非常適合種稻米。', example_pinyin = 'zhè piàn píng yuán tǔ dì féi wò， fēi cháng shì hé zhòng dào mǐ。', example_vietnamese = 'Vùng đồng bằng này đất đai màu mỡ, rất thích hợp để trồng lúa.' WHERE level = 'B1' AND hanzi = '平原' AND pinyin = 'píngyuán' AND vietnamese = 'Đồng bằng, bình nguyên';
UPDATE public.dictionary_words SET example_hanzi = '這個瓶子裝滿了他從海邊撿回來的貝殼。', example_pinyin = 'zhè ge píng zi zhuāng mǎn le tā cóng hǎi biān jiǎn huí lái de bèi ké。', example_vietnamese = 'Chiếc bình này đựng đầy vỏ sò mà anh ấy nhặt được từ bờ biển.' WHERE level = 'B1' AND hanzi = '瓶子' AND pinyin = 'píngzi' AND vietnamese = 'Bình, chai';
UPDATE public.dictionary_words SET example_hanzi = '他不小心把碗打破了。', example_pinyin = 'tā bù xiǎo xīn bǎ wǎn dǎ pò le。', example_vietnamese = 'Anh ấy vô ý làm vỡ cái bát.' WHERE level = 'B1' AND hanzi = '破' AND pinyin = 'pò' AND vietnamese = 'Vỡ, thủng';
UPDATE public.dictionary_words SET example_hanzi = '亂丟垃圾會破壞環境的美觀。', example_pinyin = 'luàn diū lā jī huì pò huài huán jìng de měi guān。', example_vietnamese = 'Xả rác bừa bãi sẽ phá hoại vẻ đẹp của môi trường.' WHERE level = 'B1' AND hanzi = '破壞' AND pinyin = 'pòhuài' AND vietnamese = 'Phá hoại, làm hỏng';
UPDATE public.dictionary_words SET example_hanzi = '這串葡萄又甜又新鮮。', example_pinyin = 'zhè chuàn pú tao yòu tián yòu xīn xiān。', example_vietnamese = 'Chùm nho này vừa ngọt vừa tươi.' WHERE level = 'B1' AND hanzi = '葡萄' AND pinyin = 'pútao' AND vietnamese = 'Trái nho';
UPDATE public.dictionary_words SET example_hanzi = '現在使用手機付款已經非常普遍了。', example_pinyin = 'xiàn zài shǐ yòng shǒu jī fù kuǎn yǐ jīng fēi cháng pǔ biàn le。', example_vietnamese = 'Hiện nay việc thanh toán bằng điện thoại di động đã rất phổ biến.' WHERE level = 'B1' AND hanzi = '普遍' AND pinyin = 'pŭbiàn' AND vietnamese = 'Phổ biến';
UPDATE public.dictionary_words SET example_hanzi = '老師發現有同學在欺負轉學生，馬上出面制止。', example_pinyin = 'lǎo shī fā xiàn yǒu tóng xué zài qī fù zhuǎn xué shēng， mǎ shàng chū miàn zhì zhǐ。', example_vietnamese = 'Thầy giáo phát hiện có bạn học đang bắt nạt học sinh chuyển trường liền ra can ngăn ngay.' WHERE level = 'B1' AND hanzi = '欺負' AND pinyin = 'qīfù' AND vietnamese = 'Bắt nạt, ăn hiếp';
UPDATE public.dictionary_words SET example_hanzi = '首先要感謝大家的幫忙，其次是感謝主辦單位的用心。', example_pinyin = 'shǒu xiān yào gǎn xiè dà jiā de bāng máng， qí cì shì gǎn xiè zhǔ bàn dān wèi de yòng xīn。', example_vietnamese = 'Trước tiên xin cảm ơn sự giúp đỡ của mọi người, tiếp theo là cảm ơn sự tận tâm của ban tổ chức.' WHERE level = 'B1' AND hanzi = '其次' AND pinyin = 'qícì' AND vietnamese = 'Lần sau, lần tiếp theo';
UPDATE public.dictionary_words SET example_hanzi = '他看起來很嚴肅，其實個性非常溫柔。', example_pinyin = 'tā kàn qǐ lái hěn yán sù， qí shí gè xìng fēi cháng wēn róu。', example_vietnamese = 'Anh ấy trông có vẻ nghiêm túc, nhưng thực ra tính cách rất dịu dàng.' WHERE level = 'B1' AND hanzi = '其實' AND pinyin = 'qíshí' AND vietnamese = 'Thực ra';
UPDATE public.dictionary_words SET example_hanzi = '這班有三十個學生，其中十個是外國人。', example_pinyin = 'zhè bān yǒu sān shí gè xué sheng， qí zhōng shí gè shì wài guó rén。', example_vietnamese = 'Lớp này có ba mươi học sinh, trong đó mười người là người nước ngoài.' WHERE level = 'B1' AND hanzi = '其中' AND pinyin = 'qízhōng' AND vietnamese = 'Trong đó';
UPDATE public.dictionary_words SET example_hanzi = '這本雜誌每個月出版一期。', example_pinyin = 'zhè běn zá zhì měi gè yuè chū bǎn yì qí。', example_vietnamese = 'Tạp chí này mỗi tháng xuất bản một kỳ.' WHERE level = 'B1' AND hanzi = '期' AND pinyin = 'qí' AND vietnamese = 'kì ,';
UPDATE public.dictionary_words SET example_hanzi = '放假期間，公司大門會暫時關閉。', example_pinyin = 'fàng jià qí jiān， gōng sī dà mén huì zàn shí guān bì。', example_vietnamese = 'Trong thời gian nghỉ lễ, cổng chính công ty sẽ tạm thời đóng cửa.' WHERE level = 'B1' AND hanzi = '期間' AND pinyin = 'qíjiān' AND vietnamese = 'Dịp, thời kì, thời gian';
UPDATE public.dictionary_words SET example_hanzi = '從明天起，這條路將開始施工。', example_pinyin = 'cóng míng tiān qǐ， zhè tiáo lù jiāng kāi shǐ shī gōng。', example_vietnamese = 'Từ ngày mai trở đi, con đường này sẽ bắt đầu thi công.' WHERE level = 'B1' AND hanzi = '起' AND pinyin = 'qĭ' AND vietnamese = 'Rời khỏi, nảy lên';
UPDATE public.dictionary_words SET example_hanzi = '他一早就起床，去公園運動。', example_pinyin = 'tā yì zǎo jiù qǐ chuáng， qù gōng yuán yùn dòng。', example_vietnamese = 'Anh ấy dậy từ sáng sớm rồi đi công viên tập thể dục.' WHERE level = 'B1' AND hanzi = '起' AND pinyin = 'qĭ' AND vietnamese = 'Nhổ, nhấc, lôi lên';
UPDATE public.dictionary_words SET example_hanzi = '這件事說起來簡單，做起來卻很難。', example_pinyin = 'zhè jiàn shì shuō qǐ lái jiǎn dān， zuò qǐ lái què hěn nán。', example_vietnamese = 'Việc này nói thì nghe đơn giản, nhưng làm thì lại rất khó.' WHERE level = 'B1' AND hanzi = '起來' AND pinyin = 'qĭlái' AND vietnamese = 'Ngồi dậy, đứng dậy';
UPDATE public.dictionary_words SET example_hanzi = '山上的空氣特別新鮮。', example_pinyin = 'shān shàng de kōng qì tè bié xīn xiān。', example_vietnamese = 'Không khí trên núi đặc biệt trong lành.' WHERE level = 'B1' AND hanzi = '氣' AND pinyin = 'qì' AND vietnamese = 'Không khí, hơi thở';
UPDATE public.dictionary_words SET example_hanzi = '他被弟弟的話氣得說不出話來。', example_pinyin = 'tā bèi dì di de huà qì de shuō bù chū huà lái。', example_vietnamese = 'Anh ấy bị lời nói của em trai làm cho tức đến không nói nên lời.' WHERE level = 'B1' AND hanzi = '氣' AND pinyin = 'qì' AND vietnamese = 'Bực bội, nổi cáu';
UPDATE public.dictionary_words SET example_hanzi = '這幾天氣溫下降了不少，記得多穿一點。', example_pinyin = 'zhè jǐ tiān qì wēn xià jiàng le bù shǎo， jì de duō chuān yì diǎn。', example_vietnamese = 'Mấy ngày nay nhiệt độ giảm khá nhiều, nhớ mặc thêm áo ấm.' WHERE level = 'B1' AND hanzi = '氣溫' AND pinyin = 'qìwēn' AND vietnamese = 'Nhiệt độ không khí';
UPDATE public.dictionary_words SET example_hanzi = '天氣這麼熱，來一杯冰汽水最舒服了。', example_pinyin = 'tiān qì zhè me rè， lái yì bēi bīng qì shuǐ zuì shū fu le。', example_vietnamese = 'Trời nóng thế này, uống một ly nước có ga đá lạnh là thoải mái nhất.' WHERE level = 'B1' AND hanzi = '汽水' AND pinyin = 'qìshuǐ' AND vietnamese = 'Nước có ga';
UPDATE public.dictionary_words SET example_hanzi = '這家企業每年都會招募不少新員工。', example_pinyin = 'zhè jiā qǐ yè měi nián dōu huì zhāo mù bù shǎo xīn yuán gōng。', example_vietnamese = 'Doanh nghiệp này mỗi năm đều tuyển dụng không ít nhân viên mới.' WHERE level = 'B1' AND hanzi = '企業' AND pinyin = 'qìyè' AND vietnamese = 'Xí nghiệp';
UPDATE public.dictionary_words SET example_hanzi = '請在這份合約的最後簽名。', example_pinyin = 'qǐng zài zhè fèn hé yuē de zuì hòu qiān míng。', example_vietnamese = 'Xin vui lòng ký tên vào cuối bản hợp đồng này.' WHERE level = 'B1' AND hanzi = '簽名' AND pinyin = 'qiānmíng' AND vietnamese = 'Ký tên';
UPDATE public.dictionary_words SET example_hanzi = '去美國旅遊之前，我需要先申請簽證。', example_pinyin = 'qù měi guó lǚ yóu zhī qián， wǒ xū yào xiān shēn qǐng qiān zhèng。', example_vietnamese = 'Trước khi đi du lịch Mỹ, tôi cần xin visa trước.' WHERE level = 'B1' AND hanzi = '簽證' AND pinyin = 'qiānzhèng' AND vietnamese = 'Thị thực, visa';
UPDATE public.dictionary_words SET example_hanzi = '雖然成績優秀，他還是非常謙虛。', example_pinyin = 'suī rán chéng jī yōu xiù， tā hái shi fēi cháng qiān xū。', example_vietnamese = 'Mặc dù thành tích xuất sắc, anh ấy vẫn rất khiêm tốn.' WHERE level = 'B1' AND hanzi = '謙虛' AND pinyin = 'qiānxū' AND vietnamese = 'Khiêm tốn, khiêm nhường';
UPDATE public.dictionary_words SET example_hanzi = '前三名的選手可以獲得獎金。', example_pinyin = 'qián sān míng de xuǎn shǒu kě yǐ huò dé jiǎng jīn。', example_vietnamese = 'Ba thí sinh đứng đầu sẽ nhận được tiền thưởng.' WHERE level = 'B1' AND hanzi = '前' AND pinyin = 'qián' AND vietnamese = 'Trước';
UPDATE public.dictionary_words SET example_hanzi = '車站前有很多賣小吃的攤販。', example_pinyin = 'chē zhàn qián yǒu hěn duō mài xiǎo chī de tān fàn。', example_vietnamese = 'Phía trước nhà ga có rất nhiều quầy hàng bán đồ ăn vặt.' WHERE level = 'B1' AND hanzi = '前' AND pinyin = 'qián' AND vietnamese = 'Phía trước';
UPDATE public.dictionary_words SET example_hanzi = '我們前年去日本旅行過一次。', example_pinyin = 'wǒ men qián nián qù rì běn lǚ xíng guò yí cì。', example_vietnamese = 'Năm kia chúng tôi đã đi du lịch Nhật Bản một lần.' WHERE level = 'B1' AND hanzi = '前年' AND pinyin = 'qiánnián' AND vietnamese = 'Năm trước, năm kia';
UPDATE public.dictionary_words SET example_hanzi = '這條河很淺，小孩子也可以安全地玩水。', example_pinyin = 'zhè tiáo hé hěn qiǎn， xiǎo hái zi yě kě yǐ ān quán de wán shuǐ。', example_vietnamese = 'Con sông này rất cạn, trẻ con cũng có thể chơi nước an toàn.' WHERE level = 'B1' AND hanzi = '淺' AND pinyin = 'qiǎn' AND vietnamese = 'Róc rách (tiếng nước chảy)';
UPDATE public.dictionary_words SET example_hanzi = '警察昨晚抓到了搶劫銀行的強盜。', example_pinyin = 'jǐng chá zuó wǎn zhuā dào le qiǎng jié yín háng de qiáng dào。', example_vietnamese = 'Tối qua cảnh sát đã bắt được tên cướp cướp ngân hàng.' WHERE level = 'B1' AND hanzi = '強盜' AND pinyin = 'qiángdào' AND vietnamese = 'Bọn giặc, bọn cướp';
UPDATE public.dictionary_words SET example_hanzi = '老師一再強調考試前要複習重點。', example_pinyin = 'lǎo shī yí zài qiáng diào kǎo shì qián yào fù xí zhòng diǎn。', example_vietnamese = 'Thầy giáo liên tục nhấn mạnh trước khi thi phải ôn lại những điểm quan trọng.' WHERE level = 'B1' AND hanzi = '強調' AND pinyin = 'qiángdiào' AND vietnamese = 'Cường điệu, nhấn mạnh';
UPDATE public.dictionary_words SET example_hanzi = '小偷搶了她的皮包就跑了。', example_pinyin = 'xiǎo tōu qiǎng le tā de pí bāo jiù pǎo le。', example_vietnamese = 'Tên trộm giật lấy túi xách của cô ấy rồi bỏ chạy.' WHERE level = 'B1' AND hanzi = '搶' AND pinyin = 'qiǎng' AND vietnamese = 'Va, đập';
UPDATE public.dictionary_words SET example_hanzi = '媽媽親了親寶寶的臉頰。', example_pinyin = 'mā ma qīn le qīn bǎo bao de liǎn jiá。', example_vietnamese = 'Mẹ hôn hôn lên má của em bé.' WHERE level = 'B1' AND hanzi = '親' AND pinyin = 'qīn' AND vietnamese = 'Thông gia, sui gia';
UPDATE public.dictionary_words SET example_hanzi = '這裡的服務人員都非常親切。', example_pinyin = 'zhè lǐ de fú wù rén yuán dōu fēi cháng qīn qiè。', example_vietnamese = 'Nhân viên phục vụ ở đây đều rất thân thiện.' WHERE level = 'B1' AND hanzi = '親切' AND pinyin = 'qīnqiè' AND vietnamese = 'Thân mật, thân thiết';
UPDATE public.dictionary_words SET example_hanzi = '這件毛衣是奶奶親手織的。', example_pinyin = 'zhè jiàn máo yī shì nǎi nai qīn shǒu zhī de。', example_vietnamese = 'Chiếc áo len này là do bà tự tay đan.' WHERE level = 'B1' AND hanzi = '親手' AND pinyin = 'qīnshŏu' AND vietnamese = 'Tự tay, chính tay';
UPDATE public.dictionary_words SET example_hanzi = '我親眼看到那場車禍發生的經過。', example_pinyin = 'wǒ qīn yǎn kàn dào nà chǎng chē huò fā shēng de jīng guò。', example_vietnamese = 'Tôi đã tận mắt chứng kiến toàn bộ quá trình xảy ra vụ tai nạn đó.' WHERE level = 'B1' AND hanzi = '親眼' AND pinyin = 'qīnyăn' AND vietnamese = 'Tận mắt, chính mắt';
UPDATE public.dictionary_words SET example_hanzi = '校長親自到機場迎接來訪的貴賓。', example_pinyin = 'xiào zhǎng qīn zì dào jī chǎng yíng jiē lái fǎng de guì bīn。', example_vietnamese = 'Hiệu trưởng đích thân ra sân bay đón vị khách quý đến thăm.' WHERE level = 'B1' AND hanzi = '親自' AND pinyin = 'qīnzì' AND vietnamese = 'Tự mình, đích thân';
UPDATE public.dictionary_words SET example_hanzi = '這條溪水清得可以看到水底的石頭。', example_pinyin = 'zhè tiáo xī shuǐ qīng de kě yǐ kàn dào shuǐ dǐ de shí tou。', example_vietnamese = 'Dòng suối này trong đến mức có thể nhìn thấy đá dưới đáy nước.' WHERE level = 'B1' AND hanzi = '清' AND pinyin = 'qīng' AND vietnamese = 'Trong suốt, trong veo';
UPDATE public.dictionary_words SET example_hanzi = '這場活動主要是為了鼓勵年輕的青年創業。', example_pinyin = 'zhè chǎng huó dòng zhǔ yào shì wèi le gǔ lì nián qīng de qīng nián chuàng yè。', example_vietnamese = 'Hoạt động này chủ yếu nhằm khuyến khích thanh niên trẻ khởi nghiệp.' WHERE level = 'B1' AND hanzi = '青年' AND pinyin = 'qīngnián' AND vietnamese = 'Tuổi trẻ, thanh niên';
UPDATE public.dictionary_words SET example_hanzi = '這部電影特別受到青少年的喜愛。', example_pinyin = 'zhè bù diàn yǐng tè bié shòu dào qīng shào nián de xǐ ài。', example_vietnamese = 'Bộ phim này đặc biệt được thanh thiếu niên yêu thích.' WHERE level = 'B1' AND hanzi = '青少年' AND pinyin = 'qīngshàonián' AND vietnamese = 'Vị thành niên, thiếu niên';
UPDATE public.dictionary_words SET example_hanzi = '考完試以後，他終於覺得輕鬆多了。', example_pinyin = 'kǎo wán shì yǐ hòu， tā zhōng yú jué de qīng sōng duō le。', example_vietnamese = 'Sau khi thi xong, cuối cùng anh ấy cũng cảm thấy nhẹ nhõm hơn nhiều.' WHERE level = 'B1' AND hanzi = '輕鬆' AND pinyin = 'qīngsōng' AND vietnamese = 'Nhẹ nhàng, nhẹ nhõm';
UPDATE public.dictionary_words SET example_hanzi = '今天天氣很晴朗，很適合出去踏青。', example_pinyin = 'jīn tiān tiān qì hěn qíng lǎng， hěn shì hé chū qù tà qīng。', example_vietnamese = 'Hôm nay trời rất quang đãng, rất thích hợp để đi dạo ngoài trời.' WHERE level = 'B1' AND hanzi = '晴' AND pinyin = 'qíng' AND vietnamese = 'Trời quang';
UPDATE public.dictionary_words SET example_hanzi = '他們兩個人之間的情，早就超過了普通朋友。', example_pinyin = 'tā men liǎng gè rén zhī jiān de qíng， zǎo jiù chāo guò le pǔ tōng péng you。', example_vietnamese = 'Tình cảm giữa hai người họ đã sớm vượt qua ranh giới bạn bè bình thường.' WHERE level = 'B1' AND hanzi = '情' AND pinyin = 'qíng' AND vietnamese = 'Tình cảm';
UPDATE public.dictionary_words SET example_hanzi = '二月十四號是全世界情人的節日。', example_pinyin = 'èr yuè shí sì hào shì quán shì jiè qíng rén de jié rì。', example_vietnamese = 'Ngày 14 tháng 2 là ngày lễ của các đôi tình nhân trên toàn thế giới.' WHERE level = 'B1' AND hanzi = '情人' AND pinyin = 'qíngrén' AND vietnamese = 'Tình nhân, người yêu';
UPDATE public.dictionary_words SET example_hanzi = '如果遇到緊急情況，請立刻打電話給我。', example_pinyin = 'rú guǒ yù dào jǐn jí qíng kuàng， qǐng lì kè dǎ diàn huà gěi wǒ。', example_vietnamese = 'Nếu gặp phải tình huống khẩn cấp, hãy gọi điện cho tôi ngay lập tức.' WHERE level = 'B1' AND hanzi = '情況' AND pinyin = 'qíngkuàng' AND vietnamese = 'Tình huống';
UPDATE public.dictionary_words SET example_hanzi = '老師仔細說明了目前班上的學習情形。', example_pinyin = 'lǎo shī zǐ xì shuō míng le mù qián bān shàng de xué xí qíng xíng。', example_vietnamese = 'Thầy giáo giải thích chi tiết về tình hình học tập hiện tại của lớp.' WHERE level = 'B1' AND hanzi = '情形' AND pinyin = 'qíngxíng' AND vietnamese = 'Tình hình';
UPDATE public.dictionary_words SET example_hanzi = '我想請教您一個關於文法的問題。', example_pinyin = 'wǒ xiǎng qǐng jiào nín yí gè guān yú wén fǎ de wèn tí。', example_vietnamese = 'Tôi muốn xin thầy chỉ bảo cho một vấn đề về ngữ pháp.' WHERE level = 'B1' AND hanzi = '請教' AND pinyin = 'qĭngjiào' AND vietnamese = 'Thỉnh giáo, xin chỉ bảo';
UPDATE public.dictionary_words SET example_hanzi = '他向老闆請求多放一天假。', example_pinyin = 'tā xiàng lǎo bǎn qǐng qiú duō fàng yì tiān jià。', example_vietnamese = 'Anh ấy đề nghị ông chủ cho nghỉ thêm một ngày.' WHERE level = 'B1' AND hanzi = '請求' AND pinyin = 'qĭngqiú' AND vietnamese = 'Thỉnh cầu, đề nghị';
UPDATE public.dictionary_words SET example_hanzi = '他小時候家裡很窮，但一直很努力讀書。', example_pinyin = 'tā xiǎo shí hou jiā lǐ hěn qióng， dàn yì zhí hěn nǔ lì dú shū。', example_vietnamese = 'Hồi nhỏ nhà anh ấy rất nghèo, nhưng luôn chăm chỉ học hành.' WHERE level = 'B1' AND hanzi = '窮' AND pinyin = 'qióng' AND vietnamese = 'Nghèo nàn';
UPDATE public.dictionary_words SET example_hanzi = '他跪下來求媽媽原諒他的錯誤。', example_pinyin = 'tā guì xià lái qiú mā ma yuán liàng tā de cuò wù。', example_vietnamese = 'Anh ấy quỳ xuống cầu xin mẹ tha thứ cho lỗi lầm của mình.' WHERE level = 'B1' AND hanzi = '求' AND pinyin = 'qiú' AND vietnamese = 'Thỉnh cầu, yêu cầu';
UPDATE public.dictionary_words SET example_hanzi = '弟弟最喜歡的運動是踢球。', example_pinyin = 'dì di zuì xǐ huan de yùn dòng shì tī qiú。', example_vietnamese = 'Môn thể thao mà em trai thích nhất là đá bóng.' WHERE level = 'B1' AND hanzi = '球' AND pinyin = 'qiú' AND vietnamese = 'Hình cầu';
UPDATE public.dictionary_words SET example_hanzi = '每到週末，球場上總是擠滿了人。', example_pinyin = 'měi dào zhōu mò， qiú chǎng shàng zǒng shì jǐ mǎn le rén。', example_vietnamese = 'Cứ đến cuối tuần là sân bóng lại đông nghịt người.' WHERE level = 'B1' AND hanzi = '球場' AND pinyin = 'qiúchăng' AND vietnamese = 'Sân bóng';
UPDATE public.dictionary_words SET example_hanzi = '昨天晚上的球賽真是精彩極了。', example_pinyin = 'zuó tiān wǎn shang de qiú sài zhēn shì jīng cǎi jí le。', example_vietnamese = 'Trận đấu bóng tối qua thật sự vô cùng hấp dẫn.' WHERE level = 'B1' AND hanzi = '球賽' AND pinyin = 'qiúsài' AND vietnamese = 'Cuộc thi đấu bóng';
UPDATE public.dictionary_words SET example_hanzi = '那位球員今天一連進了三顆球。', example_pinyin = 'nà wèi qiú yuán jīn tiān yì lián jìn le sān kē qiú。', example_vietnamese = 'Cầu thủ đó hôm nay liên tiếp ghi được ba bàn thắng.' WHERE level = 'B1' AND hanzi = '球員' AND pinyin = 'qiúyuán' AND vietnamese = 'Cầu thủ';
UPDATE public.dictionary_words SET example_hanzi = '人工智慧可能會取代部分傳統工作。', example_pinyin = 'rén gōng zhì huì kě néng huì qǔ dài bù fen chuán tǒng gōng zuò。', example_vietnamese = 'Trí tuệ nhân tạo có thể sẽ thay thế một số công việc truyền thống.' WHERE level = 'B1' AND hanzi = '取代' AND pinyin = 'qŭdài' AND vietnamese = 'Lật đổ, thay thế địa vị';
UPDATE public.dictionary_words SET example_hanzi = '他把垃圾拿出去丟了。', example_pinyin = 'tā bǎ lā jī ná chū qu diū le。', example_vietnamese = 'Anh ấy mang rác ra ngoài vứt rồi.' WHERE level = 'B1' AND hanzi = '去' AND pinyin = 'qù' AND vietnamese = 'Rời bỏ, mất đi';
UPDATE public.dictionary_words SET example_hanzi = '去年冬天特別冷。', example_pinyin = 'qù nián dōng tiān tè bié lěng。', example_vietnamese = 'Mùa đông năm ngoái đặc biệt lạnh.' WHERE level = 'B1' AND hanzi = '去' AND pinyin = 'qù' AND vietnamese = 'Năm ngoái, mùa trước';
UPDATE public.dictionary_words SET example_hanzi = '他的爺爺去年因病去世了。', example_pinyin = 'tā de yé ye qù nián yīn bìng qù shì le。', example_vietnamese = 'Ông nội anh ấy năm ngoái đã qua đời vì bệnh.' WHERE level = 'B1' AND hanzi = '去世' AND pinyin = 'qùshì' AND vietnamese = 'Qua đời, mất';
UPDATE public.dictionary_words SET example_hanzi = '全班同學都通過了這次考試。', example_pinyin = 'quán bān tóng xué dōu tōng guò le zhè cì kǎo shì。', example_vietnamese = 'Toàn bộ học sinh trong lớp đều đã vượt qua kỳ thi lần này.' WHERE level = 'B1' AND hanzi = '全' AND pinyin = 'quán' AND vietnamese = 'Đầy đủ, toàn bộ';
UPDATE public.dictionary_words SET example_hanzi = '這種病毒短短幾個月就傳到了全球各地。', example_pinyin = 'zhè zhǒng bìng dú duǎn duǎn jǐ gè yuè jiù chuán dào le quán qiú gè dì。', example_vietnamese = 'Loại virus này chỉ trong vài tháng ngắn ngủi đã lan ra khắp toàn cầu.' WHERE level = 'B1' AND hanzi = '全球' AND pinyin = 'quánqiú' AND vietnamese = 'Toàn cầu, toàn thế giới';
UPDATE public.dictionary_words SET example_hanzi = '跑完馬拉松以後，他全身都痠痛得不得了。', example_pinyin = 'pǎo wán mǎ lā sōng yǐ hòu， tā quán shēn dōu suān tòng de bù dé liǎo。', example_vietnamese = 'Sau khi chạy xong marathon, toàn thân anh ấy đau nhức không chịu nổi.' WHERE level = 'B1' AND hanzi = '全身' AND pinyin = 'quánshēn' AND vietnamese = 'Toàn thân';
UPDATE public.dictionary_words SET example_hanzi = '每個人都有優點跟缺點。', example_pinyin = 'měi gè rén dōu yǒu yōu diǎn gēn quē diǎn。', example_vietnamese = 'Mỗi người đều có ưu điểm và khuyết điểm.' WHERE level = 'B1' AND hanzi = '缺點' AND pinyin = 'quēdiăn' AND vietnamese = 'Khuyết điểm';
UPDATE public.dictionary_words SET example_hanzi = '他明明很累，卻還是堅持把工作做完。', example_pinyin = 'tā míng míng hěn lèi， què hái shi jiān chí bǎ gōng zuò zuò wán。', example_vietnamese = 'Rõ ràng anh ấy rất mệt, nhưng vẫn kiên trì hoàn thành công việc.' WHERE level = 'B1' AND hanzi = '卻' AND pinyin = 'què' AND vietnamese = 'Mà lại';
UPDATE public.dictionary_words SET example_hanzi = '你確定明天有空一起去看電影嗎？', example_pinyin = 'nǐ què dìng míng tiān yǒu kòng yì qǐ qù kàn diàn yǐng ma？', example_vietnamese = 'Bạn có chắc chắn ngày mai rảnh để cùng đi xem phim không?' WHERE level = 'B1' AND hanzi = '確定' AND pinyin = 'quèdìng' AND vietnamese = 'Xác định';
UPDATE public.dictionary_words SET example_hanzi = '出發前請再確認一次機票和護照。', example_pinyin = 'chū fā qián qǐng zài què rèn yí cì jī piào hàn hù zhào。', example_vietnamese = 'Trước khi khởi hành hãy xác nhận lại vé máy bay và hộ chiếu một lần nữa.' WHERE level = 'B1' AND hanzi = '確認' AND pinyin = 'quèrèn' AND vietnamese = 'Xác nhận';
UPDATE public.dictionary_words SET example_hanzi = '公車上，他主動讓座給一位老太太。', example_pinyin = 'gōng chē shàng， tā zhǔ dòng ràng zuò gěi yí wèi lǎo tài tai。', example_vietnamese = 'Trên xe buýt, anh ấy chủ động nhường ghế cho một bà cụ.' WHERE level = 'B1' AND hanzi = '讓' AND pinyin = 'ràng' AND vietnamese = 'Nhường';
UPDATE public.dictionary_words SET example_hanzi = '棒球場外常常有攤販在賣熱狗。', example_pinyin = 'bàng qiú chǎng wài cháng cháng yǒu tān fàn zài mài rè gǒu。', example_vietnamese = 'Bên ngoài sân bóng chày thường có quầy hàng bán bánh hotdog.' WHERE level = 'B1' AND hanzi = '熱狗' AND pinyin = 'règŏu' AND vietnamese = 'Bánh hotdog';
UPDATE public.dictionary_words SET example_hanzi = '這台機器隨時都有熱水可以泡茶。', example_pinyin = 'zhè tái jī qì suí shí dōu yǒu rè shuǐ kě yǐ pào chá。', example_vietnamese = 'Chiếc máy này lúc nào cũng có nước nóng để pha trà.' WHERE level = 'B1' AND hanzi = '熱水' AND pinyin = 'rèshuǐ' AND vietnamese = 'Nước nóng';
UPDATE public.dictionary_words SET example_hanzi = '人家已經跟你說了好幾次，你怎麼還不懂？', example_pinyin = 'rén jiā yǐ jīng gēn nǐ shuō le hǎo jǐ cì， nǐ zěn me hái bù dǒng？', example_vietnamese = 'Người ta đã nói với bạn bao nhiêu lần rồi, sao bạn vẫn chưa hiểu vậy?' WHERE level = 'B1' AND hanzi = '人家' AND pinyin = 'rénjiā' AND vietnamese = 'Nhà, hộ, gia đình';
UPDATE public.dictionary_words SET example_hanzi = '這裡的風景美得就像人間仙境。', example_pinyin = 'zhè lǐ de fēng jǐng měi de jiù xiàng rén jiān xiān jìng。', example_vietnamese = 'Phong cảnh nơi đây đẹp như chốn tiên cảnh giữa nhân gian.' WHERE level = 'B1' AND hanzi = '人間' AND pinyin = 'rénjiān' AND vietnamese = 'Nhân gian, trần gian';
UPDATE public.dictionary_words SET example_hanzi = '這個城市的人口這幾年增加得很快。', example_pinyin = 'zhè ge chéng shì de rén kǒu zhè jǐ nián zēng jiā de hěn kuài。', example_vietnamese = 'Dân số thành phố này mấy năm gần đây tăng rất nhanh.' WHERE level = 'B1' AND hanzi = '人口' AND pinyin = 'rénkǒu' AND vietnamese = 'Nhân khẩu, dân số';
UPDATE public.dictionary_words SET example_hanzi = '環境污染已經嚴重威脅到人類的健康。', example_pinyin = 'huán jìng wū rǎn yǐ jīng yán zhòng wēi xié dào rén lèi de jiàn kāng。', example_vietnamese = 'Ô nhiễm môi trường đã đe dọa nghiêm trọng đến sức khỏe của loài người.' WHERE level = 'B1' AND hanzi = '人類' AND pinyin = 'rénlèi' AND vietnamese = 'Loài người, nhân loại';
UPDATE public.dictionary_words SET example_hanzi = '節慶期間，人們都會回到家鄉和家人團聚。', example_pinyin = 'jié qìng qī jiān， rén men dōu huì huí dào jiā xiāng hàn jiā rén tuán jù。', example_vietnamese = 'Vào dịp lễ hội, mọi người đều trở về quê hương đoàn tụ cùng gia đình.' WHERE level = 'B1' AND hanzi = '人們' AND pinyin = 'rénmen' AND vietnamese = 'Mọi người';
UPDATE public.dictionary_words SET example_hanzi = '政府的政策應該以人民的利益為優先。', example_pinyin = 'zhèng fǔ de zhèng cè yīng gāi yǐ rén mín de lì yì wéi yōu xiān。', example_vietnamese = 'Chính sách của chính phủ nên lấy lợi ích của nhân dân làm ưu tiên hàng đầu.' WHERE level = 'B1' AND hanzi = '人民' AND pinyin = 'rénmín' AND vietnamese = 'Nhân dân';
UPDATE public.dictionary_words SET example_hanzi = '這件事人人都知道，早就不是秘密了。', example_pinyin = 'zhè jiàn shì rén rén dōu zhī dào， zǎo jiù bú shì mì mì le。', example_vietnamese = 'Chuyện này ai cũng biết cả rồi, sớm đã không còn là bí mật nữa.' WHERE level = 'B1' AND hanzi = '人人' AND pinyin = 'rénrén' AND vietnamese = 'Người người, mọi người';
UPDATE public.dictionary_words SET example_hanzi = '這場演唱會的參加人數超過了五萬人。', example_pinyin = 'zhè chǎng yǎn chàng huì de cān jiā rén shù chāo guò le wǔ wàn rén。', example_vietnamese = 'Số người tham gia buổi hòa nhạc này vượt quá năm mươi nghìn người.' WHERE level = 'B1' AND hanzi = '人數' AND pinyin = 'rénshù' AND vietnamese = 'Số người';
UPDATE public.dictionary_words SET example_hanzi = '這本小說裡的每個人物都刻劃得很生動。', example_pinyin = 'zhè běn xiǎo shuō lǐ de měi gè rén wù dōu kè huà de hěn shēng dòng。', example_vietnamese = 'Mỗi nhân vật trong cuốn tiểu thuyết này đều được khắc họa rất sống động.' WHERE level = 'B1' AND hanzi = '人物' AND pinyin = 'rénwù' AND vietnamese = 'Nhân vật';
UPDATE public.dictionary_words SET example_hanzi = '他痛得要命，還是忍著沒有哭出來。', example_pinyin = 'tā tòng de yào mìng， hái shi rěn zhe méi yǒu kū chū lái。', example_vietnamese = 'Anh ấy đau đến mức không chịu nổi nhưng vẫn nhẫn nhịn không khóc ra.' WHERE level = 'B1' AND hanzi = '忍' AND pinyin = 'rěn' AND vietnamese = 'Nhẫn nhịn, chịu đựng';
UPDATE public.dictionary_words SET example_hanzi = '面對困難的時候，我們需要多一點忍耐。', example_pinyin = 'miàn duì kùn nan de shí hou， wǒ men xū yào duō yì diǎn rěn nài。', example_vietnamese = 'Khi đối mặt với khó khăn, chúng ta cần thêm một chút nhẫn nại.' WHERE level = 'B1' AND hanzi = '忍耐' AND pinyin = 'rěnnài' AND vietnamese = 'Nhẫn nại';
UPDATE public.dictionary_words SET example_hanzi = '他終於認了錯，向大家道歉。', example_pinyin = 'tā zhōng yú rèn le cuò， xiàng dà jiā dào qiàn。', example_vietnamese = 'Cuối cùng anh ấy đã nhận lỗi và xin lỗi mọi người.' WHERE level = 'B1' AND hanzi = '認' AND pinyin = 'rèn' AND vietnamese = 'Nhận thức, thừa nhận';
UPDATE public.dictionary_words SET example_hanzi = '好久不見，你還認得我嗎？', example_pinyin = 'hǎo jiǔ bú jiàn， nǐ hái rèn de wǒ ma？', example_vietnamese = 'Lâu rồi không gặp, bạn còn nhận ra tôi không?' WHERE level = 'B1' AND hanzi = '認得' AND pinyin = 'rènde' AND vietnamese = 'Nhận ra, biết được';
UPDATE public.dictionary_words SET example_hanzi = '這次的任務非常艱鉅，需要大家一起努力。', example_pinyin = 'zhè cì de rèn wù fēi cháng jiān jù， xū yào dà jiā yì qǐ nǔ lì。', example_vietnamese = 'Nhiệm vụ lần này vô cùng gian nan, cần mọi người cùng nhau nỗ lực.' WHERE level = 'B1' AND hanzi = '任務' AND pinyin = 'rènwù' AND vietnamese = 'Nhiệm vụ';
UPDATE public.dictionary_words SET example_hanzi = '請不要隨便把垃圾扔在路邊。', example_pinyin = 'qǐng bú yào suí biàn bǎ lā jī rēng zài lù biān。', example_vietnamese = 'Xin đừng tùy tiện vứt rác bên đường.' WHERE level = 'B1' AND hanzi = '扔' AND pinyin = 'rēng' AND vietnamese = 'Ném, vứt bỏ';
UPDATE public.dictionary_words SET example_hanzi = '雖然已經道歉了，她仍不肯原諒他。', example_pinyin = 'suī rán yǐ jīng dào qiàn le， tā réng bù kěn yuán liàng tā。', example_vietnamese = 'Mặc dù đã xin lỗi rồi, cô ấy vẫn không chịu tha thứ cho anh ấy.' WHERE level = 'B1' AND hanzi = '仍' AND pinyin = 'réng' AND vietnamese = 'Dựa vào, chiếu theo, dựa theo';
UPDATE public.dictionary_words SET example_hanzi = '過了這麼多年，他仍然記得那個夏天。', example_pinyin = 'guò le zhè me duō nián， tā réng rán jì de nà ge xià tiān。', example_vietnamese = 'Qua bao nhiêu năm rồi, anh ấy vẫn còn nhớ mùa hè năm đó.' WHERE level = 'B1' AND hanzi = '仍然' AND pinyin = 'réngrán' AND vietnamese = 'Vẫn cứ, tiếp tục';
UPDATE public.dictionary_words SET example_hanzi = '我們一大早就爬到山頂去看日出。', example_pinyin = 'wǒ men yí dà zǎo jiù pá dào shān dǐng qù kàn rì chū。', example_vietnamese = 'Chúng tôi leo lên đỉnh núi từ sáng sớm để ngắm mặt trời mọc.' WHERE level = 'B1' AND hanzi = '日出' AND pinyin = 'rìchū' AND vietnamese = 'Bình minh';
UPDATE public.dictionary_words SET example_hanzi = '她每天晚上睡覺前都會寫日記。', example_pinyin = 'tā měi tiān wǎn shang shuì jiào qián dōu huì xiě rì jì。', example_vietnamese = 'Tối nào trước khi ngủ cô ấy cũng viết nhật ký.' WHERE level = 'B1' AND hanzi = '日記' AND pinyin = 'rìjì' AND vietnamese = 'Nhật ký';
UPDATE public.dictionary_words SET example_hanzi = '這幾年的日子過得平平淡淡，卻很幸福。', example_pinyin = 'zhè jǐ nián de rì zi guò de píng píng dàn dàn， què hěn xìng fú。', example_vietnamese = 'Những năm gần đây cuộc sống trôi qua bình dị nhưng lại rất hạnh phúc.' WHERE level = 'B1' AND hanzi = '日子' AND pinyin = 'rìzi' AND vietnamese = 'Ngày, thời kỳ';
UPDATE public.dictionary_words SET example_hanzi = '如你所說，這件事確實不太容易解決。', example_pinyin = 'rú nǐ suǒ shuō， zhè jiàn shì què shí bú tài róng yì jiě jué。', example_vietnamese = 'Đúng như bạn nói, việc này thực sự không dễ giải quyết.' WHERE level = 'B1' AND hanzi = '如' AND pinyin = 'rú' AND vietnamese = 'Theo như, giống như';
UPDATE public.dictionary_words SET example_hanzi = '沒想到事情會演變成如此。', example_pinyin = 'méi xiǎng dào shì qing huì yǎn biàn chéng rú cǐ。', example_vietnamese = 'Không ngờ sự việc lại diễn biến thành ra như vậy.' WHERE level = 'B1' AND hanzi = '如此' AND pinyin = 'rúcǐ' AND vietnamese = 'Như vậy, như thế';
UPDATE public.dictionary_words SET example_hanzi = '這次會議的內容整理如下。', example_pinyin = 'zhè cì huì yì de nèi róng zhěng lǐ rú xià。', example_vietnamese = 'Nội dung cuộc họp lần này được tổng hợp như sau.' WHERE level = 'B1' AND hanzi = '如下' AND pinyin = 'rúxià' AND vietnamese = 'Như sau, như dưới đây';
UPDATE public.dictionary_words SET example_hanzi = '祝你新年快樂，事事如意。', example_pinyin = 'zhù nǐ xīn nián kuài lè， shì shì rú yì。', example_vietnamese = 'Chúc bạn năm mới vui vẻ, mọi việc như ý.' WHERE level = 'B1' AND hanzi = '如意' AND pinyin = 'rúyì' AND vietnamese = 'Như ý, vừa ý';
UPDATE public.dictionary_words SET example_hanzi = '他生病以後，身體變得很虛弱。', example_pinyin = 'tā shēng bìng yǐ hòu， shēn tǐ biàn de hěn xū ruò。', example_vietnamese = 'Sau khi bị bệnh, cơ thể anh ấy trở nên rất yếu ớt.' WHERE level = 'B1' AND hanzi = '弱' AND pinyin = 'ruò' AND vietnamese = 'Yếu đuối, yếu sức';
UPDATE public.dictionary_words SET example_hanzi = '出門前記得帶把傘，今天可能會下雨。', example_pinyin = 'chū mén qián jì de dài bǎ sǎn， jīn tiān kě néng huì xià yǔ。', example_vietnamese = 'Trước khi ra ngoài nhớ mang theo ô, hôm nay có thể sẽ mưa.' WHERE level = 'B1' AND hanzi = '傘' AND pinyin = 'sǎn' AND vietnamese = 'Cái ô, dù';
UPDATE public.dictionary_words SET example_hanzi = '這部電影描述一名警察追查殺人犯的過程。', example_pinyin = 'zhè bù diàn yǐng miáo shù yì míng jǐng chá zhuī chá shā rén fàn de guò chéng。', example_vietnamese = 'Bộ phim này kể về quá trình một cảnh sát truy tìm kẻ giết người.' WHERE level = 'B1' AND hanzi = '殺' AND pinyin = 'shā' AND vietnamese = 'Giết';
UPDATE public.dictionary_words SET example_hanzi = '媽媽把衣服拿到陽台上晒。', example_pinyin = 'mā ma bǎ yī fu ná dào yáng tái shàng shài。', example_vietnamese = 'Mẹ mang quần áo ra ban công phơi nắng.' WHERE level = 'B1' AND hanzi = '晒' AND pinyin = 'shài' AND vietnamese = 'Phơi nắng, sưởi nắng';
UPDATE public.dictionary_words SET example_hanzi = '這個山區的天氣變化非常快。', example_pinyin = 'zhè ge shān qū de tiān qì biàn huà fēi cháng kuài。', example_vietnamese = 'Thời tiết ở vùng núi này thay đổi rất nhanh.' WHERE level = 'B1' AND hanzi = '山區' AND pinyin = 'shānqū' AND vietnamese = 'Vùng núi, miền núi';
UPDATE public.dictionary_words SET example_hanzi = '你說的那些話，深深傷害了她的心。', example_pinyin = 'nǐ shuō de nà xiē huà， shēn shēn shāng hài le tā de xīn。', example_vietnamese = 'Những lời bạn nói đã làm tổn thương sâu sắc đến trái tim cô ấy.' WHERE level = 'B1' AND hanzi = '傷害' AND pinyin = 'shānghài' AND vietnamese = 'Làm tổn thương';
UPDATE public.dictionary_words SET example_hanzi = '這家超市的商品種類非常齊全。', example_pinyin = 'zhè jiā chāo shì de shāng pǐn zhǒng lèi fēi cháng qí quán。', example_vietnamese = 'Chủng loại hàng hóa của siêu thị này rất đầy đủ.' WHERE level = 'B1' AND hanzi = '商品' AND pinyin = 'shāngpĭn' AND vietnamese = 'Hàng hóa';
UPDATE public.dictionary_words SET example_hanzi = '那位商人靠賣茶葉賺了不少錢。', example_pinyin = 'nà wèi shāng rén kào mài chá yè zhuàn le bù shǎo qián。', example_vietnamese = 'Vị thương nhân đó kiếm được không ít tiền nhờ bán trà.' WHERE level = 'B1' AND hanzi = '商人' AND pinyin = 'shāngrén' AND vietnamese = 'Thương nhân';
UPDATE public.dictionary_words SET example_hanzi = '這條街是全市最熱鬧的商業區。', example_pinyin = 'zhè tiáo jiē shì quán shì zuì rè nao de shāng yè qū。', example_vietnamese = 'Con phố này là khu thương mại náo nhiệt nhất thành phố.' WHERE level = 'B1' AND hanzi = '商業' AND pinyin = 'shāngyè' AND vietnamese = 'Thương mại';
UPDATE public.dictionary_words SET example_hanzi = '上一堂課教的文法你都記得嗎？', example_pinyin = 'shàng yì táng kè jiāo de wén fǎ nǐ dōu jì de ma？', example_vietnamese = 'Ngữ pháp đã học trong tiết trước bạn còn nhớ hết không?' WHERE level = 'B1' AND hanzi = '上' AND pinyin = 'shàng' AND vietnamese = 'ở trên, bên trên';
UPDATE public.dictionary_words SET example_hanzi = '桌子上放著一杯熱茶。', example_pinyin = 'zhuō zi shàng fàng zhe yì bēi rè chá。', example_vietnamese = 'Trên bàn đặt một tách trà nóng.' WHERE level = 'B1' AND hanzi = '上' AND pinyin = 'shàng' AND vietnamese = 'Trên, trước';
UPDATE public.dictionary_words SET example_hanzi = '他因為貪小便宜而上當受騙。', example_pinyin = 'tā yīn wèi tān xiǎo pián yi ér shàng dàng shòu piàn。', example_vietnamese = 'Anh ấy vì ham lợi nhỏ mà bị mắc lừa.' WHERE level = 'B1' AND hanzi = '上當' AND pinyin = 'shàngdàng' AND vietnamese = 'Bị lừa, mắc lừa';
UPDATE public.dictionary_words SET example_hanzi = '有些人相信上帝會保佑他們。', example_pinyin = 'yǒu xiē rén xiāng xìn shàng dì huì bǎo yòu tā men。', example_vietnamese = 'Một số người tin rằng Thượng Đế sẽ phù hộ cho họ.' WHERE level = 'B1' AND hanzi = '上帝' AND pinyin = 'shàngdì' AND vietnamese = 'Thượng đế';
UPDATE public.dictionary_words SET example_hanzi = '週末我常常和朋友一起上街逛逛。', example_pinyin = 'zhōu mò wǒ cháng cháng hàn péng you yì qǐ shàng jiē guàng guang。', example_vietnamese = 'Cuối tuần tôi thường cùng bạn bè ra phố dạo chơi.' WHERE level = 'B1' AND hanzi = '上街' AND pinyin = 'shàngjiē' AND vietnamese = 'Đi ra ngoài đường';
UPDATE public.dictionary_words SET example_hanzi = '他今天穿了一件白色的上衣。', example_pinyin = 'tā jīn tiān chuān le yí jiàn bái sè de shàng yī。', example_vietnamese = 'Hôm nay anh ấy mặc một chiếc áo màu trắng.' WHERE level = 'B1' AND hanzi = '上衣' AND pinyin = 'shàngyī' AND vietnamese = 'Mặc quần áo';
UPDATE public.dictionary_words SET example_hanzi = '農夫在田裡燒稻草。', example_pinyin = 'nóng fū zài tián lǐ shāo dào cǎo。', example_vietnamese = 'Người nông dân đốt rơm rạ trên đồng.' WHERE level = 'B1' AND hanzi = '燒' AND pinyin = 'shāo' AND vietnamese = 'Đốt, thiêu';
UPDATE public.dictionary_words SET example_hanzi = '你少說一句，別再刺激他了。', example_pinyin = 'nǐ shǎo shuō yí jù， bié zài cì jī tā le。', example_vietnamese = 'Bạn nói ít lại một câu đi, đừng kích động anh ấy nữa.' WHERE level = 'B1' AND hanzi = '少' AND pinyin = 'shǎo' AND vietnamese = 'Ít, thiếu, mất';
UPDATE public.dictionary_words SET example_hanzi = '山上有很多不同種類的蛇。', example_pinyin = 'shān shàng yǒu hěn duō bù tóng zhǒng lèi de shé。', example_vietnamese = 'Trên núi có rất nhiều loài rắn khác nhau.' WHERE level = 'B1' AND hanzi = '蛇' AND pinyin = 'shé' AND vietnamese = 'Uốn khúc';
UPDATE public.dictionary_words SET example_hanzi = '這間健身房的設備非常新，也很齊全。', example_pinyin = 'zhè jiān jiàn shēn fáng de shè bèi fēi cháng xīn， yě hěn qí quán。', example_vietnamese = 'Thiết bị của phòng tập gym này rất mới và cũng rất đầy đủ.' WHERE level = 'B1' AND hanzi = '設備' AND pinyin = 'shèbèi' AND vietnamese = 'Thiết bị';
UPDATE public.dictionary_words SET example_hanzi = '這棟大樓的設計得過國際大獎。', example_pinyin = 'zhè dòng dà lóu de shè jì dé guò guó jì dà jiǎng。', example_vietnamese = 'Bản thiết kế của tòa nhà này đã từng đoạt giải thưởng quốc tế lớn.' WHERE level = 'B1' AND hanzi = '設計' AND pinyin = 'shèjì' AND vietnamese = 'Bản thiết kế';
UPDATE public.dictionary_words SET example_hanzi = '這位建築師設計了不少著名的建築物。', example_pinyin = 'zhè wèi jiàn zhù shī shè jì le bù shǎo zhù míng de jiàn zhù wù。', example_vietnamese = 'Kiến trúc sư này đã thiết kế không ít công trình nổi tiếng.' WHERE level = 'B1' AND hanzi = '設計' AND pinyin = 'shèjì' AND vietnamese = 'Thiết kế';
UPDATE public.dictionary_words SET example_hanzi = '這個湖非常深，游泳的時候要特別小心。', example_pinyin = 'zhè ge hú fēi cháng shēn， yóu yǒng de shí hou yào tè bié xiǎo xīn。', example_vietnamese = 'Cái hồ này rất sâu, khi bơi phải đặc biệt cẩn thận.' WHERE level = 'B1' AND hanzi = '深' AND pinyin = 'shēn' AND vietnamese = 'Sâu, độ sâu';
UPDATE public.dictionary_words SET example_hanzi = '這篇報導對這個議題做了非常深入的分析。', example_pinyin = 'zhè piān bào dǎo duì zhè ge yì tí zuò le fēi cháng shēn rù de fēn xī。', example_vietnamese = 'Bài báo cáo này đã phân tích rất sâu sắc về vấn đề này.' WHERE level = 'B1' AND hanzi = '深入' AND pinyin = 'shēnrù' AND vietnamese = 'Thâm nhập, đi sâu vào';
UPDATE public.dictionary_words SET example_hanzi = '不管發生什麼事，我都會陪在你身邊。', example_pinyin = 'bù guǎn fā shēng shén me shì， wǒ dōu huì péi zài nǐ shēn biān。', example_vietnamese = 'Cho dù có chuyện gì xảy ra, tôi cũng sẽ luôn ở bên cạnh bạn.' WHERE level = 'B1' AND hanzi = '身邊' AND pinyin = 'shēnbiān' AND vietnamese = 'Bên cạnh';
UPDATE public.dictionary_words SET example_hanzi = '他的身高有一百八十公分。', example_pinyin = 'tā de shēn gāo yǒu yì bǎi bā shí gōng fēn。', example_vietnamese = 'Chiều cao của anh ấy là một trăm tám mươi centimet.' WHERE level = 'B1' AND hanzi = '身高' AND pinyin = 'shēngāo' AND vietnamese = 'Chiều cao';
UPDATE public.dictionary_words SET example_hanzi = '我身上沒帶多少現金。', example_pinyin = 'wǒ shēn shàng méi dài duō shǎo xiàn jīn。', example_vietnamese = 'Trên người tôi không mang theo nhiều tiền mặt.' WHERE level = 'B1' AND hanzi = '身上' AND pinyin = 'shēnshàng' AND vietnamese = 'Trên người';
UPDATE public.dictionary_words SET example_hanzi = '他忙到甚至連吃飯的時間都沒有。', example_pinyin = 'tā máng dào shèn zhì lián chī fàn de shí jiān dōu méi yǒu。', example_vietnamese = 'Anh ấy bận đến mức thậm chí không có cả thời gian ăn cơm.' WHERE level = 'B1' AND hanzi = '甚至' AND pinyin = 'shènzhì' AND vietnamese = 'Thậm chí, đến nỗi';
UPDATE public.dictionary_words SET example_hanzi = '他工作表現優秀，很快就升為經理。', example_pinyin = 'tā gōng zuò biǎo xiàn yōu xiù， hěn kuài jiù shēng wéi jīng lǐ。', example_vietnamese = 'Anh ấy làm việc xuất sắc nên nhanh chóng được thăng chức lên quản lý.' WHERE level = 'B1' AND hanzi = '升' AND pinyin = 'shēng' AND vietnamese = 'Thăng lên, lên chức';
UPDATE public.dictionary_words SET example_hanzi = '遠處傳來幾聲狗叫。', example_pinyin = 'yuǎn chù chuán lái jǐ shēng gǒu jiào。', example_vietnamese = 'Từ xa vọng lại vài tiếng chó sủa.' WHERE level = 'B1' AND hanzi = '聲' AND pinyin = 'shēng' AND vietnamese = 'Thanh, âm thanh';
UPDATE public.dictionary_words SET example_hanzi = '中文的聲調對很多外國學生來說是最難的部分。', example_pinyin = 'zhōng wén de shēng diào duì hěn duō wài guó xué sheng lái shuō shì zuì nán de bù fen。', example_vietnamese = 'Thanh điệu tiếng Trung là phần khó nhất đối với nhiều học sinh nước ngoài.' WHERE level = 'B1' AND hanzi = '聲調' AND pinyin = 'shēngdiào' AND vietnamese = 'Thanh điệu, âm điệu';
UPDATE public.dictionary_words SET example_hanzi = '她昨天晚上在醫院生了一個女兒。', example_pinyin = 'tā zuó tiān wǎn shang zài yī yuàn shēng le yí gè nǚ ér。', example_vietnamese = 'Tối qua cô ấy đã sinh một bé gái ở bệnh viện.' WHERE level = 'B1' AND hanzi = '生' AND pinyin = 'shēng' AND vietnamese = 'Sinh đẻ, sinh trưởng';
UPDATE public.dictionary_words SET example_hanzi = '這間工廠專門生產電動汽車的零件。', example_pinyin = 'zhè jiān gōng chǎng zhuān mén shēng chǎn diàn dòng qì chē de líng jiàn。', example_vietnamese = 'Nhà máy này chuyên sản xuất linh kiện cho xe hơi điện.' WHERE level = 'B1' AND hanzi = '生產' AND pinyin = 'shēngchăn' AND vietnamese = 'sing trưởng';
UPDATE public.dictionary_words SET example_hanzi = '老師用生動的例子解釋了這個文法。', example_pinyin = 'lǎo shī yòng shēng dòng de lì zi jiě shì le zhè ge wén fǎ。', example_vietnamese = 'Thầy giáo đã dùng ví dụ sinh động để giải thích ngữ pháp này.' WHERE level = 'B1' AND hanzi = '生動' AND pinyin = 'shēngdòng' AND vietnamese = 'Sinh động, sống động';
UPDATE public.dictionary_words SET example_hanzi = '他一個人在國外生活了將近十年。', example_pinyin = 'tā yí gè rén zài guó wài shēng huó le jiāng jìn shí nián。', example_vietnamese = 'Anh ấy đã sống một mình ở nước ngoài gần mười năm.' WHERE level = 'B1' AND hanzi = '生活' AND pinyin = 'shēnghuó' AND vietnamese = 'Cuộc sống';
UPDATE public.dictionary_words SET example_hanzi = '每一個生命都值得被尊重。', example_pinyin = 'měi yí gè shēng mìng dōu zhí de bèi zūn zhòng。', example_vietnamese = 'Mỗi một sinh mệnh đều đáng được tôn trọng.' WHERE level = 'B1' AND hanzi = '生命' AND pinyin = 'shēngmìng' AND vietnamese = 'Sinh mệnh, tính mạng';
UPDATE public.dictionary_words SET example_hanzi = '這家餐廳的生意一直很好。', example_pinyin = 'zhè jiā cān tīng de shēng yì yì zhí hěn hǎo。', example_vietnamese = 'Việc buôn bán của quán ăn này luôn rất tốt.' WHERE level = 'B1' AND hanzi = '生意' AND pinyin = 'shēngyì' AND vietnamese = 'Buôn bán, làm ăn';
UPDATE public.dictionary_words SET example_hanzi = '這一課有不少生字需要背。', example_pinyin = 'zhè yí kè yǒu bù shǎo shēng zì xū yào bèi。', example_vietnamese = 'Bài học này có không ít từ mới cần phải học thuộc.' WHERE level = 'B1' AND hanzi = '生字' AND pinyin = 'shēngzì' AND vietnamese = 'Từ mới';
UPDATE public.dictionary_words SET example_hanzi = '犯了錯以後，他開始省思自己的行為。', example_pinyin = 'fàn le cuò yǐ hòu， tā kāi shǐ shěng sī zì jǐ de xíng wéi。', example_vietnamese = 'Sau khi phạm lỗi, anh ấy bắt đầu tự kiểm điểm hành vi của mình.' WHERE level = 'B1' AND hanzi = '省' AND pinyin = 'shěng' AND vietnamese = 'Tự kiểm điểm bản thân';
UPDATE public.dictionary_words SET example_hanzi = '為了省錢，她決定自己帶便當上班。', example_pinyin = 'wèi le shěng qián， tā jué dìng zì jǐ dài biàn dāng shàng bān。', example_vietnamese = 'Để tiết kiệm tiền, cô ấy quyết định tự mang cơm hộp đi làm.' WHERE level = 'B1' AND hanzi = '省錢' AND pinyin = 'shěngqián' AND vietnamese = 'Tiết kiệm tiền';
UPDATE public.dictionary_words SET example_hanzi = '冰箱裡只剩三顆雞蛋了。', example_pinyin = 'bīng xiāng lǐ zhǐ shèng sān kē jī dàn le。', example_vietnamese = 'Trong tủ lạnh chỉ còn lại ba quả trứng.' WHERE level = 'B1' AND hanzi = '剩' AND pinyin = 'shèng' AND vietnamese = 'Thừa lại, còn lại';
UPDATE public.dictionary_words SET example_hanzi = '蛋糕被大家吃完了，只剩下一小塊。', example_pinyin = 'dàn gāo bèi dà jiā chī wán le， zhǐ shèng xia yì xiǎo kuài。', example_vietnamese = 'Bánh kem bị mọi người ăn hết rồi, chỉ còn lại một miếng nhỏ.' WHERE level = 'B1' AND hanzi = '剩下' AND pinyin = 'shèngxia' AND vietnamese = 'Thừa, còn lại';
UPDATE public.dictionary_words SET example_hanzi = '外面下雨了，我的鞋子全濕了。', example_pinyin = 'wài mian xià yǔ le， wǒ de xié zi quán shī le。', example_vietnamese = 'Bên ngoài trời mưa, giày của tôi ướt hết cả rồi.' WHERE level = 'B1' AND hanzi = '濕' AND pinyin = 'shī' AND vietnamese = 'ẩm';
UPDATE public.dictionary_words SET example_hanzi = '他失戀以後，整整一個星期都沒什麼精神。', example_pinyin = 'tā shī liàn yǐ hòu， zhěng zhěng yí gè xīng qī dōu méi shén me jīng shen。', example_vietnamese = 'Sau khi thất tình, cả tuần liền anh ấy không còn tinh thần gì cả.' WHERE level = 'B1' AND hanzi = '失戀' AND pinyin = 'shīliàn' AND vietnamese = 'Thất tình';
UPDATE public.dictionary_words SET example_hanzi = '這場意外讓他永遠失去了左腿。', example_pinyin = 'zhè chǎng yì wài ràng tā yǒng yuǎn shī qù le zuǒ tuǐ。', example_vietnamese = 'Vụ tai nạn này khiến anh ấy vĩnh viễn mất đi chân trái.' WHERE level = 'B1' AND hanzi = '失去' AND pinyin = 'shīqù' AND vietnamese = 'Mất';
UPDATE public.dictionary_words SET example_hanzi = '動物園裡的獅子正在悠閒地睡午覺。', example_pinyin = 'dòng wù yuán lǐ de shī zi zhèng zài yōu xián de shuì wǔ jiào。', example_vietnamese = 'Con sư tử trong sở thú đang ngủ trưa thư thái.' WHERE level = 'B1' AND hanzi = '獅子' AND pinyin = 'shīzi' AND vietnamese = 'Sư tử';
UPDATE public.dictionary_words SET example_hanzi = '這次比賽的結果十分令人滿意。', example_pinyin = 'zhè cì bǐ sài de jié guǒ shí fēn lìng rén mǎn yì。', example_vietnamese = 'Kết quả cuộc thi lần này vô cùng khiến người ta hài lòng.' WHERE level = 'B1' AND hanzi = '十分' AND pinyin = 'shífēn' AND vietnamese = 'Rất, hết sức, vô cùng';
UPDATE public.dictionary_words SET example_hanzi = '小男孩撿起一顆石頭丟進河裡。', example_pinyin = 'xiǎo nán hái jiǎn qǐ yì kē shí tou diū jìn hé lǐ。', example_vietnamese = 'Cậu bé nhặt một viên đá rồi ném xuống sông.' WHERE level = 'B1' AND hanzi = '石頭' AND pinyin = 'shítou' AND vietnamese = 'Đá';
UPDATE public.dictionary_words SET example_hanzi = '這個國家的經濟主要依靠石油出口。', example_pinyin = 'zhè ge guó jiā de jīng jì zhǔ yào yī kào shí yóu chū kǒu。', example_vietnamese = 'Kinh tế của quốc gia này chủ yếu dựa vào xuất khẩu dầu mỏ.' WHERE level = 'B1' AND hanzi = '石油' AND pinyin = 'shíyóu' AND vietnamese = 'Dầu mỏ, dầu thô';
UPDATE public.dictionary_words SET example_hanzi = '考試時，請把手機關機。', example_pinyin = 'kǎo shì shí， qǐng bǎ shǒu jī guān jī。', example_vietnamese = 'Khi thi, xin vui lòng tắt điện thoại di động.' WHERE level = 'B1' AND hanzi = '時' AND pinyin = 'shí' AND vietnamese = 'Thời gian';
UPDATE public.dictionary_words SET example_hanzi = '現在已經是網路時代了。', example_pinyin = 'xiàn zài yǐ jīng shì wǎng lù shí dài le。', example_vietnamese = 'Hiện nay đã là thời đại internet rồi.' WHERE level = 'B1' AND hanzi = '時代' AND pinyin = 'shídài' AND vietnamese = 'Thời đại';
UPDATE public.dictionary_words SET example_hanzi = '那是我人生中最難忘的時刻。', example_pinyin = 'nà shì wǒ rén shēng zhōng zuì nán wàng de shí kè。', example_vietnamese = 'Đó là thời khắc khó quên nhất trong cuộc đời tôi.' WHERE level = 'B1' AND hanzi = '時刻' AND pinyin = 'shíkè' AND vietnamese = 'Thời khắc';
UPDATE public.dictionary_words SET example_hanzi = '說實話，我一開始並不喜歡這份工作。', example_pinyin = 'shuō shí huà， wǒ yì kāi shǐ bìng bù xǐ huan zhè fèn gōng zuò。', example_vietnamese = 'Nói thật, ban đầu tôi không thích công việc này.' WHERE level = 'B1' AND hanzi = '實話' AND pinyin = 'shíhuà' AND vietnamese = 'Lời nói thật';
UPDATE public.dictionary_words SET example_hanzi = '這個計畫聽起來很好，但不太實際。', example_pinyin = 'zhè ge jì huà tīng qǐ lái hěn hǎo， dàn bú tài shí jì。', example_vietnamese = 'Kế hoạch này nghe có vẻ hay, nhưng không thực tế lắm.' WHERE level = 'B1' AND hanzi = '實際' AND pinyin = 'shíjì' AND vietnamese = 'Thực tế';
UPDATE public.dictionary_words SET example_hanzi = '這支球隊的實力比去年強很多。', example_pinyin = 'zhè zhī qiú duì de shí lì bǐ qù nián qiáng hěn duō。', example_vietnamese = 'Thực lực của đội bóng này mạnh hơn nhiều so với năm ngoái.' WHERE level = 'B1' AND hanzi = '實力' AND pinyin = 'shílì' AND vietnamese = 'Thực lực, sức mạnh';
UPDATE public.dictionary_words SET example_hanzi = '這項新政策將從下個月開始實行。', example_pinyin = 'zhè xiàng xīn zhèng cè jiāng cóng xià ge yuè kāi shǐ shí xíng。', example_vietnamese = 'Chính sách mới này sẽ bắt đầu được thi hành từ tháng sau.' WHERE level = 'B1' AND hanzi = '實行' AND pinyin = 'shíxíng' AND vietnamese = 'thực hành';
UPDATE public.dictionary_words SET example_hanzi = '這道菜實在太好吃了。', example_pinyin = 'zhè dào cài shí zài tài hǎo chī le。', example_vietnamese = 'Món ăn này thực sự quá ngon.' WHERE level = 'B1' AND hanzi = '實在' AND pinyin = 'shízài' AND vietnamese = 'Chắc chắn, cẩn thận';
UPDATE public.dictionary_words SET example_hanzi = '這次的失敗使得他更加努力練習。', example_pinyin = 'zhè cì de shī bài shǐ de tā gèng jiā nǔ lì liàn xí。', example_vietnamese = 'Thất bại lần này khiến anh ấy càng thêm nỗ lực luyện tập.' WHERE level = 'B1' AND hanzi = '使得' AND pinyin = 'shĭde' AND vietnamese = 'Làm cho, khiến cho';
UPDATE public.dictionary_words SET example_hanzi = '上課的時候請不要使用手機。', example_pinyin = 'shàng kè de shí hou qǐng bú yào shǐ yòng shǒu jī。', example_vietnamese = 'Trong giờ học xin đừng sử dụng điện thoại di động.' WHERE level = 'B1' AND hanzi = '使用' AND pinyin = 'shĭyòng' AND vietnamese = 'Sử dụng, dùng';
UPDATE public.dictionary_words SET example_hanzi = '不管你信不信，這就是事實。', example_pinyin = 'bù guǎn nǐ xìn bú xìn， zhè jiù shì shì shí。', example_vietnamese = 'Dù bạn có tin hay không, đây chính là sự thật.' WHERE level = 'B1' AND hanzi = '事實' AND pinyin = 'shìshí' AND vietnamese = 'Sự thật';
UPDATE public.dictionary_words SET example_hanzi = '他放棄了穩定的工作，去追求自己的事業。', example_pinyin = 'tā fàng qì le wěn dìng de gōng zuò， qù zhuī qiú zì jǐ de shì yè。', example_vietnamese = 'Anh ấy từ bỏ công việc ổn định để theo đuổi sự nghiệp của riêng mình.' WHERE level = 'B1' AND hanzi = '事業' AND pinyin = 'shìyè' AND vietnamese = 'Sự nghiệp';
UPDATE public.dictionary_words SET example_hanzi = '剛到國外的時候，他花了很長時間才適應那裡的生活。', example_pinyin = 'gāng dào guó wài de shí hou， tā huā le hěn cháng shí jiān cái shì yìng nà lǐ de shēng huó。', example_vietnamese = 'Khi mới đến nước ngoài, anh ấy đã mất rất nhiều thời gian mới thích nghi được với cuộc sống ở đó.' WHERE level = 'B1' AND hanzi = '適應' AND pinyin = 'shìyìng' AND vietnamese = 'Thích ứng';
UPDATE public.dictionary_words SET example_hanzi = '市長昨天出席了這場開幕典禮。', example_pinyin = 'shì zhǎng zuó tiān chū xí le zhè chǎng kāi mù diǎn lǐ。', example_vietnamese = 'Thị trưởng đã tham dự lễ khai mạc này vào hôm qua.' WHERE level = 'B1' AND hanzi = '市長' AND pinyin = 'shìzhăng' AND vietnamese = 'Thị trưởng';
UPDATE public.dictionary_words SET example_hanzi = '這趟旅行讓我有很多意外的收穫。', example_pinyin = 'zhè tàng lǚ xíng ràng wǒ yǒu hěn duō yì wài de shōu huò。', example_vietnamese = 'Chuyến du lịch này mang lại cho tôi rất nhiều thu hoạch bất ngờ.' WHERE level = 'B1' AND hanzi = '收穫' AND pinyin = 'shōuhuò' AND vietnamese = 'Gặt hái, thu hoạch';
UPDATE public.dictionary_words SET example_hanzi = '爺爺每天早上都會打開收音機聽新聞。', example_pinyin = 'yé ye měi tiān zǎo shang dōu huì dǎ kāi shōu yīn jī tīng xīn wén。', example_vietnamese = 'Sáng nào ông nội cũng mở đài radio để nghe tin tức.' WHERE level = 'B1' AND hanzi = '收音機' AND pinyin = 'shōuyīnjī' AND vietnamese = 'Máy thu thanh';
UPDATE public.dictionary_words SET example_hanzi = '他對這一帶的路很熟。', example_pinyin = 'tā duì zhè yí dài de lù hěn shú。', example_vietnamese = 'Anh ấy rất quen thuộc với đường xá ở khu vực này.' WHERE level = 'B1' AND hanzi = '熟' AND pinyin = 'shóu / shú' AND vietnamese = 'Quen thuộc, thành thạo';
UPDATE public.dictionary_words SET example_hanzi = '哎呀，我把鑰匙忘在家裡了！', example_pinyin = 'āi yā， wǒ bǎ yào shi wàng zài jiā lǐ le！', example_vietnamese = 'Ôi trời, tôi quên chìa khóa ở nhà rồi!' WHERE level = 'B2' AND hanzi = '哎喲' AND pinyin = 'āiyāo' AND vietnamese = 'chao ôi';
UPDATE public.dictionary_words SET example_hanzi = '哎喲，這個包裹好重啊！', example_pinyin = 'āi yō， zhè gè bāo guǒ hǎo zhòng a！', example_vietnamese = 'Chao ôi, cái kiện hàng này nặng quá!' WHERE level = 'B2' AND hanzi = '哎喲' AND pinyin = 'āiyāo' AND vietnamese = 'chao ôi';
UPDATE public.dictionary_words SET example_hanzi = '每個人都應該培養一些自己的愛好。', example_pinyin = 'měi gè rén dōu yīng gāi péi yǎng yì xiē zì jǐ de ài hào。', example_vietnamese = 'Mỗi người đều nên bồi dưỡng cho mình một vài sở thích riêng.' WHERE level = 'B2' AND hanzi = '愛好' AND pinyin = 'àihào' AND vietnamese = 'sở thích';
UPDATE public.dictionary_words SET example_hanzi = '他從小就愛好音樂，長大後成了鋼琴家。', example_pinyin = 'tā cóng xiǎo jiù ài hào yīn yuè， zhǎng dà hòu chéng le gāng qín jiā。', example_vietnamese = 'Anh ấy từ nhỏ đã yêu thích âm nhạc, lớn lên trở thành nghệ sĩ dương cầm.' WHERE level = 'B2' AND hanzi = '愛好' AND pinyin = 'àihào' AND vietnamese = 'thích, yêu thích';
UPDATE public.dictionary_words SET example_hanzi = '我們應該愛護公共設施，不要隨便破壞。', example_pinyin = 'wǒ men yīng gāi ài hù gōng gòng shè shī， bú yào suí biàn pò huài。', example_vietnamese = 'Chúng ta nên giữ gìn các công trình công cộng, đừng tùy tiện phá hoại.' WHERE level = 'B2' AND hanzi = '愛護' AND pinyin = 'àihù' AND vietnamese = 'bảo vệ, giữ gìn';
UPDATE public.dictionary_words SET example_hanzi = '他常常在朋友面前誇獎自己的愛人。', example_pinyin = 'tā cháng cháng zài péng yǒu miàn qián kuā jiǎng zì jǐ de ài rén。', example_vietnamese = 'Anh ấy thường khen ngợi vợ mình trước mặt bạn bè.' WHERE level = 'B2' AND hanzi = '愛人' AND pinyin = 'àirén' AND vietnamese = 'vợ, chồng, người yêu';
UPDATE public.dictionary_words SET example_hanzi = '看到她哭了，朋友們都過來安慰她。', example_pinyin = 'kàn dào tā kū le， péng yǒu men dōu guò lái ān wèi tā。', example_vietnamese = 'Thấy cô ấy khóc, bạn bè đều đến an ủi cô ấy.' WHERE level = 'B2' AND hanzi = '安慰' AND pinyin = 'ānwèi' AND vietnamese = 'an ủi';
UPDATE public.dictionary_words SET example_hanzi = '師傅花了一個下午才把冷氣安裝好。', example_pinyin = 'shī fù huā le yí gè xià wǔ cái bǎ lěng qì ān zhuāng hǎo。', example_vietnamese = 'Người thợ mất cả buổi chiều mới lắp xong máy lạnh.' WHERE level = 'B2' AND hanzi = '安裝' AND pinyin = 'ānzhuāng' AND vietnamese = 'lắp đặt, lắp ráp';
UPDATE public.dictionary_words SET example_hanzi = '請按這個紅色按鈕就可以開機了。', example_pinyin = 'qǐng àn zhè gè hóng sè àn niǔ jiù kě yǐ kāi jī le。', example_vietnamese = 'Xin hãy nhấn nút màu đỏ này là có thể khởi động máy.' WHERE level = 'B2' AND hanzi = '按' AND pinyin = 'àn' AND vietnamese = 'nhấn, bấm, đè';
UPDATE public.dictionary_words SET example_hanzi = '不管多忙，他每天都按時吃藥。', example_pinyin = 'bù guǎn duō máng， tā měi tiān dōu àn shí chī yào。', example_vietnamese = 'Dù bận đến mấy, ngày nào anh ấy cũng uống thuốc đúng giờ.' WHERE level = 'B2' AND hanzi = '按時' AND pinyin = 'ànshí' AND vietnamese = 'đúng hạn';
UPDATE public.dictionary_words SET example_hanzi = '房間裡的燈壞了，變得很暗。', example_pinyin = 'fáng jiān lǐ de dēng huài le， biàn de hěn àn。', example_vietnamese = 'Đèn trong phòng bị hỏng, trở nên rất tối.' WHERE level = 'B2' AND hanzi = '暗' AND pinyin = 'àn' AND vietnamese = 'tối, tối tăm';
UPDATE public.dictionary_words SET example_hanzi = '他一直暗中觀察那個陌生人的一舉一動。', example_pinyin = 'tā yì zhí àn zhōng guān chá nà gè mò shēng rén de yì jǔ yí dòng。', example_vietnamese = 'Anh ấy vẫn luôn âm thầm quan sát mọi cử chỉ của người lạ đó.' WHERE level = 'B2' AND hanzi = '暗中' AND pinyin = 'ànzhōng' AND vietnamese = 'trong bóng tối';
UPDATE public.dictionary_words SET example_hanzi = '這條巷子的地上到處都是骯髒的垃圾。', example_pinyin = 'zhè tiáo xiàng zi de dì shàng dào chǔ dōu shì āng zāng de lā jī。', example_vietnamese = 'Mặt đất trong con hẻm này khắp nơi đều là rác bẩn.' WHERE level = 'B2' AND hanzi = '骯髒' AND pinyin = 'āngzhāng' AND vietnamese = 'dơ bẩn';
UPDATE public.dictionary_words SET example_hanzi = '奶奶每天早上都會熬一鍋粥給我們吃。', example_pinyin = 'nǎi nai měi tiān zǎo shàng dōu huì áo yì guō zhōu gěi wǒ men chī。', example_vietnamese = 'Mỗi sáng bà đều nấu một nồi cháo cho chúng tôi ăn.' WHERE level = 'B2' AND hanzi = '熬' AND pinyin = 'áo' AND vietnamese = 'luộc, nấu, sắc (thuốc)';
UPDATE public.dictionary_words SET example_hanzi = '醫生小心地幫他拔掉那顆蛀牙。', example_pinyin = 'yī shēng xiǎo xīn de bāng tā bá diào nà kē zhù yá。', example_vietnamese = 'Bác sĩ cẩn thận nhổ giúp anh ấy chiếc răng sâu đó.' WHERE level = 'B2' AND hanzi = '拔' AND pinyin = 'bá' AND vietnamese = 'nhổ, rút';
UPDATE public.dictionary_words SET example_hanzi = '桌上放著一把剪刀和一把尺。', example_pinyin = 'zhuō shàng fàng zhe yì bǎ jiǎn dāo hé yì bǎ chǐ。', example_vietnamese = 'Trên bàn để một cái kéo và một cây thước.' WHERE level = 'B2' AND hanzi = '把' AND pinyin = 'bă' AND vietnamese = 'cán, quai, tay cầm';
UPDATE public.dictionary_words SET example_hanzi = '這次考試他很有把握，一定能考好。', example_pinyin = 'zhè cì kǎo shì tā hěn yǒu bǎ wò， yí dìng néng kǎo hǎo。', example_vietnamese = 'Kỳ thi này anh ấy rất tự tin, chắc chắn sẽ làm tốt.' WHERE level = 'B2' AND hanzi = '把握' AND pinyin = 'băwò' AND vietnamese = 'cầm, nắm, nắm bắt';
UPDATE public.dictionary_words SET example_hanzi = '因為工資太低，工人們決定罷工抗議。', example_pinyin = 'yīn wèi gōng zī tài dī， gōng rén men jué dìng bà gōng kàng yì。', example_vietnamese = 'Vì lương quá thấp, công nhân quyết định đình công phản đối.' WHERE level = 'B2' AND hanzi = '罷工' AND pinyin = 'bàgōng' AND vietnamese = 'bãi công, đình công';
UPDATE public.dictionary_words SET example_hanzi = '我沒有生氣，只是有點累罷了。', example_pinyin = 'wǒ méi yǒu shēng qì， zhǐ shì yǒu diǎn lèi bà le。', example_vietnamese = 'Tôi không giận đâu, chỉ là hơi mệt thôi.' WHERE level = 'B2' AND hanzi = '罷了' AND pinyin = 'bàle' AND vietnamese = 'mà thôi, thôi';
UPDATE public.dictionary_words SET example_hanzi = '他花了好幾年才擺脫債務的困擾。', example_pinyin = 'tā huā le hǎo jǐ nián cái bǎi tuō zhài wù de kùn rǎo。', example_vietnamese = 'Anh ấy mất mấy năm mới thoát khỏi cảnh nợ nần.' WHERE level = 'B2' AND hanzi = '擺脫' AND pinyin = 'băituō' AND vietnamese = 'thoát khỏi';
UPDATE public.dictionary_words SET example_hanzi = '這場比賽我們隊以一分之差敗給對手。', example_pinyin = 'zhè chǎng bǐ sài wǒ men duì yǐ yì fēn zhī chā bài gěi duì shǒu。', example_vietnamese = 'Trận đấu này đội chúng tôi thua đối thủ với cách biệt một điểm.' WHERE level = 'B2' AND hanzi = '敗' AND pinyin = 'bài' AND vietnamese = 'thua, bại trận';
UPDATE public.dictionary_words SET example_hanzi = '每逢初一，媽媽都會準備水果去廟裡拜神。', example_pinyin = 'měi féng chū yī， mā ma dōu huì zhǔn bèi shuǐ guǒ qù miào lǐ bài shén。', example_vietnamese = 'Cứ đến mùng một, mẹ đều chuẩn bị trái cây đến chùa lạy thần.' WHERE level = 'B2' AND hanzi = '拜' AND pinyin = 'bài' AND vietnamese = 'lạy, vái';
UPDATE public.dictionary_words SET example_hanzi = '朋友們互相說了聲拜拜，就各自回家了。', example_pinyin = 'péng yǒu men hù xiāng shuō le shēng bài bai， jiù gè zì huí jiā le。', example_vietnamese = 'Các bạn chào tạm biệt nhau rồi mỗi người về nhà.' WHERE level = 'B2' AND hanzi = '拜拜' AND pinyin = 'bàibai' AND vietnamese = 'cúi chào';
UPDATE public.dictionary_words SET example_hanzi = '明天我打算去拜訪一位多年不見的老師。', example_pinyin = 'míng tiān wǒ dǎ suàn qù bài fǎng yí wèi duō nián bú jiàn de lǎo shī。', example_vietnamese = 'Ngày mai tôi định đi thăm một người thầy đã nhiều năm không gặp.' WHERE level = 'B2' AND hanzi = '拜訪' AND pinyin = 'bàifăng' AND vietnamese = 'thăm viếng, thăm hỏi';
UPDATE public.dictionary_words SET example_hanzi = '大年初一，全家人一起去外婆家拜年。', example_pinyin = 'dà nián chū yī， quán jiā rén yì qǐ qù wài pó jia bài nián。', example_vietnamese = 'Mùng một Tết, cả nhà cùng đến nhà bà ngoại chúc Tết.' WHERE level = 'B2' AND hanzi = '拜年' AND pinyin = 'bàinián' AND vietnamese = 'đi chúc tết';
UPDATE public.dictionary_words SET example_hanzi = '拜託你幫我把這份文件送到辦公室。', example_pinyin = 'bài tuō nǐ bāng wǒ bǎ zhè fèn wén jiàn sòng dào bàn gōng shì。', example_vietnamese = 'Nhờ bạn giúp tôi mang tài liệu này đến văn phòng.' WHERE level = 'B2' AND hanzi = '拜託' AND pinyin = 'bàituō' AND vietnamese = 'nhờ vả';
UPDATE public.dictionary_words SET example_hanzi = '事情怎麼會弄成這般模樣？', example_pinyin = 'shì qíng zěn me huì nòng chéng zhè bān mú yàng？', example_vietnamese = 'Sao chuyện lại biến thành ra nông nỗi này?' WHERE level = 'B2' AND hanzi = '般' AND pinyin = 'bān' AND vietnamese = 'loại, kiểu, cách, hạng';
UPDATE public.dictionary_words SET example_hanzi = '他今天上晚班，要到十點才下班。', example_pinyin = 'tā jīn tiān shàng wǎn bān， yào dào shí diǎn cái xià bān。', example_vietnamese = 'Hôm nay anh ấy làm ca tối, phải đến mười giờ mới tan làm.' WHERE level = 'B2' AND hanzi = '班' AND pinyin = 'bān' AND vietnamese = 'lớp, ca, buổi làm';
UPDATE public.dictionary_words SET example_hanzi = '老師選她當班長，因為她做事很負責。', example_pinyin = 'lǎo shī xuǎn tā dāng bān zhǎng， yīn wèi tā zuò shì hěn fù zé。', example_vietnamese = 'Cô giáo chọn bạn ấy làm lớp trưởng vì bạn ấy làm việc rất có trách nhiệm.' WHERE level = 'B2' AND hanzi = '班長' AND pinyin = 'bānzhăng' AND vietnamese = 'lớp trưởng';
UPDATE public.dictionary_words SET example_hanzi = '工人正忙著把貨物搬運到卡車上。', example_pinyin = 'gōng rén zhèng máng zhe bǎ huò wù bān yùn dào kǎ chē shàng。', example_vietnamese = 'Công nhân đang bận vận chuyển hàng hóa lên xe tải.' WHERE level = 'B2' AND hanzi = '搬運' AND pinyin = 'bānyùn' AND vietnamese = 'vận chuyển, vận tải';
UPDATE public.dictionary_words SET example_hanzi = '媽媽用醬油和麻油把青菜拌一拌。', example_pinyin = 'mā ma yòng jiàng yóu hé má yóu bǎ qīng cài bàn yi bàn。', example_vietnamese = 'Mẹ dùng xì dầu và dầu mè trộn đều rau xanh.' WHERE level = 'B2' AND hanzi = '拌' AND pinyin = 'bàn' AND vietnamese = 'trộn, trộn lẫn';
UPDATE public.dictionary_words SET example_hanzi = '我們走到半路才發現忘了帶雨傘。', example_pinyin = 'wǒ men zǒu dào bàn lù cái fā xiàn wàng le dài yǔ sǎn。', example_vietnamese = 'Chúng tôi đi đến giữa đường mới phát hiện quên mang ô.' WHERE level = 'B2' AND hanzi = '半路' AND pinyin = 'bànlù' AND vietnamese = 'nửa đường, giữa đường';
UPDATE public.dictionary_words SET example_hanzi = '這次投票，半數以上的人都同意這個提案。', example_pinyin = 'zhè cì tóu piào， bàn shù yǐ shàng de rén dōu tóng yì zhè gè tí àn。', example_vietnamese = 'Cuộc bỏ phiếu lần này, hơn một nửa số người đều đồng ý với đề án này.' WHERE level = 'B2' AND hanzi = '半數' AND pinyin = 'bànshù' AND vietnamese = 'một nửa';
UPDATE public.dictionary_words SET example_hanzi = '這棟大樓的十樓是我們公司辦公的地方。', example_pinyin = 'zhè dòng dà lóu de shí lóu shì wǒ men gōng sī bàn gōng de dì fang。', example_vietnamese = 'Tầng mười của tòa nhà này là nơi công ty chúng tôi làm việc.' WHERE level = 'B2' AND hanzi = '辦公' AND pinyin = 'bàngōng' AND vietnamese = 'làm việc';
UPDATE public.dictionary_words SET example_hanzi = '他做事很認真，大家都放心讓他辦事。', example_pinyin = 'tā zuò shì hěn rèn zhēn， dà jiā dōu fàng xīn ràng tā bàn shì。', example_vietnamese = 'Anh ấy làm việc rất nghiêm túc, mọi người đều yên tâm giao việc cho anh ấy xử lý.' WHERE level = 'B2' AND hanzi = '辦事' AND pinyin = 'bànshì' AND vietnamese = 'làm việc';
UPDATE public.dictionary_words SET example_hanzi = '她在這部電影裡扮演一位堅強的母親。', example_pinyin = 'tā zài zhè bù diàn yǐng lǐ bàn yǎn yí wèi jiān qiáng de mǔ qīn。', example_vietnamese = 'Cô ấy đóng vai một người mẹ kiên cường trong bộ phim này.' WHERE level = 'B2' AND hanzi = '扮演' AND pinyin = 'bànyăn' AND vietnamese = 'đóng vai, sắm vai';
UPDATE public.dictionary_words SET example_hanzi = '我們約好傍晚在公園門口見面。', example_pinyin = 'wǒ men yuē hǎo bàng wǎn zài gōng yuán mén kǒu jiàn miàn。', example_vietnamese = 'Chúng tôi hẹn gặp nhau lúc chập tối ở cổng công viên.' WHERE level = 'B2' AND hanzi = '傍晚' AND pinyin = 'bāngwăn' AND vietnamese = 'chạng vạng, chập tối';
UPDATE public.dictionary_words SET example_hanzi = '這袋麵粉重五磅。', example_pinyin = 'zhè dài miàn fěn zhòng wǔ bàng。', example_vietnamese = 'Túi bột mì này nặng năm pound.' WHERE level = 'B2' AND hanzi = '磅' AND pinyin = 'bàng' AND vietnamese = 'pound (đơn vị cân nặng)';
UPDATE public.dictionary_words SET example_hanzi = '老師拿著一根長棒指著地圖。', example_pinyin = 'lǎo shī ná zhe yì gēn cháng bàng zhǐ zhe dì tú。', example_vietnamese = 'Thầy giáo cầm một cây gậy dài chỉ vào bản đồ.' WHERE level = 'B2' AND hanzi = '棒' AND pinyin = 'bàng' AND vietnamese = 'gậy, thỏi';
UPDATE public.dictionary_words SET example_hanzi = '他撿起地上的棒子趕走了野狗。', example_pinyin = 'tā jiǎn qǐ dì shàng de bàng zi gǎn zǒu le yě gǒu。', example_vietnamese = 'Anh ấy nhặt cây gậy dưới đất lên đuổi con chó hoang đi.' WHERE level = 'B2' AND hanzi = '棒子' AND pinyin = 'bàngzi' AND vietnamese = 'cây gậy';
UPDATE public.dictionary_words SET example_hanzi = '郵差今天送來一個很大的包裹。', example_pinyin = 'yóu chāi jīn tiān sòng lái yí gè hěn dà de bāo guǒ。', example_vietnamese = 'Hôm nay người đưa thư mang đến một kiện hàng rất lớn.' WHERE level = 'B2' AND hanzi = '包裹' AND pinyin = 'bāoguǒ' AND vietnamese = 'gói, kiện hàng';
UPDATE public.dictionary_words SET example_hanzi = '這個價錢包括早餐和晚餐。', example_pinyin = 'zhè gè jià qián bāo kuò zǎo cān hé wǎn cān。', example_vietnamese = 'Giá này bao gồm cả bữa sáng và bữa tối.' WHERE level = 'B2' AND hanzi = '包括' AND pinyin = 'bāokuò' AND vietnamese = 'bao gồm';
UPDATE public.dictionary_words SET example_hanzi = '這款產品的包裝設計得很精美。', example_pinyin = 'zhè kuǎn chǎn pǐn de bāo zhuāng shè jì de hěn jīng měi。', example_vietnamese = 'Bao bì của sản phẩm này được thiết kế rất tinh xảo.' WHERE level = 'B2' AND hanzi = '包裝' AND pinyin = 'bāozhuāng' AND vietnamese = 'bao bì';
UPDATE public.dictionary_words SET example_hanzi = '店員細心地把禮物包裝好。', example_pinyin = 'diàn yuán xì xīn de bǎ lǐ wù bāo zhuāng hǎo。', example_vietnamese = 'Nhân viên bán hàng đóng gói món quà rất cẩn thận.' WHERE level = 'B2' AND hanzi = '包裝' AND pinyin = 'bāozhuāng' AND vietnamese = 'đóng gói';
UPDATE public.dictionary_words SET example_hanzi = '這種天氣，能不能準時到達都很難保。', example_pinyin = 'zhè zhǒng tiān qì， néng bu néng zhǔn shí dào dá dōu hěn nán bǎo。', example_vietnamese = 'Thời tiết thế này, có đến đúng giờ được hay không cũng khó mà đảm bảo.' WHERE level = 'B2' AND hanzi = '保' AND pinyin = 'băo' AND vietnamese = 'giữ, gìn giữ';
UPDATE public.dictionary_words SET example_hanzi = '每天運動可以幫助你保持身材。', example_pinyin = 'měi tiān yùn dòng kě yǐ bāng zhù nǐ bǎo chí shēn cái。', example_vietnamese = 'Tập thể dục mỗi ngày có thể giúp bạn duy trì vóc dáng.' WHERE level = 'B2' AND hanzi = '保持' AND pinyin = 'băochí' AND vietnamese = 'duy trì, giữ nguyên';
UPDATE public.dictionary_words SET example_hanzi = '這些珍貴的照片都被完整地保存下來了。', example_pinyin = 'zhè xiē zhēn guì de zhào piàn dōu bèi wán zhěng de bǎo cún xià lái le。', example_vietnamese = 'Những bức ảnh quý giá này đều được bảo tồn nguyên vẹn.' WHERE level = 'B2' AND hanzi = '保存' AND pinyin = 'băocún' AND vietnamese = 'bảo tồn';
UPDATE public.dictionary_words SET example_hanzi = '對於這個決定，他保留了自己的意見。', example_pinyin = 'duì yú zhè gè jué dìng， tā bǎo liú le zì jǐ de yì jiàn。', example_vietnamese = 'Đối với quyết định này, anh ấy vẫn bảo lưu ý kiến riêng của mình.' WHERE level = 'B2' AND hanzi = '保留' AND pinyin = 'băoliú' AND vietnamese = 'bảo lưu, giữ nguyên';
UPDATE public.dictionary_words SET example_hanzi = '士兵們用生命保衛自己的國家。', example_pinyin = 'shì bīng men yòng shēng mìng bǎo wèi zì jǐ de guó jiā。', example_vietnamese = 'Các chiến sĩ dùng cả tính mạng để bảo vệ đất nước mình.' WHERE level = 'B2' AND hanzi = '保衛' AND pinyin = 'băowèi' AND vietnamese = 'bảo vệ, che chở';
UPDATE public.dictionary_words SET example_hanzi = '穩定的收入是生活的重要保障。', example_pinyin = 'wěn dìng de shōu rù shì shēng huó de zhòng yào bǎo zhàng。', example_vietnamese = 'Thu nhập ổn định là sự bảo đảm quan trọng cho cuộc sống.' WHERE level = 'B2' AND hanzi = '保障' AND pinyin = 'băozhàng' AND vietnamese = 'vật bảo đảm, đồ bảo hộ';
UPDATE public.dictionary_words SET example_hanzi = '法律保障每個人的基本人權。', example_pinyin = 'fǎ lǜ bǎo zhàng měi gè rén de jī běn rén quán。', example_vietnamese = 'Pháp luật bảo đảm quyền con người cơ bản của mỗi người.' WHERE level = 'B2' AND hanzi = '保障' AND pinyin = 'băozhàng' AND vietnamese = 'bảo đảm, bảo hộ';
UPDATE public.dictionary_words SET example_hanzi = '她一邊哄寶寶睡覺，一邊輕輕唱歌。', example_pinyin = 'tā yì biān hǒng bǎo bǎo shuì jiào， yì biān qīng qīng chàng gē。', example_vietnamese = 'Chị ấy vừa dỗ bé ngủ vừa khe khẽ hát.' WHERE level = 'B2' AND hanzi = '寶寶' AND pinyin = 'băobao' AND vietnamese = 'cục cưng, bé cưng';
UPDATE public.dictionary_words SET example_hanzi = '媽媽輕輕地把嬰兒抱在懷裡。', example_pinyin = 'mā ma qīng qīng de bǎ yīng ér bào zài huái lǐ。', example_vietnamese = 'Người mẹ nhẹ nhàng ôm đứa bé vào lòng.' WHERE level = 'B2' AND hanzi = '抱' AND pinyin = 'bào' AND vietnamese = 'bế, bồng, ôm';
UPDATE public.dictionary_words SET example_hanzi = '有情況要立刻報給主管知道。', example_pinyin = 'yǒu qíng kuàng yào lì kè bào gěi zhǔ guǎn zhī dào。', example_vietnamese = 'Có tình huống gì phải báo ngay cho quản lý biết.' WHERE level = 'B2' AND hanzi = '報' AND pinyin = 'bào' AND vietnamese = 'báo cho biết';
UPDATE public.dictionary_words SET example_hanzi = '他發誓有一天要為父親報仇。', example_pinyin = 'tā fā shì yǒu yì tiān yào wèi fù qīn bào chóu。', example_vietnamese = 'Anh ấy thề rằng sẽ có ngày báo thù cho cha mình.' WHERE level = 'B2' AND hanzi = '報仇' AND pinyin = 'bàochóu' AND vietnamese = 'báo thù, trả thù';
UPDATE public.dictionary_words SET example_hanzi = '為了報答父母的養育之恩，他努力工作。', example_pinyin = 'wèi le bào dá fù mǔ de yǎng yù zhī ēn， tā nǔ lì gōng zuò。', example_vietnamese = 'Để báo đáp công ơn nuôi dưỡng của cha mẹ, anh ấy nỗ lực làm việc.' WHERE level = 'B2' AND hanzi = '報答' AND pinyin = 'bàodá' AND vietnamese = 'báo đáp, đền đáp';
UPDATE public.dictionary_words SET example_hanzi = '記者詳細報導了這場火災的經過。', example_pinyin = 'jì zhě xiáng xì bào dǎo le zhè chǎng huǒ zāi de jīng guò。', example_vietnamese = 'Phóng viên đã đưa tin chi tiết về diễn biến vụ hỏa hoạn này.' WHERE level = 'B2' AND hanzi = '報導' AND pinyin = 'bàodăo' AND vietnamese = 'báo cáo tin tức';
UPDATE public.dictionary_words SET example_hanzi = '新生要在開學前一天到學校報到。', example_pinyin = 'xīn shēng yào zài kāi xué qián yì tiān dào xué xiào bào dào。', example_vietnamese = 'Học sinh mới phải đến trường làm thủ tục nhập học trước ngày khai giảng một hôm.' WHERE level = 'B2' AND hanzi = '報到' AND pinyin = 'bàodào' AND vietnamese = 'báo cáo có mặt';
UPDATE public.dictionary_words SET example_hanzi = '發現有人闖入，鄰居立刻報警。', example_pinyin = 'fā xiàn yǒu rén chuǎng rù， lín jū lì kè bào jǐng。', example_vietnamese = 'Phát hiện có người đột nhập, hàng xóm lập tức báo cảnh sát.' WHERE level = 'B2' AND hanzi = '報警' AND pinyin = 'bàojĭng' AND vietnamese = 'báo nguy, báo cảnh sát';
UPDATE public.dictionary_words SET example_hanzi = '他大學畢業後就進了一家報社工作。', example_pinyin = 'tā dà xué bì yè hòu jiù jìn le yì jiā bào shè gōng zuò。', example_vietnamese = 'Sau khi tốt nghiệp đại học, anh ấy vào làm việc tại một tòa soạn báo.' WHERE level = 'B2' AND hanzi = '報社' AND pinyin = 'bàoshè' AND vietnamese = 'toà soạn, tòa báo';
UPDATE public.dictionary_words SET example_hanzi = '這部電影因為含有太多暴力畫面而被限制播出。', example_pinyin = 'zhè bù diàn yǐng yīn wèi hán yǒu tài duō bào lì huà miàn ér bèi xiàn zhì bō chū。', example_vietnamese = 'Bộ phim này vì chứa quá nhiều cảnh bạo lực nên bị hạn chế chiếu.' WHERE level = 'B2' AND hanzi = '暴力' AND pinyin = 'bàolì' AND vietnamese = 'bạo lực, vũ lực';
UPDATE public.dictionary_words SET example_hanzi = '他脾氣暴躁，一點小事就發火。', example_pinyin = 'tā pí qì bào zào， yì diǎn xiǎo shì jiù fā huǒ。', example_vietnamese = 'Anh ấy tính nóng nảy, chuyện nhỏ cũng nổi giận.' WHERE level = 'B2' AND hanzi = '暴躁' AND pinyin = 'bàozào' AND vietnamese = 'nóng nảy, hấp tấp';
UPDATE public.dictionary_words SET example_hanzi = '工廠裡突然發生爆炸，濃煙沖天。', example_pinyin = 'gōng chǎng lǐ tū rán fā shēng bào zhà， nóng yān chōng tiān。', example_vietnamese = 'Trong nhà máy bất ngờ xảy ra vụ nổ, khói đen bốc lên ngút trời.' WHERE level = 'B2' AND hanzi = '爆炸' AND pinyin = 'bàozhà' AND vietnamese = 'nổ, làm nổ tung';
UPDATE public.dictionary_words SET example_hanzi = '這起交通意外真是一場悲劇。', example_pinyin = 'zhè qǐ jiāo tōng yì wài zhēn shì yì chǎng bēi jù。', example_vietnamese = 'Vụ tai nạn giao thông này thật sự là một bi kịch.' WHERE level = 'B2' AND hanzi = '悲劇' AND pinyin = 'bēijù' AND vietnamese = 'bi kịch';
UPDATE public.dictionary_words SET example_hanzi = '得知老師去世的消息，學生們都非常悲痛。', example_pinyin = 'dé zhī lǎo shī qù shì de xiāo xī， xué shēng men dōu fēi cháng bēi tòng。', example_vietnamese = 'Biết tin thầy giáo qua đời, học sinh ai nấy đều vô cùng đau buồn.' WHERE level = 'B2' AND hanzi = '悲痛' AND pinyin = 'bēitòng' AND vietnamese = 'bi thương, đau buồn';
UPDATE public.dictionary_words SET example_hanzi = '今年公司的營業額成長了一倍。', example_pinyin = 'jīn nián gōng sī de yíng yè é chéng zhǎng le yí bèi。', example_vietnamese = 'Năm nay doanh thu của công ty tăng gấp đôi.' WHERE level = 'B2' AND hanzi = '倍' AND pinyin = 'bèi' AND vietnamese = 'lần, gấp bội';
UPDATE public.dictionary_words SET example_hanzi = '出門前記得備好雨具，以防下雨。', example_pinyin = 'chū mén qián jì de bèi hǎo yǔ jù， yǐ fáng xià yǔ。', example_vietnamese = 'Trước khi ra ngoài nhớ chuẩn bị sẵn đồ che mưa, phòng khi trời mưa.' WHERE level = 'B2' AND hanzi = '備' AND pinyin = 'bèi' AND vietnamese = 'chuẩn bị, phòng bị';
UPDATE public.dictionary_words SET example_hanzi = '支票的背面需要簽名才能兌現。', example_pinyin = 'zhī piào de bèi miàn xū yào qiān míng cái néng duì xiàn。', example_vietnamese = 'Mặt sau của tấm séc cần phải ký tên mới có thể đổi thành tiền mặt.' WHERE level = 'B2' AND hanzi = '背面' AND pinyin = 'bèimiàn' AND vietnamese = 'mặt trái, mặt sau lưng';
UPDATE public.dictionary_words SET example_hanzi = '聽到消息後，他立刻奔向醫院。', example_pinyin = 'tīng dào xiāo xī hòu， tā lì kè bēn xiàng yī yuàn。', example_vietnamese = 'Nghe được tin tức, anh ấy lập tức chạy về phía bệnh viện.' WHERE level = 'B2' AND hanzi = '奔' AND pinyin = 'bēn' AND vietnamese = 'chạy';
UPDATE public.dictionary_words SET example_hanzi = '孩子們在草地上開心地奔跑。', example_pinyin = 'hái zi men zài cǎo dì shàng kāi xīn de bēn pǎo。', example_vietnamese = 'Bọn trẻ chạy nhảy vui vẻ trên bãi cỏ.' WHERE level = 'B2' AND hanzi = '奔跑' AND pinyin = 'bēnpăo' AND vietnamese = 'chạy nhanh';
UPDATE public.dictionary_words SET example_hanzi = '這件事本來就跟你沒有關係。', example_pinyin = 'zhè jiàn shì běn lái jiù gēn nǐ méi yǒu guān xì。', example_vietnamese = 'Chuyện này vốn dĩ chẳng liên quan gì đến bạn cả.' WHERE level = 'B2' AND hanzi = '本來' AND pinyin = 'běnlái' AND vietnamese = 'vốn có, lúc đầu';
UPDATE public.dictionary_words SET example_hanzi = '他有一身修理機器的本領。', example_pinyin = 'tā yǒu yì shēn xiū lǐ jī qì de běn lǐng。', example_vietnamese = 'Anh ấy có cả một thân bản lĩnh sửa chữa máy móc.' WHERE level = 'B2' AND hanzi = '本領' AND pinyin = 'běnlĭng' AND vietnamese = 'bản lĩnh, năng lực';
UPDATE public.dictionary_words SET example_hanzi = '這個問題本身就很複雜，很難有標準答案。', example_pinyin = 'zhè gè wèn tí běn shēn jiù hěn fù zá， hěn nán yǒu biāo zhǔn dá àn。', example_vietnamese = 'Bản thân vấn đề này đã rất phức tạp, khó mà có đáp án chuẩn.' WHERE level = 'B2' AND hanzi = '本身' AND pinyin = 'běnshēn' AND vietnamese = 'bản thân';
UPDATE public.dictionary_words SET example_hanzi = '這家公司近年來積極開發本土市場。', example_pinyin = 'zhè jiā gōng sī jìn nián lái jī jí kāi fā běn tǔ shì chǎng。', example_vietnamese = 'Những năm gần đây công ty này tích cực khai thác thị trường bản địa.' WHERE level = 'B2' AND hanzi = '本土' AND pinyin = 'běntŭ' AND vietnamese = 'quê hương, mảnh đất này';
UPDATE public.dictionary_words SET example_hanzi = '這台舊冰箱又笨重又占空間。', example_pinyin = 'zhè tái jiù bīng xiāng yòu bèn zhòng yòu zhàn kōng jiān。', example_vietnamese = 'Chiếc tủ lạnh cũ này vừa cồng kềnh vừa chiếm diện tích.' WHERE level = 'B2' AND hanzi = '笨重' AND pinyin = 'bènzhòng' AND vietnamese = 'cồng kềnh, to lớn';
UPDATE public.dictionary_words SET example_hanzi = '這兩件衣服的價錢差不多，你可以比一比。', example_pinyin = 'zhè liǎng jiàn yī fu de jià qián chà bù duō， nǐ kě yǐ bǐ yi bǐ。', example_vietnamese = 'Giá của hai chiếc áo này gần bằng nhau, bạn có thể so sánh thử.' WHERE level = 'B2' AND hanzi = '比' AND pinyin = 'bĭ' AND vietnamese = 'so sánh, so đo';
UPDATE public.dictionary_words SET example_hanzi = '我打個比方，你就明白了。', example_pinyin = 'wǒ dǎ gè bǐ fāng， nǐ jiù míng bái le。', example_vietnamese = 'Để tôi ví dụ thế này, bạn sẽ hiểu ngay.' WHERE level = 'B2' AND hanzi = '比方' AND pinyin = 'bĭfāng' AND vietnamese = 'ví, so bì';
UPDATE public.dictionary_words SET example_hanzi = '有些水果，比方說榴槤，味道很特別。', example_pinyin = 'yǒu xiē shuǐ guǒ， bǐ fāng shuō liú lián， wèi dào hěn tè bié。', example_vietnamese = 'Có một số loại trái cây, ví dụ như sầu riêng, có mùi vị rất đặc biệt.' WHERE level = 'B2' AND hanzi = '比方(說)' AND pinyin = 'bĭfāng(shūo)' AND vietnamese = 'so sánh với';
UPDATE public.dictionary_words SET example_hanzi = '老師要我們做一個中西文化的比較。', example_pinyin = 'lǎo shī yào wǒ men zuò yí gè zhōng xī wén huà de bǐ jiào。', example_vietnamese = 'Thầy giáo yêu cầu chúng tôi làm một bài so sánh văn hóa Đông Tây.' WHERE level = 'B2' AND hanzi = '比較' AND pinyin = 'bĭjiào' AND vietnamese = 'so sánh';
UPDATE public.dictionary_words SET example_hanzi = '今天的天氣比較涼快。', example_pinyin = 'jīn tiān de tiān qì bǐ jiào liáng kuài。', example_vietnamese = 'Thời tiết hôm nay tương đối mát mẻ.' WHERE level = 'B2' AND hanzi = '比較' AND pinyin = 'bĭjiào' AND vietnamese = 'tương đối, khá';
UPDATE public.dictionary_words SET example_hanzi = '這次調查中，女性的比例比男性高。', example_pinyin = 'zhè cì diào chá zhōng， nǚ xìng de bǐ lì bǐ nán xìng gāo。', example_vietnamese = 'Trong cuộc khảo sát này, tỉ lệ nữ giới cao hơn nam giới.' WHERE level = 'B2' AND hanzi = '比例' AND pinyin = 'bĭlì' AND vietnamese = 'tỉ lệ';
UPDATE public.dictionary_words SET example_hanzi = '雖然意見不同，我們還是要彼此尊重。', example_pinyin = 'suī rán yì jiàn bù tóng， wǒ men hái shì yào bǐ cǐ zūn zhòng。', example_vietnamese = 'Dù ý kiến khác nhau, chúng ta vẫn phải tôn trọng lẫn nhau.' WHERE level = 'B2' AND hanzi = '彼此' AND pinyin = 'bĭcĭ' AND vietnamese = 'lẫn nhau';
UPDATE public.dictionary_words SET example_hanzi = '上課的時候，她總是認真做筆記。', example_pinyin = 'shàng kè de shí hòu， tā zǒng shì rèn zhēn zuò bǐ jì。', example_vietnamese = 'Trong giờ học, cô ấy luôn chăm chỉ ghi chép bài.' WHERE level = 'B2' AND hanzi = '筆記' AND pinyin = 'bĭjì' AND vietnamese = 'ghi chép';
UPDATE public.dictionary_words SET example_hanzi = '這次應徵需要先通過筆試才能進入面試。', example_pinyin = 'zhè cì yìng zhēng xū yào xiān tōng guò bǐ shì cái néng jìn rù miàn shì。', example_vietnamese = 'Lần tuyển dụng này cần phải qua bài thi viết trước rồi mới được vào phỏng vấn.' WHERE level = 'B2' AND hanzi = '筆試' AND pinyin = 'bĭshì' AND vietnamese = 'cuộc thi viết';
UPDATE public.dictionary_words SET example_hanzi = '明天要筆試，他今晚得好好複習。', example_pinyin = 'míng tiān yào bǐ shì， tā jīn wǎn děi hǎo hǎo fù xí。', example_vietnamese = 'Ngày mai phải thi viết, tối nay anh ấy phải ôn tập cho kỹ.' WHERE level = 'B2' AND hanzi = '筆試' AND pinyin = 'bĭshì' AND vietnamese = 'thi viết';
UPDATE public.dictionary_words SET example_hanzi = '醫生請他閉上眼睛檢查視力。', example_pinyin = 'yī shēng qǐng tā bì shàng yǎn jīng jiǎn chá shì lì。', example_vietnamese = 'Bác sĩ yêu cầu anh ấy nhắm mắt lại để kiểm tra thị lực.' WHERE level = 'B2' AND hanzi = '閉' AND pinyin = 'bì' AND vietnamese = 'đóng, khép, bịt';
UPDATE public.dictionary_words SET example_hanzi = '進入實驗室之前必須先戴上口罩和手套。', example_pinyin = 'jìn rù shí yàn shì zhī qián bì xū xiān dài shàng kǒu zhào hé shǒu tào。', example_vietnamese = 'Trước khi vào phòng thí nghiệm nhất định phải đeo khẩu trang và găng tay.' WHERE level = 'B2' AND hanzi = '必須' AND pinyin = 'bìxū' AND vietnamese = 'phải, nhất định';
UPDATE public.dictionary_words SET example_hanzi = '我覺得沒有必要為了這種小事吵架。', example_pinyin = 'wǒ jué de méi yǒu bì yào wèi le zhè zhǒng xiǎo shì chǎo jià。', example_vietnamese = 'Tôi thấy không cần thiết phải cãi nhau vì chuyện nhỏ nhặt như vậy.' WHERE level = 'B2' AND hanzi = '必要' AND pinyin = 'bìyào' AND vietnamese = 'cần thiết, thiết yếu';
UPDATE public.dictionary_words SET example_hanzi = '奶奶正在用竹子編一個籃子。', example_pinyin = 'nǎi nai zhèng zài yòng zhú zi biān yí gè lán zi。', example_vietnamese = 'Bà đang dùng tre đan một cái giỏ.' WHERE level = 'B2' AND hanzi = '編' AND pinyin = 'biān' AND vietnamese = 'bện, đan, thắt';
UPDATE public.dictionary_words SET example_hanzi = '這顆球被壓得扁扁的，沒辦法用了。', example_pinyin = 'zhè kē qiú bèi yā de biǎn biǎn de， méi bàn fǎ yòng le。', example_vietnamese = 'Quả bóng này bị đè dẹp lép, không dùng được nữa.' WHERE level = 'B2' AND hanzi = '扁' AND pinyin = 'biǎn' AND vietnamese = 'dẹt, dẹp';
UPDATE public.dictionary_words SET example_hanzi = '他一聽完消息，便立刻出發了。', example_pinyin = 'tā yì tīng wán xiāo xī， biàn lì kè chū fā le。', example_vietnamese = 'Anh ấy vừa nghe xong tin tức liền lập tức xuất phát ngay.' WHERE level = 'B2' AND hanzi = '便' AND pinyin = 'biàn' AND vietnamese = 'tiện lợi, thuận tiện';
UPDATE public.dictionary_words SET example_hanzi = '這附近有捷運站，交通非常便利。', example_pinyin = 'zhè fù jìn yǒu jié yùn zhàn， jiāo tōng fēi cháng biàn lì。', example_vietnamese = 'Gần đây có ga tàu điện ngầm, giao thông rất tiện lợi.' WHERE level = 'B2' AND hanzi = '便利' AND pinyin = 'biànlì' AND vietnamese = 'tiện lợi';
UPDATE public.dictionary_words SET example_hanzi = '這次組織的變動讓不少員工感到不安。', example_pinyin = 'zhè cì zǔ zhī de biàn dòng ràng bù shǎo yuán gōng gǎn dào bù ān。', example_vietnamese = 'Sự biến động tổ chức lần này khiến không ít nhân viên cảm thấy bất an.' WHERE level = 'B2' AND hanzi = '變動' AND pinyin = 'biàndòng' AND vietnamese = 'biến động, thay đổi';
UPDATE public.dictionary_words SET example_hanzi = '由於天氣關係，行程可能會有所變動。', example_pinyin = 'yóu yú tiān qì guān xì， xíng chéng kě néng huì yǒu suǒ biàn dòng。', example_vietnamese = 'Do vấn đề thời tiết, lịch trình có thể sẽ có sự thay đổi.' WHERE level = 'B2' AND hanzi = '變動' AND pinyin = 'biàndòng' AND vietnamese = 'thay đổi, biến đổi';
UPDATE public.dictionary_words SET example_hanzi = '這篇文章的標題吸引了很多讀者。', example_pinyin = 'zhè piān wén zhāng de biāo tí xī yǐn le hěn duō dú zhě。', example_vietnamese = 'Tiêu đề của bài viết này đã thu hút rất nhiều độc giả.' WHERE level = 'B2' AND hanzi = '標題' AND pinyin = 'biāotí' AND vietnamese = 'đầu đề, tiêu đề';
UPDATE public.dictionary_words SET example_hanzi = '路口豎立著一個禁止左轉的標誌。', example_pinyin = 'lù kǒu shù lì zhe yí gè jìn zhǐ zuǒ zhuǎn de biāo zhì。', example_vietnamese = 'Ở ngã tư dựng một biển báo cấm rẽ trái.' WHERE level = 'B2' AND hanzi = '標誌' AND pinyin = 'biāozhì' AND vietnamese = 'ký hiệu';
UPDATE public.dictionary_words SET example_hanzi = '請填好這張表格再交給櫃檯。', example_pinyin = 'qǐng tián hǎo zhè zhāng biǎo gé zài jiāo gěi guì tái。', example_vietnamese = 'Xin điền xong tờ biểu mẫu này rồi nộp lại cho quầy lễ tân.' WHERE level = 'B2' AND hanzi = '表格' AND pinyin = 'biăogé' AND vietnamese = 'bảng, bảng hiệu';
UPDATE public.dictionary_words SET example_hanzi = '從她的表情就能看出她很失望。', example_pinyin = 'cóng tā de biǎo qíng jiù néng kàn chū tā hěn shī wàng。', example_vietnamese = 'Nhìn biểu cảm của cô ấy là biết ngay cô ấy rất thất vọng.' WHERE level = 'B2' AND hanzi = '表情' AND pinyin = 'biăoqíng' AND vietnamese = 'biểu cảm';
UPDATE public.dictionary_words SET example_hanzi = '校長在朝會上公開表揚了那位拾金不昧的學生。', example_pinyin = 'xiào zhǎng zài cháo huì shàng gōng kāi biǎo yáng le nà wèi shí jīn bú mèi de xué shēng。', example_vietnamese = 'Hiệu trưởng đã công khai khen thưởng học sinh nhặt được của rơi trả lại người mất đó trong buổi chào cờ.' WHERE level = 'B2' AND hanzi = '表揚' AND pinyin = 'biăoyáng' AND vietnamese = 'khen, biểu dương';
UPDATE public.dictionary_words SET example_hanzi = '這杯飲料放了很多冰塊，喝起來很冰。', example_pinyin = 'zhè bēi yǐn liào fàng le hěn duō bīng kuài， hē qǐ lái hěn bīng。', example_vietnamese = 'Ly nước này bỏ rất nhiều đá, uống vào thấy rất lạnh.' WHERE level = 'B2' AND hanzi = '冰' AND pinyin = 'bīng' AND vietnamese = 'băng, nước đá';
UPDATE public.dictionary_words SET example_hanzi = '這次評鑑他的部門被評為丙等。', example_pinyin = 'zhè cì píng jiàn tā de bù mén bèi píng wéi bǐng děng。', example_vietnamese = 'Lần đánh giá này bộ phận của anh ấy bị xếp hạng C.' WHERE level = 'B2' AND hanzi = '丙' AND pinyin = 'bǐng' AND vietnamese = 'hạng C, loại thứ ba';
UPDATE public.dictionary_words SET example_hanzi = '事情並沒有你想的那麼簡單。', example_pinyin = 'shì qíng bìng méi yǒu nǐ xiǎng de nà me jiǎn dān。', example_vietnamese = 'Sự việc hoàn toàn không đơn giản như bạn nghĩ.' WHERE level = 'B2' AND hanzi = '並' AND pinyin = 'bìng' AND vietnamese = 'hợp lại, nhập lại';
UPDATE public.dictionary_words SET example_hanzi = '會議通過並公布了新的規定。', example_pinyin = 'huì yì tōng guò bìng gōng bù le xīn de guī dìng。', example_vietnamese = 'Cuộc họp đã thông qua và công bố quy định mới.' WHERE level = 'B2' AND hanzi = '並' AND pinyin = 'bìng' AND vietnamese = 'song song, cùng lúc đó';
UPDATE public.dictionary_words SET example_hanzi = '這款手機拍照效果好，並且電池續航力強。', example_pinyin = 'zhè kuǎn shǒu jī pāi zhào xiào guǒ hǎo， bìng qiě diàn chí xù háng lì qiáng。', example_vietnamese = 'Mẫu điện thoại này chụp ảnh đẹp, đồng thời pin cũng rất bền.' WHERE level = 'B2' AND hanzi = '並且' AND pinyin = 'bìngqiě' AND vietnamese = 'đồng thời, và';
UPDATE public.dictionary_words SET example_hanzi = '這次流感是由一種新型病毒引起的。', example_pinyin = 'zhè cì liú gǎn shì yóu yì zhǒng xīn xíng bìng dú yǐn qǐ de。', example_vietnamese = 'Đợt cúm lần này do một loại virus mới gây ra.' WHERE level = 'B2' AND hanzi = '病毒' AND pinyin = 'bìngdú' AND vietnamese = 'siêu vi trùng, virus';
UPDATE public.dictionary_words SET example_hanzi = '護士每小時都會來病房量一次體溫。', example_pinyin = 'hù shì měi xiǎo shí dōu huì lái bìng fáng liáng yí cì tǐ wēn。', example_vietnamese = 'Mỗi giờ y tá đều đến phòng bệnh đo nhiệt độ một lần.' WHERE level = 'B2' AND hanzi = '病房' AND pinyin = 'bìngfáng' AND vietnamese = 'phòng bệnh';
UPDATE public.dictionary_words SET example_hanzi = '請撥這個號碼跟客服聯絡。', example_pinyin = 'qǐng bō zhè gè hào mǎ gēn kè fú lián luò。', example_vietnamese = 'Xin hãy bấm số này để liên hệ với bộ phận chăm sóc khách hàng.' WHERE level = 'B2' AND hanzi = '撥' AND pinyin = 'bō' AND vietnamese = 'đẩy, gẩy';
UPDATE public.dictionary_words SET example_hanzi = '媽媽用菠菜炒了一盤菜。', example_pinyin = 'mā ma yòng bō cài chǎo le yì pán cài。', example_vietnamese = 'Mẹ dùng rau chân vịt xào một đĩa rau.' WHERE level = 'B2' AND hanzi = '菠菜' AND pinyin = 'bōcài' AND vietnamese = 'rau chân vịt';
UPDATE public.dictionary_words SET example_hanzi = '最近股市波動很大，投資人都很緊張。', example_pinyin = 'zuì jìn gǔ shì bō dòng hěn dà， tóu zī rén dōu hěn jǐn zhāng。', example_vietnamese = 'Gần đây thị trường chứng khoán biến động rất mạnh, các nhà đầu tư đều rất lo lắng.' WHERE level = 'B2' AND hanzi = '波動' AND pinyin = 'bōdòng' AND vietnamese = 'chập chờn, không ổn định';
UPDATE public.dictionary_words SET example_hanzi = '小心，這個杯子是玻璃做的，很容易破。', example_pinyin = 'xiǎo xīn， zhè gè bēi zi shì bō lí zuò de， hěn róng yì pò。', example_vietnamese = 'Cẩn thận, cái cốc này làm bằng thủy tinh, rất dễ vỡ.' WHERE level = 'B2' AND hanzi = '玻璃' AND pinyin = 'bōli' AND vietnamese = 'thủy tinh';
UPDATE public.dictionary_words SET example_hanzi = '這家公司靠著薄利多銷的方式擴大市場。', example_pinyin = 'zhè jiā gōng sī kào zhe bó lì duō xiāo de fāng shì kuò dà shì chǎng。', example_vietnamese = 'Công ty này mở rộng thị trường bằng cách lãi ít bán nhiều.' WHERE level = 'B2' AND hanzi = '薄' AND pinyin = 'bó' AND vietnamese = 'mỏng manh';
UPDATE public.dictionary_words SET example_hanzi = '他的意志力比較薄弱，遇到挫折容易放棄。', example_pinyin = 'tā de yì zhì lì bǐ jiào bó ruò， yù dào cuò zhé róng yì fàng qì。', example_vietnamese = 'Ý chí của anh ấy khá yếu, gặp khó khăn là dễ bỏ cuộc.' WHERE level = 'B2' AND hanzi = '薄弱' AND pinyin = 'bóruò' AND vietnamese = 'bạc nhược, yếu kém';
UPDATE public.dictionary_words SET example_hanzi = '我的伯父是一位退休的中學老師。', example_pinyin = 'wǒ de bó fù shì yí wèi tuì xiū de zhōng xué lǎo shī。', example_vietnamese = 'Bác trai của tôi là một giáo viên trung học đã nghỉ hưu.' WHERE level = 'B2' AND hanzi = '伯父' AND pinyin = 'bófù' AND vietnamese = 'bác trai';
UPDATE public.dictionary_words SET example_hanzi = '伯母做的紅燒肉特別好吃。', example_pinyin = 'bó mǔ zuò de hóng shāo ròu tè bié hǎo chī。', example_vietnamese = 'Món thịt kho của bác gái làm đặc biệt ngon.' WHERE level = 'B2' AND hanzi = '伯母' AND pinyin = 'bómŭ' AND vietnamese = 'bác gái';
UPDATE public.dictionary_words SET example_hanzi = '貓在院子裡捕到了一隻老鼠。', example_pinyin = 'māo zài yuàn zi lǐ bǔ dào le yì zhī lǎo shǔ。', example_vietnamese = 'Con mèo bắt được một con chuột ở trong sân.' WHERE level = 'B2' AND hanzi = '捕' AND pinyin = 'bŭ' AND vietnamese = 'bắt, vồ, tóm';
UPDATE public.dictionary_words SET example_hanzi = '這件衣服破了個洞，得補一補。', example_pinyin = 'zhè jiàn yī fu pò le gè dòng， děi bǔ yi bǔ。', example_vietnamese = 'Chiếc áo này bị thủng một lỗ, phải vá lại một chút.' WHERE level = 'B2' AND hanzi = '補' AND pinyin = 'bŭ' AND vietnamese = 'tu bổ, sửa chữa';
UPDATE public.dictionary_words SET example_hanzi = '公司決定給受影響的顧客一些補償。', example_pinyin = 'gōng sī jué dìng gěi shòu yǐng xiǎng de gù kè yì xiē bǔ cháng。', example_vietnamese = 'Công ty quyết định bồi thường một khoản cho những khách hàng bị ảnh hưởng.' WHERE level = 'B2' AND hanzi = '補償' AND pinyin = 'bŭcháng' AND vietnamese = 'bồi thường, đền bù';
UPDATE public.dictionary_words SET example_hanzi = '老師講完後，還補充了一些例子。', example_pinyin = 'lǎo shī jiǎng wán hòu， hái bǔ chōng le yì xiē lì zi。', example_vietnamese = 'Sau khi giảng xong, thầy giáo còn bổ sung thêm vài ví dụ.' WHERE level = 'B2' AND hanzi = '補充' AND pinyin = 'bŭchōng' AND vietnamese = 'bổ sung';
UPDATE public.dictionary_words SET example_hanzi = '因為颱風停課，老師安排星期六補課。', example_pinyin = 'yīn wèi tái fēng tíng kè， lǎo shī ān pái xīng qī liù bǔ kè。', example_vietnamese = 'Vì bão nghỉ học, thầy giáo sắp xếp học bù vào thứ Bảy.' WHERE level = 'B2' AND hanzi = '補課' AND pinyin = 'bŭkè' AND vietnamese = 'học bù, dạy bù';
UPDATE public.dictionary_words SET example_hanzi = '很多學生放學後還要去補習。', example_pinyin = 'hěn duō xué shēng fàng xué hòu hái yào qù bǔ xí。', example_vietnamese = 'Nhiều học sinh sau khi tan học vẫn phải đi học thêm.' WHERE level = 'B2' AND hanzi = '補習' AND pinyin = 'bŭxí' AND vietnamese = 'bổ túc';
UPDATE public.dictionary_words SET example_hanzi = '政府每個月會發放生活補助給低收入戶。', example_pinyin = 'zhèng fǔ měi gè yuè huì fā fàng shēng huó bǔ zhù gěi dī shōu rù hù。', example_vietnamese = 'Mỗi tháng chính phủ đều phát trợ cấp sinh hoạt cho các hộ thu nhập thấp.' WHERE level = 'B2' AND hanzi = '補助' AND pinyin = 'bŭzhù' AND vietnamese = 'trợ cấp';
UPDATE public.dictionary_words SET example_hanzi = '學校決定補助清寒學生的午餐費用。', example_pinyin = 'xué xiào jué dìng bǔ zhù qīng hán xué shēng de wǔ cān fèi yòng。', example_vietnamese = 'Nhà trường quyết định trợ cấp tiền ăn trưa cho học sinh nghèo.' WHERE level = 'B2' AND hanzi = '補助' AND pinyin = 'bŭzhù' AND vietnamese = 'giúp đỡ';
UPDATE public.dictionary_words SET example_hanzi = '他往前走了幾步，就停下來了。', example_pinyin = 'tā wǎng qián zǒu le jǐ bù， jiù tíng xià lái le。', example_vietnamese = 'Anh ấy đi về phía trước vài bước rồi dừng lại.' WHERE level = 'B2' AND hanzi = '步' AND pinyin = 'bù' AND vietnamese = 'bước chân';
UPDATE public.dictionary_words SET example_hanzi = '這道菜不大辣，你可以放心吃。', example_pinyin = 'zhè dào cài bú dà là， nǐ kě yǐ fàng xīn chī。', example_vietnamese = 'Món này không cay lắm, bạn có thể yên tâm ăn.' WHERE level = 'B2' AND hanzi = '不大' AND pinyin = 'bùdà' AND vietnamese = 'vừa phải';
UPDATE public.dictionary_words SET example_hanzi = '考試結果還沒公布，他心裡感到很不安。', example_pinyin = 'kǎo shì jié guǒ hái méi gōng bù， tā xīn lǐ gǎn dào hěn bù ān。', example_vietnamese = 'Kết quả thi chưa công bố, trong lòng anh ấy cảm thấy rất bất an.' WHERE level = 'B2' AND hanzi = '不安' AND pinyin = 'bùān' AND vietnamese = 'bất an, bất ổn';
UPDATE public.dictionary_words SET example_hanzi = '難道你想一個人去不成？', example_pinyin = 'nán dào nǐ xiǎng yí gè rén qù bù chéng？', example_vietnamese = 'Chẳng lẽ bạn định đi một mình hay sao?' WHERE level = 'B2' AND hanzi = '不成' AND pinyin = 'bùchéng' AND vietnamese = 'không được phép';
UPDATE public.dictionary_words SET example_hanzi = '他因為言論不當而被公司處分。', example_pinyin = 'tā yīn wèi yán lùn bú dàng ér bèi gōng sī chǔ fèn。', example_vietnamese = 'Anh ấy vì phát ngôn không thỏa đáng mà bị công ty kỷ luật.' WHERE level = 'B2' AND hanzi = '不當' AND pinyin = 'bùdàng' AND vietnamese = 'không thích đáng';
UPDATE public.dictionary_words SET example_hanzi = '這場電影不到一半觀眾就走了大半。', example_pinyin = 'zhè chǎng diàn yǐng bú dào yí bàn guān zhòng jiù zǒu le dà bàn。', example_vietnamese = 'Bộ phim này chưa chiếu được một nửa mà phần lớn khán giả đã bỏ về.' WHERE level = 'B2' AND hanzi = '不到' AND pinyin = 'bùdào' AND vietnamese = 'không đến, không xuất hiện';
UPDATE public.dictionary_words SET example_hanzi = '我實在是不得已才向他借錢的。', example_pinyin = 'wǒ shí zài shì bù dé yǐ cái xiàng tā jiè qián de。', example_vietnamese = 'Tôi thực sự là bất đắc dĩ mới phải mượn tiền anh ấy.' WHERE level = 'B2' AND hanzi = '不得已' AND pinyin = 'bùdéyĭ' AND vietnamese = 'bất đắc dĩ';
UPDATE public.dictionary_words SET example_hanzi = '您這麼誇獎我，我真是不敢當。', example_pinyin = 'nín zhè me kuā jiǎng wǒ， wǒ zhēn shì bù gǎn dāng。', example_vietnamese = 'Ông khen tôi như vậy, tôi thật không dám nhận.' WHERE level = 'B2' AND hanzi = '不敢當' AND pinyin = 'bùgăndāng' AND vietnamese = 'không dám';
UPDATE public.dictionary_words SET example_hanzi = '他不顧大家的反對，堅持辭職去創業。', example_pinyin = 'tā bú gù dà jiā de fǎn duì， jiān chí cí zhí qù chuàng yè。', example_vietnamese = 'Anh ấy bất chấp sự phản đối của mọi người, kiên quyết nghỉ việc để khởi nghiệp.' WHERE level = 'B2' AND hanzi = '不顧' AND pinyin = 'bùgù' AND vietnamese = 'không quan tâm';
UPDATE public.dictionary_words SET example_hanzi = '能跟你合作，那真是再好不過了。', example_pinyin = 'néng gēn nǐ hé zuò， nà zhēn shì zài hǎo bú guò le。', example_vietnamese = 'Có thể hợp tác với bạn thì thật là tốt hết chỗ nói.' WHERE level = 'B2' AND hanzi = '不過' AND pinyin = 'bùguò' AND vietnamese = 'cực kỳ, hết mức';
UPDATE public.dictionary_words SET example_hanzi = '便宜的東西不見得品質不好。', example_pinyin = 'pián yi de dōng xi bú jiàn de pǐn zhì bù hǎo。', example_vietnamese = 'Đồ rẻ chưa chắc đã là chất lượng kém.' WHERE level = 'B2' AND hanzi = '不見得' AND pinyin = 'bùjiànde' AND vietnamese = 'chưa chắc';
UPDATE public.dictionary_words SET example_hanzi = '他不僅會說中文，還會說日文和韓文。', example_pinyin = 'tā bù jǐn huì shuō zhōng wén， hái huì shuō rì wén hé hán wén。', example_vietnamese = 'Anh ấy không chỉ biết nói tiếng Trung, mà còn biết nói tiếng Nhật và tiếng Hàn.' WHERE level = 'B2' AND hanzi = '不僅' AND pinyin = 'bùjĭn' AND vietnamese = 'không chỉ';
UPDATE public.dictionary_words SET example_hanzi = '長期熬夜對身體有不良的影響。', example_pinyin = 'cháng qī áo yè duì shēn tǐ yǒu bù liáng de yǐng xiǎng。', example_vietnamese = 'Thức khuya lâu dài có ảnh hưởng không tốt đến sức khỏe.' WHERE level = 'B2' AND hanzi = '不良' AND pinyin = 'bùliáng' AND vietnamese = 'không tốt';
UPDATE public.dictionary_words SET example_hanzi = '看到他被冤枉，大家都為他感到不平。', example_pinyin = 'kàn dào tā bèi yuān wǎng， dà jiā dōu wèi tā gǎn dào bù píng。', example_vietnamese = 'Thấy anh ấy bị oan, mọi người đều cảm thấy bất bình thay anh.' WHERE level = 'B2' AND hanzi = '不平' AND pinyin = 'bùpíng' AND vietnamese = 'không công bằng';
UPDATE public.dictionary_words SET example_hanzi = '快點出發吧，不然會趕不上火車。', example_pinyin = 'kuài diǎn chū fā ba， bù rán huì gǎn bú shàng huǒ chē。', example_vietnamese = 'Xuất phát nhanh lên thôi, nếu không sẽ lỡ chuyến tàu mất.' WHERE level = 'B2' AND hanzi = '不然' AND pinyin = 'bùrán' AND vietnamese = 'chi bằng';
UPDATE public.dictionary_words SET example_hanzi = '與其在家等消息，不如主動打電話問問。', example_pinyin = 'yǔ qí zài jiā děng xiāo xī， bù rú zhǔ dòng dǎ diàn huà wèn wèn。', example_vietnamese = 'Thay vì ở nhà chờ tin, chi bằng chủ động gọi điện hỏi thử.' WHERE level = 'B2' AND hanzi = '不如' AND pinyin = 'bùrú' AND vietnamese = 'không bằng, kém hơn';
UPDATE public.dictionary_words SET example_hanzi = '圖書館裡不許大聲說話。', example_pinyin = 'tú shū guǎn lǐ bù xū dà shēng shuō huà。', example_vietnamese = 'Trong thư viện không được phép nói chuyện lớn tiếng.' WHERE level = 'B2' AND hanzi = '不許' AND pinyin = 'bùxŭ' AND vietnamese = 'không được phép';
UPDATE public.dictionary_words SET example_hanzi = '這部電影內容不宜兒童觀看。', example_pinyin = 'zhè bù diàn yǐng nèi róng bù yí ér tóng guān kàn。', example_vietnamese = 'Nội dung bộ phim này không thích hợp cho trẻ em xem.' WHERE level = 'B2' AND hanzi = '不宜' AND pinyin = 'bùyí' AND vietnamese = 'không thích hợp';
UPDATE public.dictionary_words SET example_hanzi = '聽到這個笑話，大家不由得笑了出來。', example_pinyin = 'tīng dào zhè gè xiào huà， dà jiā bù yóu de xiào le chū lái。', example_vietnamese = 'Nghe câu chuyện cười này, mọi người không nhịn được mà bật cười.' WHERE level = 'B2' AND hanzi = '不由得' AND pinyin = 'bùyóude' AND vietnamese = 'đành phải';
UPDATE public.dictionary_words SET example_hanzi = '這次活動的參加人數不止一百人。', example_pinyin = 'zhè cì huó dòng de cān jiā rén shù bù zhǐ yì bǎi rén。', example_vietnamese = 'Số người tham gia hoạt động lần này không chỉ một trăm người.' WHERE level = 'B2' AND hanzi = '不止' AND pinyin = 'bùzhĭ' AND vietnamese = 'không dứt, không ngớt';
UPDATE public.dictionary_words SET example_hanzi = '他的哥哥去年入伍，現在在部隊服役。', example_pinyin = 'tā de gē ge qù nián rù wǔ， xiàn zài zài bù duì fú yì。', example_vietnamese = 'Anh trai của anh ấy nhập ngũ năm ngoái, hiện đang phục vụ trong quân đội.' WHERE level = 'B2' AND hanzi = '部隊' AND pinyin = 'bùduì' AND vietnamese = 'bộ đội';
UPDATE public.dictionary_words SET example_hanzi = '教育部長今天出席了畢業典禮。', example_pinyin = 'jiào yù bù zhǎng jīn tiān chū xí le bì yè diǎn lǐ。', example_vietnamese = 'Bộ trưởng Bộ Giáo dục hôm nay đã tham dự lễ tốt nghiệp.' WHERE level = 'B2' AND hanzi = '部長' AND pinyin = 'bùzhăng' AND vietnamese = 'bộ trưởng';
UPDATE public.dictionary_words SET example_hanzi = '學校在門口貼了一張佈告。', example_pinyin = 'xué xiào zài mén kǒu tiē le yì zhāng bù gào。', example_vietnamese = 'Nhà trường dán một bản thông báo ở cổng.' WHERE level = 'B2' AND hanzi = '布/佈告' AND pinyin = 'bùgào' AND vietnamese = 'bản thông báo';
UPDATE public.dictionary_words SET example_hanzi = '最新的活動消息都貼在佈告欄上。', example_pinyin = 'zuì xīn de huó dòng xiāo xī dōu tiē zài bù gào lán shàng。', example_vietnamese = 'Thông tin hoạt động mới nhất đều được dán trên bảng thông báo.' WHERE level = 'B2' AND hanzi = '布/佈告欄' AND pinyin = 'bùgàolán' AND vietnamese = 'bảng thông báo';
UPDATE public.dictionary_words SET example_hanzi = '他把大部分的財產都捐給了慈善機構。', example_pinyin = 'tā bǎ dà bù fen de cái chǎn dōu juān gěi le cí shàn jī gòu。', example_vietnamese = 'Anh ấy đã quyên góp phần lớn tài sản của mình cho các tổ chức từ thiện.' WHERE level = 'B2' AND hanzi = '財產' AND pinyin = 'cáichăn' AND vietnamese = 'tài sản';
UPDATE public.dictionary_words SET example_hanzi = '對他來說，健康比財富更重要。', example_pinyin = 'duì tā lái shuō， jiàn kāng bǐ cái fù gèng zhòng yào。', example_vietnamese = 'Đối với anh ấy, sức khỏe quan trọng hơn của cải.' WHERE level = 'B2' AND hanzi = '財富' AND pinyin = 'cáifù' AND vietnamese = 'của cải';
UPDATE public.dictionary_words SET example_hanzi = '她的音樂才能從小就展現出來了。', example_pinyin = 'tā de yīn yuè cái néng cóng xiǎo jiù zhǎn xiàn chū lái le。', example_vietnamese = 'Tài năng âm nhạc của cô ấy đã bộc lộ từ nhỏ.' WHERE level = 'B2' AND hanzi = '才能' AND pinyin = 'cáinéng' AND vietnamese = 'tài năng';
UPDATE public.dictionary_words SET example_hanzi = '裁判吹了哨子，宣布比賽結束。', example_pinyin = 'cái pàn chuī le shào zi， xuān bù bǐ sài jié shù。', example_vietnamese = 'Trọng tài thổi còi, tuyên bố trận đấu kết thúc.' WHERE level = 'B2' AND hanzi = '裁判' AND pinyin = 'cáipàn' AND vietnamese = 'phán xử, xét xử';
UPDATE public.dictionary_words SET example_hanzi = '公司因為業績下滑，決定裁員一百人。', example_pinyin = 'gōng sī yīn wèi yè jì xià huá， jué dìng cái yuán yì bǎi rén。', example_vietnamese = 'Vì doanh thu sụt giảm, công ty quyết định cắt giảm một trăm nhân viên.' WHERE level = 'B2' AND hanzi = '裁員' AND pinyin = 'cáiyuán' AND vietnamese = 'giảm biên chế';
UPDATE public.dictionary_words SET example_hanzi = '對不起，我不小心踩到你的腳了。', example_pinyin = 'duì bù qǐ， wǒ bù xiǎo xīn cǎi dào nǐ de jiǎo le。', example_vietnamese = 'Xin lỗi, tôi vô ý giẫm phải chân bạn rồi.' WHERE level = 'B2' AND hanzi = '踩' AND pinyin = 'căi' AND vietnamese = 'giẫm, đạp';
UPDATE public.dictionary_words SET example_hanzi = '農夫一早就到果園裡採水果。', example_pinyin = 'nóng fū yì zǎo jiù dào guǒ yuán lǐ cǎi shuǐ guǒ。', example_vietnamese = 'Người nông dân từ sáng sớm đã ra vườn hái trái cây.' WHERE level = 'B2' AND hanzi = '採' AND pinyin = 'căi' AND vietnamese = 'hái, ngắt';
UPDATE public.dictionary_words SET example_hanzi = '公司派他去負責採購辦公用品。', example_pinyin = 'gōng sī pài tā qù fù zé cǎi gòu bàn gōng yòng pǐn。', example_vietnamese = 'Công ty cử anh ấy phụ trách mua sắm đồ dùng văn phòng.' WHERE level = 'B2' AND hanzi = '採購' AND pinyin = 'căigòu' AND vietnamese = 'chọn mua, mua sắm';
UPDATE public.dictionary_words SET example_hanzi = '這台印表機可以印出彩色的照片。', example_pinyin = 'zhè tái yìn biǎo jī kě yǐ yìn chū cǎi sè de zhào piàn。', example_vietnamese = 'Chiếc máy in này có thể in ra ảnh màu.' WHERE level = 'B2' AND hanzi = '彩色' AND pinyin = 'căisè' AND vietnamese = 'màu sắc';
UPDATE public.dictionary_words SET example_hanzi = '這次活動歡迎所有人自由參與。', example_pinyin = 'zhè cì huó dòng huān yíng suǒ yǒu rén zì yóu cān yǔ。', example_vietnamese = 'Hoạt động lần này hoan nghênh mọi người tự do tham gia.' WHERE level = 'B2' AND hanzi = '參與' AND pinyin = 'cānyù' AND vietnamese = 'tham dự';
UPDATE public.dictionary_words SET example_hanzi = '學生在課堂上養蠶，觀察牠結繭的過程。', example_pinyin = 'xué shēng zài kè táng shàng yǎng cán， guān chá tā jié jiǎn de guò chéng。', example_vietnamese = 'Học sinh nuôi tằm trong lớp học, quan sát quá trình chúng kết kén.' WHERE level = 'B2' AND hanzi = '蠶' AND pinyin = 'cán' AND vietnamese = 'tằm';
UPDATE public.dictionary_words SET example_hanzi = '沒能完成承諾，他感到十分慚愧。', example_pinyin = 'méi néng wán chéng chéng nuò， tā gǎn dào shí fēn cán kuì。', example_vietnamese = 'Vì không thể hoàn thành lời hứa, anh ấy cảm thấy vô cùng xấu hổ.' WHERE level = 'B2' AND hanzi = '慚愧' AND pinyin = 'cánkuì' AND vietnamese = 'xấu hổ, hổ thẹn';
UPDATE public.dictionary_words SET example_hanzi = '這場車禍發生得太慘了，好幾個人受傷。', example_pinyin = 'zhè chǎng chē huò fā shēng de tài cǎn le， hǎo jǐ gè rén shòu shāng。', example_vietnamese = 'Vụ tai nạn xe này xảy ra thảm khốc quá, mấy người bị thương.' WHERE level = 'B2' AND hanzi = '慘' AND pinyin = 'căn' AND vietnamese = 'bi thảm';
UPDATE public.dictionary_words SET example_hanzi = '這些貨物暫時先放在倉庫裡。', example_pinyin = 'zhè xiē huò wù zàn shí xiān fàng zài cāng kù lǐ。', example_vietnamese = 'Số hàng hóa này tạm thời cứ để trong kho trước đã.' WHERE level = 'B2' AND hanzi = '倉庫' AND pinyin = 'cāngkù' AND vietnamese = 'kho, nhà kho';
UPDATE public.dictionary_words SET example_hanzi = '他把生日禮物藏在衣櫃裡。', example_pinyin = 'tā bǎ shēng rì lǐ wù cáng zài yī guì lǐ。', example_vietnamese = 'Anh ấy giấu món quà sinh nhật trong tủ quần áo.' WHERE level = 'B2' AND hanzi = '藏' AND pinyin = 'cáng' AND vietnamese = 'giấu, trốn';
UPDATE public.dictionary_words SET example_hanzi = '孩子都長大了，你別再為他們操心了。', example_pinyin = 'hái zi dōu zhǎng dà le， nǐ bié zài wèi tā men cāo xīn le。', example_vietnamese = 'Con cái đều đã lớn rồi, bạn đừng lo lắng cho chúng nữa.' WHERE level = 'B2' AND hanzi = '操心' AND pinyin = 'cāoxīn' AND vietnamese = 'bận tâm, lo nghĩ';
UPDATE public.dictionary_words SET example_hanzi = '這台機器操作起來並不困難。', example_pinyin = 'zhè tái jī qì cāo zuò qǐ lái bìng bú kùn nán。', example_vietnamese = 'Chiếc máy này thao tác không khó chút nào.' WHERE level = 'B2' AND hanzi = '操作' AND pinyin = 'cāozuò' AND vietnamese = 'thao tác';
UPDATE public.dictionary_words SET example_hanzi = '這套小說一共有六冊。', example_pinyin = 'zhè tào xiǎo shuō yí gòng yǒu liù cè。', example_vietnamese = 'Bộ tiểu thuyết này tổng cộng có sáu quyển.' WHERE level = 'B2' AND hanzi = '冊' AND pinyin = 'cè' AND vietnamese = 'sổ, quyển';
UPDATE public.dictionary_words SET example_hanzi = '公司調整了行銷策略以提高銷售量。', example_pinyin = 'gōng sī diào zhěng le xíng xiāo cè lüè yǐ tí gāo xiāo shòu liàng。', example_vietnamese = 'Công ty đã điều chỉnh chiến lược marketing để tăng doanh số.' WHERE level = 'B2' AND hanzi = '策略' AND pinyin = 'cèlüè' AND vietnamese = 'sách lược';
UPDATE public.dictionary_words SET example_hanzi = '工人用尺仔細測量房間的長寬。', example_pinyin = 'gōng rén yòng chǐ zǎi xì cè liáng fáng jiān de cháng kuān。', example_vietnamese = 'Người thợ dùng thước đo cẩn thận chiều dài và chiều rộng của căn phòng.' WHERE level = 'B2' AND hanzi = '測量' AND pinyin = 'cèliáng' AND vietnamese = 'đo lường';
UPDATE public.dictionary_words SET example_hanzi = '這款新軟體還在測試階段。', example_pinyin = 'zhè kuǎn xīn ruǎn tǐ hái zài cè shì jiē duàn。', example_vietnamese = 'Phần mềm mới này vẫn còn trong giai đoạn kiểm tra.' WHERE level = 'B2' AND hanzi = '測試' AND pinyin = 'cèshì' AND vietnamese = 'kiểm tra';
UPDATE public.dictionary_words SET example_hanzi = '下週一有一場英文小測驗。', example_pinyin = 'xià zhōu yì yǒu yì chǎng yīng wén xiǎo cè yàn。', example_vietnamese = 'Thứ Hai tuần sau có một bài kiểm tra tiếng Anh nhỏ.' WHERE level = 'B2' AND hanzi = '測驗' AND pinyin = 'cèyàn' AND vietnamese = 'kiểm tra, sát hạch';
UPDATE public.dictionary_words SET example_hanzi = '老師常用小考來測驗學生的理解程度。', example_pinyin = 'lǎo shī cháng yòng xiǎo kǎo lái cè yàn xué shēng de lǐ jiě chéng dù。', example_vietnamese = 'Thầy giáo thường dùng bài kiểm tra nhỏ để đánh giá mức độ hiểu bài của học sinh.' WHERE level = 'B2' AND hanzi = '測驗' AND pinyin = 'cèyàn' AND vietnamese = 'kiểm nghiệm, đo lường';
UPDATE public.dictionary_words SET example_hanzi = '時差讓他這幾天都睡不好。', example_pinyin = 'shí chā ràng tā zhè jǐ tiān dōu shuì bù hǎo。', example_vietnamese = 'Lệch múi giờ khiến mấy hôm nay anh ấy ngủ không ngon.' WHERE level = 'B2' AND hanzi = '差' AND pinyin = 'chā' AND vietnamese = 'so le';
UPDATE public.dictionary_words SET example_hanzi = '這麼重要的文件，千萬不能出差錯。', example_pinyin = 'zhè me zhòng yào de wén jiàn， qiān wàn bù néng chū chā cuò。', example_vietnamese = 'Tài liệu quan trọng như thế này, nhất định không được để xảy ra sai sót.' WHERE level = 'B2' AND hanzi = '差錯' AND pinyin = 'chācuò' AND vietnamese = 'sai lầm, nhầm lẫn';
UPDATE public.dictionary_words SET example_hanzi = '城市和鄉村的發展差距越來越大。', example_pinyin = 'chéng shì hé xiāng cūn de fā zhǎn chā jù yuè lái yuè dà。', example_vietnamese = 'Khoảng cách phát triển giữa thành thị và nông thôn ngày càng lớn.' WHERE level = 'B2' AND hanzi = '差距' AND pinyin = 'chājù' AND vietnamese = 'chênh lệch, khoảng cách';
UPDATE public.dictionary_words SET example_hanzi = '他把插頭插進插座裡。', example_pinyin = 'tā bǎ chā tóu chā jìn chā zuò lǐ。', example_vietnamese = 'Anh ấy cắm phích cắm vào ổ điện.' WHERE level = 'B2' AND hanzi = '插' AND pinyin = 'chā' AND vietnamese = 'cắm vào, chọc vào';
UPDATE public.dictionary_words SET example_hanzi = '媽媽很喜歡插花，客廳擺了不少作品。', example_pinyin = 'mā ma hěn xǐ huān chā huā， kè tīng bǎi le bù shǎo zuò pǐn。', example_vietnamese = 'Mẹ rất thích cắm hoa, phòng khách bày không ít tác phẩm.' WHERE level = 'B2' AND hanzi = '插花' AND pinyin = 'chāhuā' AND vietnamese = 'cắm hoa, bó hoa';
UPDATE public.dictionary_words SET example_hanzi = '這本童書的插圖畫得非常可愛。', example_pinyin = 'zhè běn tóng shū de chā tú huà de fēi cháng kě ài。', example_vietnamese = 'Tranh minh họa trong cuốn sách thiếu nhi này được vẽ rất dễ thương.' WHERE level = 'B2' AND hanzi = '插圖' AND pinyin = 'chātú' AND vietnamese = 'tranh minh họa';
UPDATE public.dictionary_words SET example_hanzi = '老人們喜歡到茶館聊天下棋。', example_pinyin = 'lǎo rén men xǐ huān dào chá guǎn liáo tiān xià qí。', example_vietnamese = 'Các cụ già thích đến quán trà trò chuyện và đánh cờ.' WHERE level = 'B2' AND hanzi = '茶館/茶館兒' AND pinyin = 'cháguăn/cháguănr' AND vietnamese = 'quán trà';
UPDATE public.dictionary_words SET example_hanzi = '公司下午舉辦了一場歡迎新同事的茶會。', example_pinyin = 'gōng sī xià wǔ jǔ bàn le yì chǎng huān yíng xīn tóng shì de chá huì。', example_vietnamese = 'Chiều nay công ty tổ chức một buổi tiệc trà chào đón đồng nghiệp mới.' WHERE level = 'B2' AND hanzi = '茶會' AND pinyin = 'cháhuì' AND vietnamese = 'tiệc trà';
UPDATE public.dictionary_words SET example_hanzi = '這種茶葉泡出來的茶特別香。', example_pinyin = 'zhè zhǒng chá yè pào chū lái de chá tè bié xiāng。', example_vietnamese = 'Loại lá trà này pha ra trà thơm đặc biệt.' WHERE level = 'B2' AND hanzi = '茶葉' AND pinyin = 'cháyè' AND vietnamese = 'lá trà';
UPDATE public.dictionary_words SET example_hanzi = '他迫不及待地拆開了生日禮物。', example_pinyin = 'tā pò bù jí dài de chāi kāi le shēng rì lǐ wù。', example_vietnamese = 'Anh ấy nóng lòng mở ngay món quà sinh nhật ra.' WHERE level = 'B2' AND hanzi = '拆' AND pinyin = 'chāi' AND vietnamese = 'mở ra, dỡ ra';
UPDATE public.dictionary_words SET example_hanzi = '這隻母貓昨天晚上產下了四隻小貓。', example_pinyin = 'zhè zhī mǔ māo zuó tiān wǎn shàng chǎn xià le sì zhī xiǎo māo。', example_vietnamese = 'Con mèo mẹ này tối qua đã sinh ra bốn con mèo con.' WHERE level = 'B2' AND hanzi = '產' AND pinyin = 'chăn' AND vietnamese = 'đẻ, sinh sản';
UPDATE public.dictionary_words SET example_hanzi = '今年稻米的產量比去年增加不少。', example_pinyin = 'jīn nián dào mǐ de chǎn liàng bǐ qù nián zēng jiā bù shǎo。', example_vietnamese = 'Sản lượng lúa gạo năm nay tăng hơn nhiều so với năm ngoái.' WHERE level = 'B2' AND hanzi = '產量' AND pinyin = 'chănliàng' AND vietnamese = 'sản lượng';
UPDATE public.dictionary_words SET example_hanzi = '政府積極扶植科技產業的發展。', example_pinyin = 'zhèng fǔ jī jí fú zhí kē jì chǎn yè de fā zhǎn。', example_vietnamese = 'Chính phủ tích cực hỗ trợ phát triển ngành công nghiệp công nghệ.' WHERE level = 'B2' AND hanzi = '產業' AND pinyin = 'chănyè' AND vietnamese = 'sản nghiệp';
UPDATE public.dictionary_words SET example_hanzi = '這是他第一次嘗試自己下廚。', example_pinyin = 'zhè shì tā dì yī cì cháng shì zì jǐ xià chú。', example_vietnamese = 'Đây là lần đầu tiên anh ấy thử tự vào bếp nấu ăn.' WHERE level = 'B2' AND hanzi = '嘗/嚐試' AND pinyin = 'chángshì' AND vietnamese = 'thử nghiệm';
UPDATE public.dictionary_words SET example_hanzi = '遵守交通規則是最基本的常識。', example_pinyin = 'zūn shǒu jiāo tōng guī zé shì zuì jī běn de cháng shí。', example_vietnamese = 'Tuân thủ luật giao thông là kiến thức thường thức cơ bản nhất.' WHERE level = 'B2' AND hanzi = '常識' AND pinyin = 'chángshì' AND vietnamese = 'thường thức';
UPDATE public.dictionary_words SET example_hanzi = '每個人都有自己的長處，不必羨慕別人。', example_pinyin = 'měi gè rén dōu yǒu zì jǐ de cháng chǔ， bú bì xiàn mù bié rén。', example_vietnamese = 'Mỗi người đều có sở trường riêng, không cần phải ghen tị với người khác.' WHERE level = 'B2' AND hanzi = '長處' AND pinyin = 'chángchù' AND vietnamese = 'sở trường';
UPDATE public.dictionary_words SET example_hanzi = '這條橋的長度將近兩公里。', example_pinyin = 'zhè tiáo qiáo de cháng dù jiāng jìn liǎng gōng lǐ。', example_vietnamese = 'Chiều dài cây cầu này gần tới hai ki-lô-mét.' WHERE level = 'B2' AND hanzi = '長度' AND pinyin = 'chángdù' AND vietnamese = 'độ dài';
UPDATE public.dictionary_words SET example_hanzi = '這張桌子是長方形的。', example_pinyin = 'zhè zhāng zhuō zi shì cháng fāng xíng de。', example_vietnamese = 'Cái bàn này có hình chữ nhật.' WHERE level = 'B2' AND hanzi = '長方形' AND pinyin = 'chángfāngxíng' AND vietnamese = 'hình chữ nhật';
UPDATE public.dictionary_words SET example_hanzi = '兩人的感情經過考驗，才變得更加長久。', example_pinyin = 'liǎng rén de gǎn qíng jīng guò kǎo yàn， cái biàn de gèng jiā cháng jiǔ。', example_vietnamese = 'Tình cảm của hai người trải qua thử thách mới trở nên bền lâu hơn.' WHERE level = 'B2' AND hanzi = '長久' AND pinyin = 'chángjiŭ' AND vietnamese = 'lâu dài';
UPDATE public.dictionary_words SET example_hanzi = '他每天都要搭長途巴士上班。', example_pinyin = 'tā měi tiān dōu yào dā cháng tú bā shì shàng bān。', example_vietnamese = 'Ngày nào anh ấy cũng phải đi xe buýt đường dài để đi làm.' WHERE level = 'B2' AND hanzi = '長途' AND pinyin = 'chángtú' AND vietnamese = 'đường dài';
UPDATE public.dictionary_words SET example_hanzi = '昨天晚上下了一場大雨。', example_pinyin = 'zuó tiān wǎn shàng xià le yì chǎng dà yǔ。', example_vietnamese = 'Tối qua có một trận mưa lớn.' WHERE level = 'B2' AND hanzi = '場' AND pinyin = 'chăng' AND vietnamese = 'sân phơi';
UPDATE public.dictionary_words SET example_hanzi = '這次運動會的場地在市立體育館。', example_pinyin = 'zhè cì yùn dòng huì de chǎng dì zài shì lì tǐ yù guǎn。', example_vietnamese = 'Địa điểm của hội thao lần này là ở nhà thi đấu thành phố.' WHERE level = 'B2' AND hanzi = '場地' AND pinyin = 'chăngdì' AND vietnamese = 'sân bãi';
UPDATE public.dictionary_words SET example_hanzi = '在正式的場合，穿著要特別注意。', example_pinyin = 'zài zhèng shì de chǎng hé， chuān zhuó yào tè bié zhù yì。', example_vietnamese = 'Trong những dịp trang trọng, cách ăn mặc cần đặc biệt chú ý.' WHERE level = 'B2' AND hanzi = '場合' AND pinyin = 'chănghé' AND vietnamese = 'trường hợp, nơi';
UPDATE public.dictionary_words SET example_hanzi = '圖書館是一個安靜讀書的場所。', example_pinyin = 'tú shū guǎn shì yí gè ān jìng dú shū de chǎng suǒ。', example_vietnamese = 'Thư viện là một nơi yên tĩnh để đọc sách.' WHERE level = 'B2' AND hanzi = '場所' AND pinyin = 'chăngsuŏ' AND vietnamese = 'nơi chốn';
UPDATE public.dictionary_words SET example_hanzi = '這款零件是向國外廠商訂購的。', example_pinyin = 'zhè kuǎn líng jiàn shì xiàng guó wài chǎng shāng dìng gòu de。', example_vietnamese = 'Loại linh kiện này được đặt mua từ nhà cung cấp nước ngoài.' WHERE level = 'B2' AND hanzi = '廠商' AND pinyin = 'chăngshāng' AND vietnamese = 'nhà máy';
UPDATE public.dictionary_words SET example_hanzi = '他偷偷抄了同學的作業。', example_pinyin = 'tā tōu tōu chāo le tóng xué de zuò yè。', example_vietnamese = 'Cậu ấy lén chép bài tập của bạn học.' WHERE level = 'B2' AND hanzi = '抄' AND pinyin = 'chāo' AND vietnamese = 'sao chép';
UPDATE public.dictionary_words SET example_hanzi = '皮包裡放著幾張鈔票和一些零錢。', example_pinyin = 'pí bāo lǐ fàng zhe jǐ zhāng chāo piào hé yì xiē líng qián。', example_vietnamese = 'Trong ví có để vài tờ tiền giấy và ít tiền lẻ.' WHERE level = 'B2' AND hanzi = '鈔票' AND pinyin = 'chāopiào' AND vietnamese = 'tiền giấy, giấy bạc';
UPDATE public.dictionary_words SET example_hanzi = '這次的花費超出了我們原本的預算。', example_pinyin = 'zhè cì de huā fèi chāo chū le wǒ men yuán běn de yù suàn。', example_vietnamese = 'Chi phí lần này đã vượt quá ngân sách ban đầu của chúng tôi.' WHERE level = 'B2' AND hanzi = '超出' AND pinyin = 'chāochū' AND vietnamese = 'vượt qua, vượt khỏi';
UPDATE public.dictionary_words SET example_hanzi = '弟弟最喜歡的卡通人物就是超人。', example_pinyin = 'dì di zuì xǐ huān de kǎ tōng rén wù jiù shì chāo rén。', example_vietnamese = 'Nhân vật hoạt hình mà em trai thích nhất chính là Siêu nhân.' WHERE level = 'B2' AND hanzi = '超人' AND pinyin = 'chāorén' AND vietnamese = 'siêu nhân';
UPDATE public.dictionary_words SET example_hanzi = '這位選手成功超越了自己的紀錄。', example_pinyin = 'zhè wèi xuǎn shǒu chéng gōng chāo yuè le zì jǐ de jì lù。', example_vietnamese = 'Vận động viên này đã thành công vượt qua kỷ lục của chính mình.' WHERE level = 'B2' AND hanzi = '超越' AND pinyin = 'chāoyuè' AND vietnamese = 'vượt quá, hơn hẳn';
UPDATE public.dictionary_words SET example_hanzi = '你的行李超重了，得再加付一些費用。', example_pinyin = 'nǐ de xíng li chāo zhòng le， děi zài jiā fù yì xiē fèi yòng。', example_vietnamese = 'Hành lý của bạn quá cân rồi, phải trả thêm một khoản phí nữa.' WHERE level = 'B2' AND hanzi = '超重' AND pinyin = 'chāozhòng' AND vietnamese = 'siêu trọng, quá tải';
UPDATE public.dictionary_words SET example_hanzi = '他朝我微微一笑，就轉身離開了。', example_pinyin = 'tā cháo wǒ wēi wēi yí xiào， jiù zhuǎn shēn lí kāi le。', example_vietnamese = 'Anh ấy hướng về phía tôi mỉm cười nhẹ rồi quay người rời đi.' WHERE level = 'B2' AND hanzi = '朝' AND pinyin = 'cháo' AND vietnamese = 'triều, triều đại';
UPDATE public.dictionary_words SET example_hanzi = '這種穿搭風格已經成為現在的潮流。', example_pinyin = 'zhè zhǒng chuān dā fēng gé yǐ jīng chéng wéi xiàn zài de cháo liú。', example_vietnamese = 'Phong cách phối đồ này đã trở thành trào lưu hiện nay.' WHERE level = 'B2' AND hanzi = '潮流' AND pinyin = 'cháoliú' AND vietnamese = 'thủy triều, trào lưu';
UPDATE public.dictionary_words SET example_hanzi = '梅雨季節，衣服常常曬不乾，房間也很潮溼。', example_pinyin = 'méi yǔ jì jié， yī fu cháng cháng shài bù gān， fáng jiān yě hěn cháo shī。', example_vietnamese = 'Vào mùa mưa phùn, quần áo thường phơi không khô, phòng cũng rất ẩm ướt.' WHERE level = 'B2' AND hanzi = '潮溼/濕' AND pinyin = 'cháoshī' AND vietnamese = 'ẩm ướt';
UPDATE public.dictionary_words SET example_hanzi = '隔壁鄰居半夜吵鬧，讓大家都無法入睡。', example_pinyin = 'gé bì lín jū bàn yè chǎo nào， ràng dà jiā dōu wú fǎ rù shuì。', example_vietnamese = 'Hàng xóm bên cạnh ồn ào cãi vã giữa đêm, khiến mọi người không tài nào ngủ được.' WHERE level = 'B2' AND hanzi = '吵鬧' AND pinyin = 'chăonào' AND vietnamese = 'tranh cãi ầm ĩ';
UPDATE public.dictionary_words SET example_hanzi = '出發前記得先買好車票。', example_pinyin = 'chū fā qián jì de xiān mǎi hǎo chē piào。', example_vietnamese = 'Trước khi xuất phát nhớ mua sẵn vé xe.' WHERE level = 'B2' AND hanzi = '車票' AND pinyin = 'chēpiào' AND vietnamese = 'vé xe';
UPDATE public.dictionary_words SET example_hanzi = '他用力扯開了纏在一起的繩子。', example_pinyin = 'tā yòng lì chě kāi le chán zài yì qǐ de shéng zi。', example_vietnamese = 'Anh ấy dùng sức kéo tách sợi dây đang bị rối vào nhau.' WHERE level = 'B2' AND hanzi = '扯' AND pinyin = 'chě' AND vietnamese = 'kéo, lôi, căng';
UPDATE public.dictionary_words SET example_hanzi = '這個問題必須澈底解決，不能再拖了。', example_pinyin = 'zhè gè wèn tí bì xū chè dǐ jiě jué， bù néng zài tuō le。', example_vietnamese = 'Vấn đề này phải giải quyết triệt để, không thể trì hoãn thêm nữa.' WHERE level = 'B2' AND hanzi = '澈底' AND pinyin = 'chèdĭ' AND vietnamese = 'triệt để, đến cùng';
UPDATE public.dictionary_words SET example_hanzi = '船在暴風雨中不幸沉入海底。', example_pinyin = 'chuán zài bào fēng yǔ zhōng bú xìng chén rù hǎi dǐ。', example_vietnamese = 'Con tàu không may bị chìm xuống đáy biển trong cơn bão.' WHERE level = 'B2' AND hanzi = '沉' AND pinyin = 'chén' AND vietnamese = 'chìm, rơi xuống';
UPDATE public.dictionary_words SET example_hanzi = '博物館裡陳列著許多古代文物。', example_pinyin = 'bó wù guǎn lǐ chén liè zhe xū duō gǔ dài wén wù。', example_vietnamese = 'Trong bảo tàng trưng bày rất nhiều cổ vật.' WHERE level = 'B2' AND hanzi = '陳列' AND pinyin = 'chénliè' AND vietnamese = 'trưng bày, triển lãm';
UPDATE public.dictionary_words SET example_hanzi = '大家都稱他為這個領域的專家。', example_pinyin = 'dà jiā dōu chēng tā wéi zhè gè lǐng yù de zhuān jiā。', example_vietnamese = 'Mọi người đều gọi anh ấy là chuyên gia trong lĩnh vực này.' WHERE level = 'B2' AND hanzi = '稱' AND pinyin = 'chēng' AND vietnamese = 'gọi, gọi là';
UPDATE public.dictionary_words SET example_hanzi = '他用一把傘撐住了風雨。', example_pinyin = 'tā yòng yì bǎ sǎn chēng zhù le fēng yǔ。', example_vietnamese = 'Anh ấy dùng một chiếc ô chống đỡ mưa gió.' WHERE level = 'B2' AND hanzi = '撐' AND pinyin = 'chēng' AND vietnamese = 'chống, chống đỡ';
UPDATE public.dictionary_words SET example_hanzi = '這件事終於辦成了。', example_pinyin = 'zhè jiàn shì zhōng yú bàn chéng le。', example_vietnamese = 'Việc này cuối cùng cũng đã thành công.' WHERE level = 'B2' AND hanzi = '成' AND pinyin = 'chéng' AND vietnamese = 'thành, trở thành';
UPDATE public.dictionary_words SET example_hanzi = '十年的努力，總算修成正果。', example_pinyin = 'shí nián de nǔ lì， zǒng suàn xiū chéng zhèng guǒ。', example_vietnamese = 'Mười năm nỗ lực, cuối cùng cũng đã đạt được thành quả.' WHERE level = 'B2' AND hanzi = '成' AND pinyin = 'chéng' AND vietnamese = 'hoàn thành';
UPDATE public.dictionary_words SET example_hanzi = '原料漲價讓生產成本增加不少。', example_pinyin = 'yuán liào zhǎng jià ràng shēng chǎn chéng běn zēng jiā bù shǎo。', example_vietnamese = 'Giá nguyên liệu tăng khiến chi phí sản xuất tăng lên không ít.' WHERE level = 'B2' AND hanzi = '成本' AND pinyin = 'chéngběn' AND vietnamese = 'giá thành';
UPDATE public.dictionary_words SET example_hanzi = '這瓶乳液含有天然的植物成分。', example_pinyin = 'zhè píng rǔ yè hán yǒu tiān rán de zhí wù chéng fèn。', example_vietnamese = 'Chai sữa dưỡng này chứa thành phần thực vật tự nhiên.' WHERE level = 'B2' AND hanzi = '成分/份' AND pinyin = 'chéngfèn' AND vietnamese = 'thành phần';
UPDATE public.dictionary_words SET example_hanzi = '經過一番討價還價，這筆生意終於成交了。', example_pinyin = 'jīng guò yì fān tǎo jià huán jià， zhè bǐ shēng yì zhōng yú chéng jiāo le。', example_vietnamese = 'Sau một hồi mặc cả, thương vụ này cuối cùng đã chốt thành công.' WHERE level = 'B2' AND hanzi = '成交' AND pinyin = 'chéngjiāo' AND vietnamese = 'thống nhất mua bán';
UPDATE public.dictionary_words SET example_hanzi = '這間公司是十年前成立的。', example_pinyin = 'zhè jiàn gōng sī shì shí nián qián chéng lì de。', example_vietnamese = 'Công ty này được thành lập cách đây mười năm.' WHERE level = 'B2' AND hanzi = '成立' AND pinyin = 'chénglì' AND vietnamese = 'thành lập, lập';
UPDATE public.dictionary_words SET example_hanzi = '他放假的時候成天待在家裡打電動。', example_pinyin = 'tā fàng jià de shí hòu chéng tiān dài zài jiā lǐ dǎ diàn dòng。', example_vietnamese = 'Lúc nghỉ lễ cậu ấy ở lì trong nhà chơi game suốt ngày.' WHERE level = 'B2' AND hanzi = '成天' AND pinyin = 'chéngtiān' AND vietnamese = 'suốt ngày, cả ngày';
UPDATE public.dictionary_words SET example_hanzi = '她從一名學生成為了知名的作家。', example_pinyin = 'tā cóng yì míng xué shēng chéng wéi le zhī míng de zuò jiā。', example_vietnamese = 'Cô ấy từ một học sinh trở thành một nhà văn nổi tiếng.' WHERE level = 'B2' AND hanzi = '成為' AND pinyin = 'chéngwéi' AND vietnamese = 'trở thành. biến thành';
UPDATE public.dictionary_words SET example_hanzi = '老師今天教了我們幾個常用的成語。', example_pinyin = 'lǎo shī jīn tiān jiào le wǒ men jǐ gè cháng yòng de chéng yǔ。', example_vietnamese = 'Hôm nay thầy giáo dạy chúng tôi vài thành ngữ thông dụng.' WHERE level = 'B2' AND hanzi = '成語' AND pinyin = 'chéngyŭ' AND vietnamese = 'thành ngữ';
UPDATE public.dictionary_words SET example_hanzi = '我們決定乘火車去南部旅行。', example_pinyin = 'wǒ men jué dìng chéng huǒ chē qù nán bù lǚ xíng。', example_vietnamese = 'Chúng tôi quyết định đi tàu hỏa xuống miền Nam du lịch.' WHERE level = 'B2' AND hanzi = '乘' AND pinyin = 'chéng' AND vietnamese = 'đáp, đi';
UPDATE public.dictionary_words SET example_hanzi = '這班公車上擠滿了乘客。', example_pinyin = 'zhè bān gōng chē shàng jǐ mǎn le chéng kè。', example_vietnamese = 'Chuyến xe buýt này chật kín hành khách.' WHERE level = 'B2' AND hanzi = '乘客' AND pinyin = 'chéngkè' AND vietnamese = 'hành khách';
UPDATE public.dictionary_words SET example_hanzi = '他態度誠懇地向老闆道歉。', example_pinyin = 'tā tài dù chéng kěn de xiàng lǎo bǎn dào qiàn。', example_vietnamese = 'Anh ấy với thái độ chân thành xin lỗi ông chủ.' WHERE level = 'B2' AND hanzi = '誠懇' AND pinyin = 'chéngkěn' AND vietnamese = 'thành khẩn, chân thành';
UPDATE public.dictionary_words SET example_hanzi = '這份禮物雖然不貴，卻代表了他的誠意。', example_pinyin = 'zhè fèn lǐ wù suī rán bú guì， què dài biǎo le tā de chéng yì。', example_vietnamese = 'Món quà này tuy không đắt tiền nhưng thể hiện tấm lòng thành của anh ấy.' WHERE level = 'B2' AND hanzi = '誠意' AND pinyin = 'chéngyì' AND vietnamese = 'thành ý, lòng thành';
UPDATE public.dictionary_words SET example_hanzi = '這幅畫呈現出畫家內心的孤獨。', example_pinyin = 'zhè fú huà chéng xiàn chū huà jiā nèi xīn de gū dú。', example_vietnamese = 'Bức tranh này thể hiện nỗi cô đơn trong nội tâm của họa sĩ.' WHERE level = 'B2' AND hanzi = '呈現' AND pinyin = 'chéngxiàn' AND vietnamese = 'lộ ra, phơi bày ra';
UPDATE public.dictionary_words SET example_hanzi = '申請護照需要按照一定的程序辦理。', example_pinyin = 'shēn qǐng hù zhào xū yào àn zhào yí dìng de chéng xù bàn lǐ。', example_vietnamese = 'Xin cấp hộ chiếu cần phải làm theo một trình tự nhất định.' WHERE level = 'B2' AND hanzi = '程序' AND pinyin = 'chéngxù' AND vietnamese = 'trình tự';
UPDATE public.dictionary_words SET example_hanzi = '做人太老實，有時候會吃虧。', example_pinyin = 'zuò rén tài lǎo shí， yǒu shí hòu huì chī kuī。', example_vietnamese = 'Sống quá thật thà, đôi khi sẽ bị chịu thiệt.' WHERE level = 'B2' AND hanzi = '吃虧' AND pinyin = 'chīkuī' AND vietnamese = 'chịu thiệt';
UPDATE public.dictionary_words SET example_hanzi = '他遲了半個小時才到。', example_pinyin = 'tā chí le bàn gè xiǎo shí cái dào。', example_vietnamese = 'Anh ấy trễ nửa tiếng mới đến.' WHERE level = 'B2' AND hanzi = '遲' AND pinyin = 'chí' AND vietnamese = 'chậm, trể';
UPDATE public.dictionary_words SET example_hanzi = '這個祕密遲早會被大家發現的。', example_pinyin = 'zhè gè mì mì chí zǎo huì bèi dà jiā fā xiàn de。', example_vietnamese = 'Bí mật này sớm muộn gì cũng sẽ bị mọi người phát hiện.' WHERE level = 'B2' AND hanzi = '遲早' AND pinyin = 'chízăo' AND vietnamese = 'không sớm thì muộn';
UPDATE public.dictionary_words SET example_hanzi = '買衣服前最好先量好自己的尺寸。', example_pinyin = 'mǎi yī fu qián zuì hǎo xiān liáng hǎo zì jǐ de chǐ cùn。', example_vietnamese = 'Trước khi mua áo tốt nhất nên đo trước số đo của mình.' WHERE level = 'B2' AND hanzi = '尺寸' AND pinyin = 'chĭcùn' AND vietnamese = 'kích cỡ, kích thước';
UPDATE public.dictionary_words SET example_hanzi = '這隻小鳥的翅膀受傷了，飛不起來。', example_pinyin = 'zhè zhī xiǎo niǎo de chì bǎng shòu shāng le， fēi bù qǐ lái。', example_vietnamese = 'Đôi cánh của chú chim nhỏ này bị thương, không bay lên được.' WHERE level = 'B2' AND hanzi = '翅膀' AND pinyin = 'chìbăng' AND vietnamese = 'cánh (chim, côn trùng)';
UPDATE public.dictionary_words SET example_hanzi = '洗完澡後記得把浴室沖乾淨。', example_pinyin = 'xǐ wán zǎo hòu jì de bǎ yù shì chōng gān jìng。', example_vietnamese = 'Tắm xong nhớ xả nước dội sạch phòng tắm.' WHERE level = 'B2' AND hanzi = '沖' AND pinyin = 'chōng' AND vietnamese = 'xông lên';
UPDATE public.dictionary_words SET example_hanzi = '這件事我們已經有了充分的準備。', example_pinyin = 'zhè jiàn shì wǒ men yǐ jīng yǒu le chōng fèn de zhǔn bèi。', example_vietnamese = 'Việc này chúng tôi đã có sự chuẩn bị đầy đủ.' WHERE level = 'B2' AND hanzi = '充分/份' AND pinyin = 'chōngfèn' AND vietnamese = 'đầy đủ, trọn vẹn';
UPDATE public.dictionary_words SET example_hanzi = '這座城市充滿了歷史的痕跡。', example_pinyin = 'zhè zuò chéng shì chōng mǎn le lì shǐ de hén jì。', example_vietnamese = 'Thành phố này tràn đầy dấu vết của lịch sử.' WHERE level = 'B2' AND hanzi = '充滿' AND pinyin = 'chōngmăn' AND vietnamese = 'lấp đầy';
UPDATE public.dictionary_words SET example_hanzi = '睡眠充足才能保持良好的精神狀態。', example_pinyin = 'shuì mián chōng zú cái néng bǎo chí liáng hǎo de jīng shén zhuàng tài。', example_vietnamese = 'Ngủ đủ giấc mới có thể duy trì trạng thái tinh thần tốt.' WHERE level = 'B2' AND hanzi = '充足' AND pinyin = 'chōngzú' AND vietnamese = 'đầy đủ';
UPDATE public.dictionary_words SET example_hanzi = '這篇報告寫得不好，得重寫一次。', example_pinyin = 'zhè piān bào gào xiě de bù hǎo， děi zhòng xiě yí cì。', example_vietnamese = 'Bản báo cáo này viết không tốt, phải viết lại một lần nữa.' WHERE level = 'B2' AND hanzi = '重' AND pinyin = 'chóng' AND vietnamese = 'nặng';
UPDATE public.dictionary_words SET example_hanzi = '很多年輕人崇拜這位歌手。', example_pinyin = 'hěn duō nián qīng rén chóng bài zhè wèi gē shǒu。', example_vietnamese = 'Rất nhiều người trẻ hâm mộ, sùng bái ca sĩ này.' WHERE level = 'B2' AND hanzi = '崇拜' AND pinyin = 'chóngbài' AND vietnamese = 'tôn thờ, sùng bái';
UPDATE public.dictionary_words SET example_hanzi = '他為了理想犧牲自己，精神十分崇高。', example_pinyin = 'tā wèi le lǐ xiǎng xī shēng zì jǐ， jīng shén shí fēn chóng gāo。', example_vietnamese = 'Anh ấy vì lý tưởng mà hy sinh bản thân, tinh thần vô cùng cao thượng.' WHERE level = 'B2' AND hanzi = '崇高' AND pinyin = 'chónggāo' AND vietnamese = 'cao thượng, cao quý';
UPDATE public.dictionary_words SET example_hanzi = '鑰匙放在書桌的抽屜裡。', example_pinyin = 'yào shi fàng zài shū zhuō de chōu tì lǐ。', example_vietnamese = 'Chìa khóa để trong ngăn kéo bàn học.' WHERE level = 'B2' AND hanzi = '抽屜' AND pinyin = 'chōuti' AND vietnamese = 'ngắn kéo, két';
UPDATE public.dictionary_words SET example_hanzi = '孩子的教育問題讓她愁得睡不著。', example_pinyin = 'hái zi de jiào yù wèn tí ràng tā chóu de shuì bu zháo。', example_vietnamese = 'Vấn đề giáo dục con cái khiến cô ấy lo lắng đến mất ngủ.' WHERE level = 'B2' AND hanzi = '愁' AND pinyin = 'chóu' AND vietnamese = 'ưu sầu, lo âu';
UPDATE public.dictionary_words SET example_hanzi = '太陽出來了，天氣終於變晴朗。', example_pinyin = 'tài yáng chū lái le， tiān qì zhōng yú biàn qíng lǎng。', example_vietnamese = 'Mặt trời đã ló ra, thời tiết cuối cùng cũng trở nên quang đãng.' WHERE level = 'B2' AND hanzi = '出' AND pinyin = 'chū' AND vietnamese = 'ra, xuất, đến';
UPDATE public.dictionary_words SET example_hanzi = '這個地區主要出產茶葉和水果。', example_pinyin = 'zhè gè dì qū zhǔ yào chū chǎn chá yè hé shuǐ guǒ。', example_vietnamese = 'Khu vực này chủ yếu sản xuất trà và trái cây.' WHERE level = 'B2' AND hanzi = '出產' AND pinyin = 'chūchăn' AND vietnamese = 'xuất bản';
UPDATE public.dictionary_words SET example_hanzi = '旅客辦好手續後就可以出境了。', example_pinyin = 'lǚ kè bàn hǎo shǒu xù hòu jiù kě yǐ chū jìng le。', example_vietnamese = 'Sau khi làm xong thủ tục, hành khách có thể xuất cảnh.' WHERE level = 'B2' AND hanzi = '出境' AND pinyin = 'chūjìng' AND vietnamese = 'xuất cảnh';
UPDATE public.dictionary_words SET example_hanzi = '這句話太尷尬了，他實在難以出口。', example_pinyin = 'zhè jù huà tài gān gà le， tā shí zài nán yǐ chū kǒu。', example_vietnamese = 'Câu này ngại quá, anh ấy thật sự khó mà nói ra miệng.' WHERE level = 'B2' AND hanzi = '出口' AND pinyin = 'chūkŏu' AND vietnamese = 'mở miệng, nói';
UPDATE public.dictionary_words SET example_hanzi = '她在這次比賽中表現得非常出色。', example_pinyin = 'tā zài zhè cì bǐ sài zhōng biǎo xiàn de fēi cháng chū sè。', example_vietnamese = 'Cô ấy đã thể hiện vô cùng xuất sắc trong cuộc thi lần này.' WHERE level = 'B2' AND hanzi = '出色' AND pinyin = 'chūsè' AND vietnamese = 'xuất sắc';
UPDATE public.dictionary_words SET example_hanzi = '他出身於一個普通的農民家庭。', example_pinyin = 'tā chū shēn yú yí gè pǔ tōng de nóng mín jiā tíng。', example_vietnamese = 'Anh ấy xuất thân từ một gia đình nông dân bình thường.' WHERE level = 'B2' AND hanzi = '出身' AND pinyin = 'chūshēn' AND vietnamese = 'xuất thân';
UPDATE public.dictionary_words SET example_hanzi = '工地昨天出事了，一名工人受傷送醫。', example_pinyin = 'gōng dì zuó tiān chū shì le， yì míng gōng rén shòu shāng sòng yī。', example_vietnamese = 'Công trường hôm qua xảy ra sự cố, một công nhân bị thương phải đưa đi bệnh viện.' WHERE level = 'B2' AND hanzi = '出事' AND pinyin = 'chūshì' AND vietnamese = 'xảy ra sự cố';
UPDATE public.dictionary_words SET example_hanzi = '這棟房子已經出售了。', example_pinyin = 'zhè dòng fáng zi yǐ jīng chū shòu le。', example_vietnamese = 'Căn nhà này đã được bán rồi.' WHERE level = 'B2' AND hanzi = '出售' AND pinyin = 'chūshòu' AND vietnamese = 'bán ra';
UPDATE public.dictionary_words SET example_hanzi = '董事長親自出席了這場記者會。', example_pinyin = 'dǒng shì zhǎng qīn zì chū xí le zhè chǎng jì zhě huì。', example_vietnamese = 'Chủ tịch hội đồng quản trị đã đích thân tham dự buổi họp báo này.' WHERE level = 'B2' AND hanzi = '出席' AND pinyin = 'chūxí' AND vietnamese = 'dự họp, tham dự hội nghị';
UPDATE public.dictionary_words SET example_hanzi = '醫生說他再觀察兩天就可以出院了。', example_pinyin = 'yī shēng shuō tā zài guān chá liǎng tiān jiù kě yǐ chū yuàn le。', example_vietnamese = 'Bác sĩ nói theo dõi thêm hai ngày nữa là anh ấy có thể xuất viện.' WHERE level = 'B2' AND hanzi = '出院' AND pinyin = 'chūyuàn' AND vietnamese = 'ra viện, xuất viện';